INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kettleofketchup/DraftForge/frontend-dev-guidelines', 'community', 'kettleofketchup', 'DraftForge', 'kettleofketchup/DraftForge', 'frontend-dev-guidelines', 0, 0, 54, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:33.718Z', 'e8187169648aa60b3828fde643b0046a343cff7984887e40c3966c791efcc7c8', '{"id":"kettleofketchup/DraftForge/frontend-dev-guidelines","name":"frontend-dev-guidelines","description":{"en":"frontend-dev-guidelines provides a comprehensive guide for modern React development, emphasizing Suspense-based data fetching and performance optimization for developers. It helps developers create efficient and scalable React applications.","zh":"前端开发最佳实践指南，涵盖 React Suspense、lazy loading、TanStack Query 和 MUI v7","ja":"フロントエンド開発ガイドライン - React Suspense、lazy loading、TanStack Query、MUI v7","ko":"프론트엔드 개발 가이드라인 - React Suspense, lazy loading, TanStack Query, MUI v7","es":"Directrices de desarrollo frontend para React con enfoque en Suspense, lazy loading y optimización de rendimiento","fr":"Directives de développement frontend pour React avec un focus sur Suspense, lazy loading et optimisation des performances","de":"Richtlinien für Frontend-Entwicklung mit React und Schwerpunkt auf Suspense, Lazy Loading und Leistungsoptimierung","pt":"Este guia fornece diretrizes para desenvolvedores frontend que desejam criar aplicações React modernas e otimizadas","ru":"Это руководство предоставляет рекомендации для frontend-разработчиков, которые хотят создавать современные и оптимизированные приложения React с помощью ИИ Агентов","ar":"هذا الدليل يوفر إرشادات لتطوير الواجهة الأمامية لإنشاء تطبيقات React الحديثة والمحسنة مع الأدوات الذكية"},"seo":{"title":{"en":"frontend-dev-guidelines: Modern React Development Setup G...","zh":"前端开发最佳实践指南 - React 开发设置指南","ja":"フロントエンド開発ガイドライン - React 開発ベストプラクティス","ko":"프론트엔드 개발 가이드라인 - React 개발 설정 가이드","es":"Guía de configuración para frontend-dev-guidelines con React","fr":"Guide de mise en place des directives de développement fr...","de":"Einrichtungsleitfaden für frontend-dev-guidelines mit React","pt":"Guia de Configuração para Desenvolvedores Frontend com React","ru":"Руководство по настройке frontend-разработки с React и ИИ...","ar":"دليل إعداد وتطوير الواجهة الأمامية مع React والأدوات الذكية"},"description":{"en":"Unlock efficient React development with frontend-dev-guidelines! Learn how to optimize performance, organize code, and master Suspense-based data fetching - ...","zh":"了解前端开发最佳实践，包括使用 Suspense、lazy loading、TanStack Query 和 MUI v7 进行 React 开发","ja":"フロントエンド開発のベストプラクティスを学ぶ - Suspense、lazy loading、TanStack Query、MUI v7 を使用した React 開発","ko":"프론트엔드 개발 가이드라인을 통해 React 개발을 위한 최신 방법을 배우세요 - Suspense, lazy loading, TanStack Query, MUI v7","es":"Aprende a crear componentes y páginas con Suspense, lazy loading y optimización de rendimiento con nuestras directrices de desarrollo frontend","fr":"Découvrez comment créer des composants et des pages avec Suspense, lazy loading et optimisation des performances avec nos directives de développement frontend","de":"Erfahren Sie, wie Sie Komponenten und Seiten mit Suspense, Lazy Loading und Leistungsoptimierung mit unseren Richtlinien für Frontend-Entwicklung erstellen","pt":"Aprenda a configurar e otimizar seu desenvolvimento frontend com React, Suspense e TanStack Query para melhorar o desempenho da aplicação","ru":"Узнайте, как настроить и оптимизировать frontend-разработку с React, Suspense и TanStack Query для улучшения производительности приложения с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد وتحسين تطوير الواجهة الأمامية باستخدام React و Suspense و TanStack Query لتحسين أداء التطبيق مع الأدوات الذكية"},"definition":{"en":"frontend-dev-guidelines is a set of guidelines for modern React development, focusing on best practices for Suspense-based data fetching, lazy loading, and performance optimization.","zh":"前端开发最佳实践指南是一套用于 React 开发的指南，涵盖 Suspense、lazy loading 等","ja":"フロントエンド開発ガイドラインは、React 開発のためのガイドラインで、Suspense、lazy loading などを含みます","ko":"프론트엔드 개발 가이드라인은 React 개발을 위한 가이드라인으로 Suspense, lazy loading 등을 포함합니다","es":"¿Qué es frontend-dev-guidelines? Es un conjunto de directrices para desarrollar aplicaciones frontend con React de manera eficiente","fr":"Qu''est-ce que frontend-dev-guidelines ? C''est un ensemble de directives pour développer des applications frontend avec React de manière efficace","de":"Was sind frontend-dev-guidelines? Es ist ein Satz von Richtlinien für die effiziente Entwicklung von Frontend-Anwendungen mit React","pt":"O que é desenvolvimento frontend com React? É uma abordagem para criar aplicações web modernas e responsivas","ru":"Что такое frontend-разработка с React? Это подход к созданию современных и адаптивных веб-приложений с помощью ИИ Агентов","ar":"ما هو تطوير الواجهة الأمامية مع React؟ إنه نهج لإنشاء تطبيقات ويب حديثة ومتجاوبة مع الأدوات الذكية"},"features":{"en":["Supports Suspense-based data fetching with TanStack Query","Enables lazy loading for efficient component rendering","Provides guidance on proper file organization for React projects","Optimizes performance using proven React development techniques","Integrates with MUI v7 for styling components","Follows TypeScript best practices for robust code development"],"zh":["使用 Suspense 进行数据获取","实现 lazy loading 优化性能","使用 TanStack Query 进行数据管理","使用 MUI v7 进行组件样式化","优化前端代码组织","遵循 TypeScript 最佳实践"],"ja":["Suspense を使用したデータ取得","lazy loading を使用したパフォーマンス最適化","TanStack Query を使用したデータ管理","MUI v7 を使用したコンポーネントスタイリング","フロントエンドコードの最適化","TypeScript のベストプラクティスに従った開発"],"ko":["Suspense를 사용한 데이터 가져오기","lazy loading을 사용한 성능 최적화","TanStack Query를 사용한 데이터 관리","MUI v7를 사용한 컴포넌트 스타일링","프론트엔드 코드 최적화","TypeScript 최선의 관행을 따르는 개발"],"es":["Uso de Suspense para la carga de datos","Implementación de lazy loading para mejorar el rendimiento","Organización de archivos y código con TypeScript","Uso de TanStack Query para la carga de datos","Configuración de rutas con TanStack Router","Estilos de componentes con MUI v7"],"fr":["Utilisation de Suspense pour le chargement de données","Mise en œuvre du lazy loading pour améliorer les performances","Organisation de fichiers et de code avec TypeScript","Utilisation de TanStack Query pour le chargement de données","Configuration des routes avec TanStack Router","Styles de composants avec MUI v7"],"de":["Verwendung von Suspense für die Datenladung","Implementierung von Lazy Loading zur Leistungsverbesserung","Organisation von Dateien und Code mit TypeScript","Verwendung von TanStack Query für die Datenladung","Konfiguration von Routen mit TanStack Router","Stile von Komponenten mit MUI v7"],"pt":["Utilização de Suspense para busca de dados","Otimização de desempenho com lazy loading","Organização de código com boas práticas de TypeScript","Integração com TanStack Query para busca de dados","Utilização de MUI v7 para estilização de componentes","Configuração de rotas com TanStack Router"],"ru":["Использование Suspense для запроса данных","Оптимизация производительности с помощью lazy loading","Организация кода с помощью лучших практик TypeScript","Интеграция с TanStack Query для запроса данных","Использование MUI v7 для стилизации компонентов","Настройка маршрутов с помощью TanStack Router и ИИ Агентов"],"ar":["استخدام Suspense لاستعلام البيانات","تحسين الأداء مع تحميل الكسل","تنظيم الكود مع أفضل الممارسات ل TypeScript","التكامل مع TanStack Query لاستعلام البيانات","استخدام MUI v7 لتنسيق المكونات","تكوين المسارات مع TanStack Router والأدوات الذكية"]},"keywords":{"en":["how to use frontend-dev-guidelines","frontend-dev-guidelines tutorial","React development best practices","Suspense-based data fetching","frontend-dev-guidelines vs create-react-app","frontend-dev-guidelines setup guide","frontend-dev-guidelines installation","modern React development guidelines","performance optimization in React","frontend-dev-guidelines alternative"],"zh":["React 开发最佳实践","前端开发指南","Suspense 数据获取","lazy loading 优化","TanStack Query","MUI v7 组件样式","TypeScript 最佳实践","前端代码组织"],"ja":["React 開発ベストプラクティス","フロントエンド開発ガイドライン","Suspense データ取得","lazy loading パフォーマンス最適化","TanStack Query","MUI v7 コンポーネントスタイリング","TypeScript ベストプラクティス","フロントエンドコード最適化"],"ko":["React 개발 가이드라인","프론트엔드 개발 가이드","Suspense 데이터 가져오기","lazy loading 성능 최적화","TanStack Query","MUI v7 컴포넌트 스타일링","TypeScript 최선의 관행","프론트엔드 코드 최적화"],"es":["desarrollo frontend","React","Suspense","lazy loading","optimización de rendimiento","TypeScript","TanStack Query","TanStack Router","MUI v7","directrices de desarrollo frontend"],"fr":["développement frontend","React","Suspense","lazy loading","optimisation des performances","TypeScript","TanStack Query","TanStack Router","MUI v7","directives de développement frontend"],"de":["Frontend-Entwicklung","React","Suspense","Lazy Loading","Leistungsoptimierung","TypeScript","TanStack Query","TanStack Router","MUI v7","Richtlinien für Frontend-Entwicklung"],"pt":["desenvolvimento frontend","React","Suspense","TanStack Query","lazy loading","TypeScript","MUI v7","TanStack Router","otimização de desempenho","desenvolvedores frontend"],"ru":["frontend-разработка","React","Suspense","TanStack Query","lazy loading","TypeScript","MUI v7","TanStack Router","оптимизация производительности","ИИ Агенты","frontend-разработчики"],"ar":["تطوير الواجهة الأمامية","React","Suspense","TanStack Query","تحميل الكسل","TypeScript","MUI v7","TanStack Router","تحسين الأداء","الأدوات الذكية","مطورو الواجهة الأمامية"]}},"owner":"kettleofketchup","repo":"DraftForge","repoPath":"kettleofketchup/DraftForge","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"frontend-dev-guidelines","description":"Frontend development guidelines for React/TypeScript applications. Modern patterns including Suspense, lazy loading, useSuspenseQuery, file organization with features directory, MUI v7 styling, TanStack Router, performance optimization, and TypeScript best practices. Use when creating components, pages, features, fetching data, styling, routing, or working with frontend code.","bodyPreview":"# Frontend Development Guidelines\n\n## Purpose\n\nComprehensive guide for modern React development, emphasizing Suspense-based data fetching, lazy loading, proper file organization, and performance optimization.\n\n## When to Use This Skill\n\n- Creating new components or pages\n- Building new features\n- Fetching data with TanStack Query\n- Setting up routing with TanStack Router\n- Styling components with MUI v7\n- Performance optimization\n- Organizing frontend code\n- TypeScript best practices\n\n---\n\n## Qu","body":"# Frontend Development Guidelines\n\n## Purpose\n\nComprehensive guide for modern React development, emphasizing Suspense-based data fetching, lazy loading, proper file organization, and performance optimization.\n\n## When to Use This Skill\n\n- Creating new components or pages\n- Building new features\n- Fetching data with TanStack Query\n- Setting up routing with TanStack Router\n- Styling components with MUI v7\n- Performance optimization\n- Organizing frontend code\n- TypeScript best practices\n\n---\n\n## Quick Start\n\n### New Component Checklist\n\nCreating a component? Follow this checklist:\n\n- [ ] Use `React.FC<Props>` pattern with TypeScript\n- [ ] Lazy load if heavy component: `React.lazy(() => import())`\n- [ ] Wrap in `<SuspenseLoader>` for loading states\n- [ ] Use `useSuspenseQuery` for data fetching\n- [ ] Import aliases: `@/`, `~types`, `~components`, `~features`\n- [ ] Styles: Inline if <100 lines, separate file if >100 lines\n- [ ] Use `useCallback` for event handlers passed to children\n- [ ] Default export at bottom\n- [ ] No early returns with loading spinners\n- [ ] Use `useMuiSnackbar` for user notifications\n\n### New Feature Checklist\n\nCreating a feature? Set up this structure:\n\n- [ ] Create `features/{feature-name}/` directory\n- [ ] Create subdirectories: `api/`, `components/`, `hooks/`, `helpers/`, `types/`\n- [ ] Create API service file: `api/{feature}Api.ts`\n- [ ] Set up TypeScript types in `types/`\n- [ ] Create route in `routes/{feature-name}/index.tsx`\n- [ ] Lazy load feature components\n- [ ] Use Suspense boundaries\n- [ ] Export public API from feature `index.ts`\n\n---\n\n## Import Aliases Quick Reference\n\n| Alias | Resolves To | Example |\n|-------|-------------|---------|\n| `@/` | `src/` | `import { apiClient } from ''@/lib/apiClient''` |\n| `~types` | `src/types` | `import type { User } from ''~types/user''` |\n| `~components` | `src/components` | `import { SuspenseLoader } from ''~components/SuspenseLoader''` |\n| `~features` | `src/features` | `import { authApi } from ''~features/auth''` |\n\nDefined in: [vite.config.ts](../../vite.config.ts) lines 180-185\n\n---\n\n## Common Imports Cheatsheet\n\n```typescript\n// React & Lazy Loading\nimport React, { useState, useCallback, useMemo } from ''react'';\nconst Heavy = React.lazy(() => import(''./Heavy''));\n\n// MUI Components\nimport { Box, Paper, Typography, Button, Grid } from ''@mui/material'';\nimport type { SxProps, Theme } from ''@mui/material'';\n\n// TanStack Query (Suspense)\nimport { useSuspenseQuery, useQueryClient } from ''@tanstack/react-query'';\n\n// TanStack Router\nimport { createFileRoute } from ''@tanstack/react-router'';\n\n// Project Components\nimport { SuspenseLoader } from ''~components/SuspenseLoader'';\n\n// Hooks\nimport { useAuth } from ''@/hooks/useAuth'';\nimport { useMuiSnackbar } from ''@/hooks/useMuiSnackbar'';\n\n// Types\nimport type { Post } from ''~types/post'';\n```\n\n---\n\n## Topic Guides\n\n### 🎨 Component Patterns\n\n**Modern React components use:**\n- `React.FC<Props>` for type safety\n- `React.lazy()` for code splitting\n- `SuspenseLoader` for loading states\n- Named const + default export pattern\n\n**Key Concepts:**\n- Lazy load heavy components (DataGrid, charts, editors)\n- Always wrap lazy components in Suspense\n- Use SuspenseLoader component (with fade animation)\n- Component structure: Props → Hooks → Handlers → Render → Export\n\n**[📖 Complete Guide: resources/component-patterns.md](resources/component-patterns.md)**\n\n---\n\n### 📊 Data Fetching\n\n**PRIMARY PATTERN: useSuspenseQuery**\n- Use with Suspense boundaries\n- Cache-first strategy (check grid cache before API)\n- Replaces `isLoading` checks\n- Type-safe with generics\n\n**API Service Layer:**\n- Create `features/{feature}/api/{feature}Api.ts`\n- Use `apiClient` axios instance\n- Centralized methods per feature\n- Route format: `/form/route` (NOT `/api/form/route`)\n\n**[📖 Complete Guide: resources/data-fetching.md](resources/data-fetching.md)**\n\n---\n\n### 📁 File Organization\n\n**features/ vs components/:**\n- `features/`: Domain-specific (posts, comments, auth)\n- `components/`: Truly reusable (SuspenseLoader, CustomAppBar)\n\n**Feature Subdirectories:**\n```\nfeatures/\n  my-feature/\n    api/          # API service layer\n    components/   # Feature components\n    hooks/        # Custom hooks\n    helpers/      # Utility functions\n    types/        # TypeScript types\n```\n\n**[📖 Complete Guide: resources/file-organization.md](resources/file-organization.md)**\n\n---\n\n### 🎨 Styling\n\n**Inline vs Separate:**\n- <100 lines: Inline `const styles: Record<string, SxProps<Theme>>`\n- >100 lines: Separate `.styles.ts` file\n\n**Primary Method:**\n- Use `sx` prop for MUI components\n- Type-safe with `SxProps<Theme>`\n- Theme access: `(theme) => theme.palette.primary.main`\n\n**MUI v7 Grid:**\n```typescript\n<Grid size={{ xs: 12, md: 6 }}>  // ✅ v7 syntax\n<Grid xs={12} md={6}>             // ❌ Old syntax\n```\n\n**[📖 Complete Guide: resources/styling-guide.md](resources/styling-guide.md)**\n\n---\n\n### 🛣️ Routing\n\n**TanStack Router - Folder-Based:**\n- Directory: `routes/my-route/index.tsx`\n- Lazy load components\n- Use `createFileRoute`\n- Breadcrumb data in loader\n\n**Example:**\n```typescript\nimport { createFileRoute } from ''@tanstack/react-router'';\nimport { lazy } from ''react'';\n\nconst MyPage = lazy(() => import(''@/features/my-feature/components/MyPage''));\n\nexport const Route = createFileRoute(''/my-route/'')({\n    component: MyPage,\n    loader: () => ({ crumb: ''My Route'' }),\n});\n```\n\n**[📖 Complete Guide: resources/routing-guide.md](resources/routing-guide.md)**\n\n---\n\n### ⏳ Loading & Error States\n\n**CRITICAL RULE: No Early Returns**\n\n```typescript\n// ❌ NEVER - Causes layout shift\nif (isLoading) {\n    return <LoadingSpinner />;\n}\n\n// ✅ ALWAYS - Consistent layout\n<SuspenseLoader>\n    <Content />\n</SuspenseLoader>\n```\n\n**Why:** Prevents Cumulative Layout Shift (CLS), better UX\n\n**Error Handling:**\n- Use `useMuiSnackbar` for user feedback\n- NEVER `react-toastify`\n- TanStack Query `onError` callbacks\n\n**[📖 Complete Guide: resources/loading-and-error-states.md](resources/loading-and-error-states.md)**\n\n---\n\n### ⚡ Performance\n\n**Optimization Patterns:**\n- `useMemo`: Expensive computations (filter, sort, map)\n- `useCallback`: Event handlers passed to children\n- `React.memo`: Expensive components\n- Debounced search (300-500ms)\n- Memory leak prevention (cleanup in useEffect)\n\n**[📖 Complete Guide: resources/performance.md](resources/performance.md)**\n\n---\n\n### 📘 TypeScript\n\n**Standards:**\n- Strict mode, no `any` type\n- Explicit return types on functions\n- Type imports: `import type { User } from ''~types/user''`\n- Component prop interfaces with JSDoc\n\n**[📖 Complete Guide: resources/typescript-standards.md](resources/typescript-standards.md)**\n\n---\n\n### 🔧 Common Patterns\n\n**Covered Topics:**\n- React Hook Form with Zod validation\n- DataGrid wrapper contracts\n- Dialog component standards\n- `useAuth` hook for current user\n- Mutation patterns with cache invalidation\n\n**[📖 Complete Guide: resources/common-patterns.md](resources/common-patterns.md)**\n\n---\n\n### 👤 User Avatars\n\n**ALWAYS use `AvatarUrl` helper** for user avatars - handles empty strings, Discord IDs, and fallback generation.\n\n```typescript\nimport { AvatarUrl } from \"~/components/user/avatar\";\n<img src={AvatarUrl(user)} />\n```\n\n**[📖 Complete Guide: resources/user-avatar.md](resources/user-avatar.md)**\n\n---\n\n### 📚 Complete Examples\n\n**Full working examples:**\n- Modern component with all patterns\n- Complete feature structure\n- API service layer\n- Route with lazy loading\n- Suspense + useSuspenseQuery\n- Form with validation\n\n**[📖 Complete Guide: resources/complete-examples.md](resources/complete-examples.md)**\n\n---\n\n## Navigation Guide\n\n| Need to... | Read this resource |\n|------------|-------------------|\n| Create a component | [component-patterns.md](resources/component-patterns.md) |\n| Fetch data | [data-fetching.md](resources/data-fetching.md) |\n| Organize files/folders | [file-organization.md](resources/file-organization.md) |\n| Style components | [styling-guide.md](resources/styling-guide.md) |\n| Set up routing | [routing-guide.md](resources/routing-guide.md) |\n| Handle loading/errors | [loading-and-error-states.md](resources/loading-and-error-states.md) |\n| Optimize performance | [performance.md](resources/performance.md) |\n| TypeScript types | [typescript-standards.md](resources/typescript-standards.md) |\n| Forms/Auth/DataGrid | [common-patterns.md](resources/common-patterns.md) |\n| Display user avatars | [user-avatar.md](resources/user-avatar.md) |\n| See full examples | [complete-examples.md](resources/complete-examples.md) |\n\n---\n\n## Core Principles\n\n1. **Lazy Load Everything Heavy**: Routes, DataGrid, charts, editors\n2. **Suspense for Loading**: Use SuspenseLoader, not early returns\n3. **useSuspenseQuery**: Primary data fetching pattern for new code\n4. **Features are Organized**: api/, components/, hooks/, helpers/ subdirs\n5. **Styles Based on Size**: <100 inline, >100 separate\n6. **Import Aliases**: Use @/, ~types, ~components, ~features\n7. **No Early Returns**: Prevents layout shift\n8. **useMuiSnackbar**: For all user notifications\n\n---\n\n## Quick Reference: File Structure\n\n```\nsrc/\n  features/\n    my-feature/\n      api/\n        myFeatureApi.ts       # API service\n      components/\n        MyFeature.tsx         # Main component\n        SubComponent.tsx      # Related components\n      hooks/\n        useMyFeature.ts       # Custom hooks\n        useSuspenseMyFeature.ts  # Suspense hooks\n      helpers/\n        myFeatureHelpers.ts   # Utilities\n      types/\n        index.ts              # TypeScript types\n      index.ts                # Public exports\n\n  components/\n    SuspenseLoader/\n      SuspenseLoader.tsx      # Reusable loader\n    CustomAppBar/\n      CustomAppBar.tsx        # Reusable app bar\n\n  routes/\n    my-route/\n      index.tsx               # Route component\n      create/\n        index.tsx             # Nested route\n```\n\n---\n\n## Modern Component Template (Quick Copy)\n\n```typescript\nimport React, { useState, useCallback } from ''react'';\nimport { Box, Paper } from ''@mui/material'';\nimport { useSuspenseQuery } from ''@tanstack/react-query'';\nimport { featureApi } from ''../api/featureApi'';\nimport type { FeatureData } from ''~types/feature'';\n\ninterface MyComponentProps {\n    id: number;\n    onAction?: () => void;\n}\n\nexport const MyComponent: React.FC<MyComponentProps> = ({ id, onAction }) => {\n    const [state, setState] = useState<string>('''');\n\n    const { data } = useSuspenseQuery({\n        queryKey: [''feature'', id],\n        queryFn: () => featureApi.getFeature(id),\n    });\n\n    const handleAction = useCallback(() => {\n        setState(''updated'');\n        onAction?.();\n    }, [onAction]);\n\n    return (\n        <Box sx={{ p: 2 }}>\n            <Paper sx={{ p: 3 }}>\n                {/* Content */}\n            </Paper>\n        </Box>\n    );\n};\n\nexport default MyComponent;\n```\n\nFor complete examples, see [resources/complete-examples.md](resources/complete-examples.md)\n\n---\n\n## Related Skills\n\n- **error-tracking**: Error tracking with Sentry (applies to frontend too)\n- **backend-dev-guidelines**: Backend API patterns that frontend consumes\n\n---\n\n**Skill Status**: Modular structure with progressive loading for optimal context management\n"},"lastSynced":"2026-03-08T02:02:33.718Z","agentAnalysis":{"suitability":{"en":"Perfect for React Development Agents needing comprehensive frontend development guidelines and Suspense-based data fetching capabilities.","zh":"非常适合需要全面前端开发指南和基于Suspense的数据获取能力的React开发代理。","ja":"React開発エージェントが包括的なフロントエンド開発ガイドラインとSuspenseベースのデータ取得機能を必要とする場合に最適です。","ko":"전체적인 프론트엔드 개발 가이드라인과 Suspense 기반의 데이터 가져오기 기능이 필요한 React 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de React que necesitan directrices de desarrollo de frontend integrales y capacidades de recuperación de datos basadas en Suspense.","fr":"Parfait pour les agents de développement React qui ont besoin de directives de développement frontend complètes et de capacités de récupération de données basées sur Suspense.","de":"Perfekt für React-Entwicklungsagenten, die umfassende Richtlinien für die Frontend-Entwicklung und Suspense-basierte Datenabruf-Funktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento React que precisam de diretrizes abrangentes de desenvolvimento frontend e capacidades de busca de dados baseadas em Suspense.","ru":"Идеально для агентов разработки React, которым необходимы комплексные рекомендации по разработке frontend и возможности получения данных на основе Suspense.","ar":"مثالي لعميل التطوير رياكت الذي يحتاج إلى إرشادات شاملة لتحسين الواجهة الأمامية وقدرات استرجاع البيانات القائمة على سوسبنس."},"recommendation":{"en":"Empowers agents to create efficient and scalable React applications using Suspense-based data fetching, lazy loading, and performance optimization techniques with libraries like TanStack Query and TanStack Router, and styling components with MUI v7.","zh":"赋予代理创建高效且可扩展的React应用程序的能力，使用Suspense基于的数据获取、延迟加载和性能优化技术，结合TanStack Query和TanStack Router等库，并使用MUI v7进行组件样式化。","ja":"Suspenseベースのデータ取得、遅延ローディング、パフォーマンス最適化テクニックを使用して、効率的でスケーラブルなReactアプリケーションを作成するエージェントを可能にします。TanStack QueryやTanStack Routerなどのライブラリと組み合わせて、MUI v7を使用してコンポーネントをスタイリングします。","ko":"에이전트가 Suspense 기반의 데이터 가져오기, 지연 로딩 및 성능 최적화 기술을 사용하여 효율적이고 확장 가능한 React 응용 프로그램을 생성할 수 있도록 합니다. TanStack Query와 TanStack Router 같은 라이브러리와 함께 MUI v7을 사용하여 컴포넌트를 스타일링합니다.","es":"Habilita a los agentes a crear aplicaciones React eficientes y escalables utilizando técnicas de recuperación de datos basadas en Suspense, carga diferida y optimización del rendimiento con bibliotecas como TanStack Query y TanStack Router, y estilizando componentes con MUI v7.","fr":"Permet aux agents de créer des applications React efficaces et évolutives en utilisant des techniques de récupération de données basées sur Suspense, de chargement différé et d''optimisation des performances avec des bibliothèques comme TanStack Query et TanStack Router, et en stylisant des composants avec MUI v7.","de":"Ermöglicht es Agenten, effiziente und skalierbare React-Anwendungen zu erstellen, indem sie Suspense-basierte Datenabruf-, Lazy-Loading- und Leistungsoptimierungstechniken mit Bibliotheken wie TanStack Query und TanStack Router verwenden und Komponenten mit MUI v7 stylen.","pt":"Habilita os agentes a criar aplicativos React eficientes e escaláveis usando busca de dados baseada em Suspense, carregamento lento e técnicas de otimização de desempenho com bibliotecas como TanStack Query e TanStack Router, e estilizando componentes com MUI v7.","ru":"Позволяет агентам создавать эффективные и масштабируемые приложения React, используя получение данных на основе Suspense, ленивую загрузку и методы оптимизации производительности с помощью библиотек, таких как TanStack Query и TanStack Router, а также стилизацию компонентов с помощью MUI v7.","ar":"تمكّن العميل من إنشاء تطبيقات رياكت فعالة وقابلة للتوسعة باستخدام استرجاع البيانات القائمة على سوسبنس والتحميل الكسول وتقنيات تحسين الأداء باستخدام مكتبات مثل TanStack Query وTanStack Router، وتحسين مكونات الواجهة باستخدام MUI v7."},"useCases":{"en":["Building new React features with optimized data fetching","Creating scalable and performant React applications","Implementing Suspense-based data fetching and lazy loading","Setting up routing with TanStack Router","Styling components with MUI v7"],"zh":["使用优化的数据获取构建新的React功能","创建可扩展且高性能的React应用程序","实现基于Suspense的数据获取和延迟加载","使用TanStack Router设置路由","使用MUI v7样式化组件"],"ja":["最適化されたデータ取得を使用して新しいReact機能を構築する","スケーラブルで高パフォーマンスのReactアプリケーションを作成する","Suspenseベースのデータ取得と遅延ローディングを実装する","TanStack Routerを使用してルーティングを設定する","MUI v7を使用してコンポーネントをスタイリングする"],"ko":["최적화된 데이터 가져오기를 사용하여 새로운 React 기능을 구축하는 것","확장 가능하고 고성능의 React 응용 프로그램을 생성하는 것","Suspense 기반의 데이터 가져오기 및 지연 로딩을 구현하는 것","TanStack Router를 사용하여 라우팅을 설정하는 것","MUI v7을 사용하여 컴포넌트를 스타일링하는 것"],"es":["Crear nuevas características de React con recuperación de datos optimizada","Crear aplicaciones React escalables y de alto rendimiento","Implementar recuperación de datos basada en Suspense y carga diferida","Configurar enrutamiento con TanStack Router","Estilizar componentes con MUI v7"],"fr":["Créer de nouvelles fonctionnalités React avec une récupération de données optimisée","Créer des applications React évolutives et performantes","Mettre en œuvre une récupération de données basée sur Suspense et un chargement différé","Configurer le routage avec TanStack Router","Styliser des composants avec MUI v7"],"de":["Erstellen neuer React-Features mit optimierter Datenabruf","Erstellen skalierbarer und leistungsstarker React-Anwendungen","Implementieren von Suspense-basiertem Datenabruf und Lazy-Loading","Einrichten von Routing mit TanStack Router","Stylen von Komponenten mit MUI v7"],"pt":["Construção de novos recursos React com busca de dados otimizada","Criação de aplicativos React escaláveis e de alto desempenho","Implementação de busca de dados baseada em Suspense e carregamento lento","Configuração de roteamento com TanStack Router","Estilização de componentes com MUI v7"],"ru":["Создание новых функций React с оптимизированным получением данных","Создание масштабируемых и производительных приложений React","Реализация получения данных на основе Suspense и ленивой загрузки","Настройка маршрутизации с помощью TanStack Router","Стилизация компонентов с помощью MUI v7"],"ar":["بناء ميزات رياكت جديدة مع استرجاع بيانات محسّن","إنشاء تطبيقات رياكت قابلة للتوسعة وأداء عال","تنفيذ استرجاع البيانات القائمة على سوسبنس والتحميل الكسول","تكوين التوجيه باستخدام TanStack Router","تحسين مكونات الواجهة باستخدام MUI v7"]},"limitations":{"en":["Requires React development environment","Limited to React applications","Dependent on TanStack Query and TanStack Router libraries"],"zh":["需要React开发环境","仅限React应用程序","依赖于TanStack Query和TanStack Router库"],"ja":["React開発環境が必要","Reactアプリケーションに限定される","TanStack QueryとTanStack Routerライブラリに依存する"],"ko":["React 개발 환경이 필요합니다.","React 응용 프로그램으로 제한됩니다.","TanStack Query 및 TanStack Router 라이브러리에 의존합니다."],"es":["Requiere entorno de desarrollo de React","Limitado a aplicaciones de React","Dependiente de las bibliotecas TanStack Query y TanStack Router"],"fr":["Nécessite un environnement de développement React","Limité aux applications React","Dépendant des bibliothèques TanStack Query et TanStack Router"],"de":["Benötigt React-Entwicklungsumgebung","Begrenzt auf React-Anwendungen","Abhängig von den Bibliotheken TanStack Query und TanStack Router"],"pt":["Exige ambiente de desenvolvimento React","Limitado a aplicativos React","Dependente das bibliotecas TanStack Query e TanStack Router"],"ru":["Требует среды разработки React","Ограничен приложениями React","Зависит от библиотек TanStack Query и TanStack Router"],"ar":["يتطلب بيئة تطوير رياكت","محدود بتطبيقات رياكت","يعتمد على مكتبات TanStack Query وTanStack Router"]},"version":4},"contentHash":"e8187169648aa60b3828fde643b0046a343cff7984887e40c3966c791efcc7c8","qualityScore":54}');
