INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kettleofketchup/DraftForge/frontend-dev-guidelines', 'frontend-dev-guidelines', 'kettleofketchup', 'DraftForge', 'community', 'frontend-dev-guidelines kettleofketchup DraftForge community frontend-dev-guidelines provides a comprehensive guide for modern React development, emphasizing Suspense-based data fetching and performance optimization for developers. It helps developers create efficient and scalable React applications. 前端开发最佳实践指南，涵盖 React Suspense、lazy loading、TanStack Query 和 MUI v7 フロントエンド開発ガイドライン - React Suspense、lazy loading、TanStack Query、MUI v7 프론트엔드 개발 가이드라인 - React Suspense, lazy loading, TanStack Query, MUI v7 Directrices de desarrollo frontend para React con enfoque en Suspense, lazy loading y optimización de rendimiento Directives de développement frontend pour React avec un focus sur Suspense, lazy loading et optimisation des performances Richtlinien für Frontend-Entwicklung mit React und Schwerpunkt auf Suspense, Lazy Loading und Leistungsoptimierung Este guia fornece diretrizes para desenvolvedores frontend que desejam criar aplicações React modernas e otimizadas Это руководство предоставляет рекомендации для frontend-разработчиков, которые хотят создавать современные и оптимизированные приложения React с помощью ИИ Агентов هذا الدليل يوفر إرشادات لتطوير الواجهة الأمامية لإنشاء تطبيقات React الحديثة والمحسنة مع الأدوات الذكية how to use frontend-dev-guidelines frontend-dev-guidelines tutorial React development best practices Suspense-based data fetching frontend-dev-guidelines vs create-react-app frontend-dev-guidelines setup guide frontend-dev-guidelines installation modern React development guidelines performance optimization in React frontend-dev-guidelines alternative React 开发最佳实践 前端开发指南 Suspense 数据获取 lazy loading 优化 TanStack Query MUI v7 组件样式 TypeScript 最佳实践 前端代码组织 Supports Suspense-based data fetching with TanStack Query Enables lazy loading for efficient component rendering Provides guidance on proper file organization for React projects Optimizes performance using proven React development techniques Integrates with MUI v7 for styling components Follows TypeScript best practices for robust code development frontend-dev-guidelines is a set of guidelines for modern React development, focusing on best practices for Suspense-based data fetching, lazy loading, and performance optimization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nonzod/drupaldev-claude-skill/drupal-standards', 'community', 'nonzod', 'drupaldev-claude-skill', 'nonzod/drupaldev-claude-skill', 'drupal-standards', 0, 0, 54, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:36.103Z', '0aa609b0613a2dea56b6814692415992c728952de8da5ba041ba65c334d54bc3', '{"id":"nonzod/drupaldev-claude-skill/drupal-standards","name":"drupal-standards","description":{"en":"The drupal-standards skill applies Drupal coding standards for efficient development, benefiting developers who work with PHP files, modules, services, and plugins. It ensures all code follows US English spelling and the Boy Scout Rule.","zh":"Drupal 标准开发指南提供了 Drupal 编码标准和最佳实践，帮助开发者提高开发效率","ja":"Drupal 開発のための AI エージェント設定ガイドでは、Drupal コーディング標準とベストプラクティスを紹介します","ko":"드루팔 개발을 위한 Drupal Standards 설정 가이드는 드루팔 코딩 표준과 모범 사례를 제공하여 개발자에게 도움을 줍니다","es":"Aplicación de normas de codificación de Drupal para un desarrollo eficiente","fr":"Application des normes de codage Drupal pour un développement efficace","de":"Anwendung der Drupal-Coding-Standards für eine effiziente Entwicklung","pt":"O skill drupal-standards ajuda desenvolvedores a seguir as normas de codificação do Drupal, melhorando a qualidade do código","ru":"Навык drupal-standards помогает разработчикам следовать стандартам кодирования Drupal, улучшая качество кода","ar":"المهارة drupal-standards تساعد المبرمجين على اتباع معايير دروبال، مما يحسن جودة الكود"},"seo":{"title":{"en":"drupal-standards: Drupal Coding Standards Setup Guide | A...","zh":"Drupal 标准开发指南","ja":"Drupal 開発のための AI エージェント設定ガイド","ko":"드루팔 개발을 위한 Drupal Standards 설정 가이드","es":"Guía de configuración de Drupal Standards para desarrollo","fr":"Mise en place des normes Drupal pour le développement","de":"Drupal-Standards-Setup-Anleitung für die Entwicklung","pt":"Drupal Standards: Guia de Configuração para Desenvolvedores","ru":"Drupal Стандарты: Руководство по Настройке для Разработчи...","ar":"معايير دروبال: دليل الإعداد لل مبرمجين"},"description":{"en":"Unlock efficient Drupal development with drupal-standards. Learn how to apply version-independent coding standards and best practices for PHP development.","zh":"了解 Drupal 标准开发指南，掌握 Drupal 编码标准和最佳实践，提高开发效率","ja":"Drupal 開発のためのコーディング標準とベストプラクティスを学び、開発効率を向上させる","ko":"드루팔 개발을 위한 Drupal Standards 가이드를 통해 코딩 표준과 모범 사례를 익혀 개발 효율성을 향상시키세요","es":"Aprende a aplicar las normas de codificación de Drupal para un desarrollo eficiente con nuestra guía de configuración","fr":"Découvrez comment appliquer les normes de codage Drupal pour un développement efficace avec notre guide de configuration","de":"Erfahren Sie, wie Sie die Drupal-Coding-Standards für eine effiziente Entwicklung mit unserer Konfigurationsanleitung anwenden","pt":"Aprenda a aplicar as normas de codificação do Drupal para melhorar a qualidade do seu código e aumentar a produtividade","ru":"Узнайте, как применять стандарты кодирования Drupal, чтобы улучшить качество вашего кода и повысить производительность с помощью ИИ Агентов","ar":"تعلم كيفية تطبيق معايير دروبال لتحسين جودة كودك وزيادة الإنتاجية"},"definition":{"en":"drupal-standards is a set of guidelines for Drupal development that ensures all code follows version-independent coding standards, US English spelling, and best practices.","zh":"Drupal 标准是指 Drupal 开发中遵循的编码标准和最佳实践","ja":"Drupal 標準は、Drupal 開発において従うべきコーディング標準とベストプラクティスです","ko":"드루팔 표준은 드루팔 개발에서 따라야 하는 코딩 표준과 모범 사례를 말합니다","es":"Las normas de codificación de Drupal son un conjunto de reglas para escribir código de alta calidad","fr":"Les normes de codage Drupal sont un ensemble de règles pour écrire du code de haute qualité","de":"Die Drupal-Coding-Standards sind eine Sammlung von Regeln für die Erstellung von hochwertigem Code","pt":"O que é drupal-standards? É um conjunto de regras para codificação no Drupal","ru":"Что такое drupal-standards? Это набор правил для кодирования в Drupal","ar":"ما هي معايير دروبال؟ هي مجموعة من القواعد لكتابة الكود في دروبال"},"features":{"en":["Applies Drupal coding standards based on development context","Enforces US English spelling in comments and names","Follows the Boy Scout Rule for code improvement","Supports PHP development for files, modules, services, and plugins","Ensures standards are always-current for new code","Detects context and loads standards for efficient development"],"zh":["遵循 Drupal 编码标准（版本无关）","使用 US 英文拼写在所有注释和名称中","遵循男孩侦探规则：使代码比你发现时更好","支持 PHP 开发（.php 文件、模块、服务、插件）","提供上下文检测和标准加载"],"ja":["Drupal コーディング標準（バージョン非依存）に従う","すべてのコメントと名前で US 英語のスペルを使用する","ボーイスカウトルールに従う：コードをあなたが見つけたときよりも良い状態に残す","PHP 開発（.php ファイル、モジュール、サービス、プラグイン）をサポートする","コンテキスト検出と標準ロードを提供する"],"ko":["드루팔 코딩 표준（버전 무관）을 따름","모든 주석과 이름에서 US 영어拼写 사용","보이스카우트 규칙을 따름：코드를 발견했을 때보다 더 좋은 상태로 оставить","PHP 개발（.php 파일, 모듈, 서비스, 플러그인）을 지원함","콘텍스트 감지와 표준 로드를 제공함"],"es":["Aplicación de normas de codificación de Drupal version-independientes","Uso de inglés estadounidense en comentarios y nombres","Seguimiento de la regla del Boy Scout para mejorar el código","Detección de contexto y carga de normas para PHP","Desarrollo de módulos, servicios y plugins con normas de codificación de Drupal"],"fr":["Application des normes de codage Drupal version-indépendantes","Utilisation de l''anglais américain dans les commentaires et les noms","Suivi de la règle du Boy Scout pour améliorer le code","Détection de contexte et chargement de normes pour PHP","Développement de modules, services et plugins avec les normes de codage Drupal"],"de":["Anwendung von version-unabhängigen Drupal-Coding-Standards","Verwendung von US-Englisch in Kommentaren und Namen","Einhalten der Boy-Scout-Regel für die Verbesserung des Codes","Kontext-Erkennung und Laden von Standards für PHP","Entwicklung von Modulen, Diensten und Plugins mit Drupal-Coding-Standards"],"pt":["Aplicação das normas de codificação do Drupal","Uso de inglês americano em comentários e nomes","Seguimento do princípio do Boy Scout","Detecção de contexto e carregamento de padrões","Suporte a desenvolvimento PHP"],"ru":["Применение стандартов кодирования Drupal","Использование американского английского языка в комментариях и именах","Следование принципу скаута","Обнаружение контекста и загрузка стандартов","Поддержка разработки на PHP с помощью ИИ Агентов"],"ar":["تطبيق معايير دروبال","استخدام اللغة الإنجليزية الأمريكية في التعليقات والأسماء","اتباع مبدأ كشاف","كشف السياق وتحميل المعايير","دعم تطوير PHP"]},"keywords":{"en":["how to use drupal-standards","drupal-standards setup guide","drupal coding standards best practices","drupal-standards vs drupal coding standards","drupal-standards install","what is drupal-standards","drupal-standards alternative","drupal development with drupal-standards","drupal-standards for PHP development"],"zh":["Drupal 标准开发","Drupal 编码标准","PHP 开发","Drupal 模块开发","Drupal 服务开发","Drupal 插件开发","AI 开发工具","Drupal 开发最佳实践"],"ja":["Drupal 開発のための AI エージェント","Drupal コーディング標準","PHP 開発","Drupal モジュール開発","Drupal サービス開発","Drupal プラグイン開発","AI 開発ツール","Drupal 開発ベストプラクティス"],"ko":["드루팔 개발을 위한 AI 에이전트","드루팔 코딩 표준","PHP 개발","드루팔 모듈 개발","드루팔 서비스 개발","드루팔 플러그인 개발","AI 개발 도구","드루팔 개발 모범 사례"],"es":["normas de codificación de Drupal","desarrollo de Drupal","Drupal standards","código de alta calidad","reglas de codificación","Boy Scout Rule","PHP development","módulos de Drupal","servicios de Drupal","plugins de Drupal"],"fr":["normes de codage Drupal","développement de Drupal","Drupal standards","code de haute qualité","règles de codage","Règle du Boy Scout","développement PHP","modules de Drupal","services de Drupal","plugins de Drupal"],"de":["Drupal-Coding-Standards","Drupal-Entwicklung","Drupal-Standards","hochwertiger Code","Codierregeln","Boy-Scout-Regel","PHP-Entwicklung","Drupal-Module","Drupal-Dienste","Drupal-Plugins"],"pt":["drupal standards","normas de codificação drupal","desenvolvimento drupal","codificação php","melhoria de código","produtividade de desenvolvedores","guias de configuração drupal"],"ru":["drupal стандарты","стандарты кодирования drupal","разработка drupal","кодирование php","улучшение кода","производительность разработчиков","руководство по настройке drupal для ИИ Агентов"],"ar":["معايير دروبال","قواعد كتابة الكود دروبال","تطوير دروبال","كتابة كود php","تحسين الكود","إنتاجية المبرمجين","دليل إعداد دروبال"]}},"owner":"nonzod","repo":"drupaldev-claude-skill","repoPath":"nonzod/drupaldev-claude-skill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"drupal-standards","description":"Automatically applies Drupal coding standards when developing PHP modules, JavaScript, CSS, SQL queries, Twig templates, or YAML configs. Activates when creating/editing .php, .js, .css, .sql, .twig, .yml files or when user mentions module, query, template, form, or custom code.","bodyPreview":"# Drupal Coding Standards\n\nApply Drupal coding standards based on the development context.\n\n## Core Principles\n\nFrom `coding_standards/index.md`:\n- All code must follow Drupal coding standards (version-independent)\n- Use US English spelling in all comments and names\n- Standards are \"always-current\" and apply to all new code\n- Follow Boy Scout Rule: leave code better than you found it\n\n## Context Detection & Standard Loading\n\n### PHP Development (.php files, modules, services, plugins)\n\nWhen work","body":"# Drupal Coding Standards\n\nApply Drupal coding standards based on the development context.\n\n## Core Principles\n\nFrom `coding_standards/index.md`:\n- All code must follow Drupal coding standards (version-independent)\n- Use US English spelling in all comments and names\n- Standards are \"always-current\" and apply to all new code\n- Follow Boy Scout Rule: leave code better than you found it\n\n## Context Detection & Standard Loading\n\n### PHP Development (.php files, modules, services, plugins)\n\nWhen working with PHP code, **ALWAYS read these standards FIRST**:\n\n1. **Core Standards**: Read `coding_standards/php/coding.md`\n2. **Documentation**: Read `coding_standards/php/documentation.md`\n3. **Namespaces**: Read `coding_standards/php/namespaces.md`\n4. **PSR-4**: Read `coding_standards/php/psr4.md`\n\nAdditionally, based on specific needs:\n- Creating services → Read `coding_standards/php/naming-services.md`\n- Exception handling → Read `coding_standards/php/exceptions.md`\n- Using placeholders → Read `coding_standards/php/placeholders-delimiters.md`\n- Error handling → Read `coding_standards/php/e_all.md`\n- Documentation examples → Read `coding_standards/php/documentation-examples.md`\n\n### JavaScript Development (.js files)\n\n**ALWAYS read these standards FIRST**:\n\n1. **Core Standards**: Read `coding_standards/javascript/coding.md`\n2. **Documentation**: Read `coding_standards/javascript/documentation.md`\n3. **Best Practices**: Read `coding_standards/javascript/best-practice.md`\n4. **ESLint Config**: Read `coding_standards/javascript/eslint.md`\n\nIf using jQuery:\n- Read `coding_standards/javascript/jquery.md`\n\n### CSS Development (.css, .scss files, styling)\n\n**ALWAYS read these standards FIRST**:\n\n1. **Core Standards**: Read `coding_standards/css/coding.md`\n2. **Formatting**: Read `coding_standards/css/format.md`\n3. **File Organization**: Read `coding_standards/css/file-organization.md`\n4. **Architecture**: Read `coding_standards/css/architecture.md`\n\nFor tool configuration:\n- Read `coding_standards/css/csscomb.md`\n- Read `coding_standards/css/review.md`\n\n### SQL Queries (database operations)\n\n**ALWAYS read these standards FIRST**:\n\n1. **Conventions**: Read `coding_standards/sql/conventions.md`\n2. **Keywords**: Read `coding_standards/sql/keywords.md`\n3. **SELECT Queries**: Read `coding_standards/sql/select-from.md`\n\n### Twig Templates (.twig files)\n\n**ALWAYS read these standards**:\n\n1. **Twig Standards**: Read `coding_standards/twig/coding.md`\n2. **Markup Standards**: Read `coding_standards/markup/style.md`\n\n### YAML Configuration (.yml, .yaml files)\n\n**ALWAYS read**:\n- Read `coding_standards/yaml/configuration-files.md`\n\n### Composer Packages (composer.json)\n\n**ALWAYS read**:\n- Read `coding_standards/composer/package-name.md`\n\n### Accessibility (forms, UI components, interactive elements)\n\n**ALWAYS read**:\n- Read `coding_standards/accessibility/accessibility.md`\n\n### Spelling & General\n\n**ALWAYS apply**:\n- Read `coding_standards/spelling/spelling.md` (US English required)\n\n## Workflow\n\n```\n1. User requests development task\n   ↓\n2. Identify file types/context (PHP, JS, CSS, SQL, etc.)\n   ↓\n3. Read ALL relevant standard files from coding_standards/\n   ↓\n4. Apply standards while writing code\n   ↓\n5. Validate code against standards\n   ↓\n6. Complete task with compliant code\n```\n\n## Multi-Context Tasks\n\nFor tasks involving multiple file types, load **ALL** relevant standards:\n\n**Example: Creating a custom module**\n- PHP standards (module code)\n- JavaScript standards (if includes JS)\n- CSS standards (if includes styling)\n- Twig standards (if includes templates)\n- YAML standards (for .info.yml and config files)\n- Accessibility standards (if includes UI)\n\n## Application Rules\n\n1. **Read First, Write Second**: Always read relevant standards before generating code\n2. **No Assumptions**: Never assume standards—always verify from files\n3. **Exact Compliance**: Follow standards exactly as written\n4. **US English Only**: All comments, variable names, and documentation\n5. **Complete Coverage**: If working with multiple file types, apply all relevant standards\n6. **Validation**: Before completing, verify code against loaded standards\n\n## Examples\n\n### Example 1: Creating a PHP Service\n\n```\nUser: \"Create a service to handle user notifications\"\n\nActions:\n1. Identify: PHP service development\n2. Read standards:\n   - coding_standards/php/coding.md\n   - coding_standards/php/documentation.md\n   - coding_standards/php/namespaces.md\n   - coding_standards/php/naming-services.md\n3. Generate code following all standards\n4. Include proper docblocks, namespaces, service naming\n```\n\n### Example 2: Writing Database Query\n\n```\nUser: \"Write a query to get active users with roles\"\n\nActions:\n1. Identify: SQL query\n2. Read standards:\n   - coding_standards/sql/conventions.md\n   - coding_standards/sql/keywords.md\n   - coding_standards/sql/select-from.md\n3. Write query with proper keyword capitalization and formatting\n```\n\n### Example 3: Building an Accessible Form\n\n```\nUser: \"Create a contact form with validation\"\n\nActions:\n1. Identify: Multi-context (PHP form API, JavaScript validation, accessibility)\n2. Read standards:\n   - coding_standards/php/coding.md\n   - coding_standards/php/documentation.md\n   - coding_standards/javascript/coding.md\n   - coding_standards/markup/style.md\n   - coding_standards/accessibility/accessibility.md\n3. Build form with all standards applied\n4. Ensure full accessibility compliance\n```\n\n## Critical Reminders\n\n- **Never skip reading standards** - always load them before coding\n- **Standards override preferences** - follow Drupal standards exactly\n- **When uncertain** - read additional related standard files\n- **Multi-file tasks** - load standards for ALL file types involved\n- **US English spelling** - non-negotiable requirement\n"},"lastSynced":"2026-03-08T02:02:36.103Z","agentAnalysis":{"suitability":{"en":"Perfect for PHP Development Agents needing to enforce Drupal coding standards and best practices.","zh":"非常适合需要强制执行Drupal编码标准和最佳实践的PHP开发代理。","ja":"Drupalのコーディング規範とベストプラクティスを強制する必要があるPHP開発エージェントに最適です。","ko":"Drupal 코딩 표준 및 최고의 관행을 강제로 적용해야 하는 PHP 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo PHP que necesitan hacer cumplir las normas y las mejores prácticas de codificación de Drupal.","fr":"Parfait pour les agents de développement PHP ayant besoin de faire respecter les normes et les meilleures pratiques de codage de Drupal.","de":"Perfekt für PHP-Entwicklungsagenten, die Drupal-Codierungsstandards und Best Practices durchsetzen müssen.","pt":"Perfeito para Agentes de Desenvolvimento PHP que precisam impor padrões e melhores práticas de codificação do Drupal.","ru":"Идеально подходит для агентов разработки PHP, которым необходимо обеспечивать соблюдение стандартов и лучших практик кодирования Drupal.","ar":"مثالي للوكلاء الذين يحتاجون إلى فرض معايير وافتراضات الترميز لتنمية Drupal باللغة PHP."},"recommendation":{"en":"Empowers agents to apply version-independent Drupal coding standards, ensuring US English spelling consistency and adherence to the Boy Scout Rule, resulting in efficient development and better code quality through PHP files, modules, services, and plugins.","zh":"赋予代理应用版本无关的Drupal编码标准，确保US English拼写一致性和遵守Boy Scout Rule，从而通过PHP文件、模块、服务和插件实现高效的开发和更好的代码质量。","ja":"エージェントにバージョンに依存しないDrupalのコーディング規範を適用することを可能にし、US Englishのスペルの一貫性とBoy Scout Ruleの遵守を保証し、PHPファイル、モジュール、サービス、およびプラグインを介した効率的な開発とより良いコード品質を実現します。","ko":"에이전트가 버전에 독립적인 Drupal 코딩 표준을 적용할 수 있도록 하여 US 영어 철자의 일관성과 보이스카우트 규칙의 순守을 보장하여 PHP 파일, 모듈, 서비스 및 플러그인을 통해 효율적인 개발 및 더 나은 코드 품질을 달성합니다.","es":"Habilita a los agentes a aplicar normas de codificación de Drupal independientes de la versión, garantizando la coherencia de la ortografía en inglés de EE. UU. y el cumplimiento de la Regla del Boy Scout, lo que resulta en un desarrollo eficiente y una mejor calidad del código a través de archivos PHP, módulos, servicios y complementos.","fr":"Permet aux agents d''appliquer des normes de codage de Drupal indépendantes de la version, garantissant la cohérence de l''orthographe en anglais américain et le respect de la Règle du Boy Scout, aboutissant à un développement efficace et à une meilleure qualité de code via des fichiers PHP, des modules, des services et des plug-ins.","de":"Ermöglicht es Agenten, version-unabhängige Drupal-Codierungsstandards anzuwenden, die Konsistenz der US-amerikanischen Rechtschreibung sicherzustellen und die Beachtung der Boy-Scout-Regel, was zu einem effizienten Entwicklung und besserer Codequalität durch PHP-Dateien, Module, Dienste und Plugins führt.","pt":"Habilita os agentes a aplicar padrões de codificação do Drupal independentes de versão, garantindo a consistência da ortografia em inglês americano e a adesão à Regra do Escoteiro, resultando em desenvolvimento eficiente e melhor qualidade de código por meio de arquivos PHP, módulos, serviços e plug-ins.","ru":"Наделяет агентов возможностью применять стандарты кодирования Drupal, независимые от версии, обеспечивая последовательность английского языка с американским правописанием и соблюдение Правило Разведчика, в результате чего получается эффективная разработка и лучшее качество кода через файлы PHP, модули, сервисы и плагины.","ar":"تمكين الوكلاء من تطبيق معايير الترميز لبرنامج Drupal التي لا تعتمد على الإصدار، مما يضمن اتحاد拼رة اللغة الإنجليزية الأمريكية وتطبيق قاعدة الكشاف، مما يؤدي إلى تطوير فعال وجودة أفضل للرمز من خلال ملفات PHP والوحدات والخدمات والإضافات."},"useCases":{"en":["Enforcing Drupal coding standards for PHP development","Validating US English spelling in code comments and names","Applying the Boy Scout Rule for improved code maintainability"],"zh":["执行PHP开发的Drupal编码标准","验证代码注释和名称中的US English拼写","应用Boy Scout Rule以提高代码的可维护性"],"ja":["PHP開発のDrupalコーディング規範の適用","コードのコメントと名前におけるUS Englishスペルの検証","コードの保守性の向上のためのBoy Scout Ruleの適用"],"ko":["PHP 개발을 위한 Drupal 코딩 표준의 적용","코드 주석 및 이름에서 US 영어 철자 검증","코드 유지보수성을 향상시키기 위한 보이스카우트 규칙 적용"],"es":["Hacer cumplir las normas de codificación de Drupal para el desarrollo de PHP","Validar la ortografía en inglés de EE. UU. en comentarios y nombres de código","Aplicar la Regla del Boy Scout para una mejor mantenibilidad del código"],"fr":["Faire respecter les normes de codage de Drupal pour le développement PHP","Valider l''orthographe en anglais américain dans les commentaires et les noms de code","Appliquer la Règle du Boy Scout pour une meilleure maintenabilité du code"],"de":["Durchsetzen von Drupal-Codierungsstandards für die PHP-Entwicklung","Überprüfen der US-amerikanischen Rechtschreibung in Codekommentaren und -namen","Anwenden der Boy-Scout-Regel für eine verbesserte Wartbarkeit des Codes"],"pt":["Impor padrões de codificação do Drupal para desenvolvimento PHP","Validar a ortografia em inglês americano em comentários e nomes de código","Aplicar a Regra do Escoteiro para melhorar a manutenibilidade do código"],"ru":["Обеспечить соблюдение стандартов кодирования Drupal для разработки PHP","Проверить правописание английского языка с американским вариантом в комментариях и именах кода","Применить Правило Разведчика для улучшения поддерживаемости кода"],"ar":["فرض معايير الترميز لبرنامج Drupal لتنمية PHP","التحقق من拼رة اللغة الإنجليزية الأمريكية في التعليقات وأسماء الرمز","تطبيق قاعدة الكشاف لتحسين صيانة الرمز"]},"limitations":{"en":["Requires PHP development context","Limited to Drupal-specific coding standards"],"zh":["需要PHP开发上下文","仅限于Drupal特定的编码标准"],"ja":["PHP開発のコンテキストが必要","Drupal特有のコーディング規範に限定される"],"ko":["PHP 개발 컨텍스트가 필요함","Drupal 전용 코딩 표준으로 제한됨"],"es":["Requiere un contexto de desarrollo de PHP","Limitado a normas de codificación específicas de Drupal"],"fr":["Nécessite un contexte de développement PHP","Limité aux normes de codage spécifiques à Drupal"],"de":["Benötigt einen PHP-Entwicklungskontext","Befristet auf Drupal-spezifische Codierungsstandards"],"pt":["Exige contexto de desenvolvimento PHP","Limitado a padrões de codificação específicos do Drupal"],"ru":["Требует контекста разработки PHP","Ограничен стандартами кодирования, специфичными для Drupal"],"ar":["يتطلب سياق تنمية PHP","محدود بمعايير الترميز الخاصة ببرنامج Drupal"]},"version":4},"contentHash":"0aa609b0613a2dea56b6814692415992c728952de8da5ba041ba65c334d54bc3","qualityScore":54}');
