INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nonzod/drupaldev-claude-skill/drupal-standards', 'drupal-standards', 'nonzod', 'drupaldev-claude-skill', 'community', 'drupal-standards nonzod drupaldev-claude-skill community The drupal-standards skill applies Drupal coding standards for efficient development, benefiting developers who work with PHP files, modules, services, and plugins. It ensures all code follows US English spelling and the Boy Scout Rule. Drupal 标准开发指南提供了 Drupal 编码标准和最佳实践，帮助开发者提高开发效率 Drupal 開発のための AI エージェント設定ガイドでは、Drupal コーディング標準とベストプラクティスを紹介します 드루팔 개발을 위한 Drupal Standards 설정 가이드는 드루팔 코딩 표준과 모범 사례를 제공하여 개발자에게 도움을 줍니다 Aplicación de normas de codificación de Drupal para un desarrollo eficiente Application des normes de codage Drupal pour un développement efficace Anwendung der Drupal-Coding-Standards für eine effiziente Entwicklung O skill drupal-standards ajuda desenvolvedores a seguir as normas de codificação do Drupal, melhorando a qualidade do código Навык drupal-standards помогает разработчикам следовать стандартам кодирования Drupal, улучшая качество кода المهارة drupal-standards تساعد المبرمجين على اتباع معايير دروبال، مما يحسن جودة الكود how to use drupal-standards drupal-standards setup guide drupal coding standards best practices drupal-standards vs drupal coding standards drupal-standards install what is drupal-standards drupal-standards alternative drupal development with drupal-standards drupal-standards for PHP development Drupal 标准开发 Drupal 编码标准 PHP 开发 Drupal 模块开发 Drupal 服务开发 Drupal 插件开发 AI 开发工具 Drupal 开发最佳实践 Applies Drupal coding standards based on development context Enforces US English spelling in comments and names Follows the Boy Scout Rule for code improvement Supports PHP development for files, modules, services, and plugins Ensures standards are always-current for new code Detects context and loads standards for efficient development drupal-standards is a set of guidelines for Drupal development that ensures all code follows version-independent coding standards, US English spelling, and best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('utkudarilmaz/claude-code-setup/docs', 'community', 'utkudarilmaz', 'claude-code-setup', 'utkudarilmaz/claude-code-setup', 'docs', 0, 0, 54, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:38.730Z', 'd65e076ec3e88c93366ede7180d8ccb17da1c03e26d40413673e96cf9cdff0c9', '{"id":"utkudarilmaz/claude-code-setup/docs","name":"docs","description":{"en":"The docs skill dispatches an agent to synchronize documentation with code changes, benefiting developers by keeping their README.md, CLAUDE.md, and API docs accurate and current.","zh":"docs技能用于自动更新文档以反映代码变更，包括README.md、CLAUDE.md和docs目录文件","ja":"docsスキルは、コードの変更を反映するために、README.md、CLAUDE.md、docsディレクトリファイルなどのドキュメントを自動更新","ko":"docs 스킬은 코드 변경을 반영하기 위해 README.md, CLAUDE.md 및 문서 디렉토리 파일을 자동으로 업데이트","es":"El agente de documentación Docs se utiliza para sincronizar la documentación con los cambios de código, actualizando archivos como README.md y API docs","fr":"L''agent de documentation Docs est utilisé pour synchroniser la documentation avec les modifications de code, mettant à jour des fichiers tels que README.md et API docs","de":"Der Docs-Dokumentationsagent wird verwendet, um die Dokumentation mit Codeänderungen zu synchronisieren und Dateien wie README.md und API-Dokumentation zu aktualisieren","pt":"O skill Docs é uma ferramenta que sincroniza documentação com alterações de código, garantindo que seus arquivos README.md, CLAUDE.md e outros sejam precisos e atualizados","ru":"Навык документации - это инструмент, который синхронизирует документацию с изменениями кода, обеспечивая точность и актуальность файлов README.md, CLAUDE.md и других","ar":"مهارة الوثائق هي أداة تزامن الوثائق مع تغييرات التعليمات البرمجية، مما يضمن دقة ومواكبة ملفات README.md و CLAUDE.md وغيرها"},"seo":{"title":{"en":"docs: Automated Documentation Setup Guide | AI Agent Skill","zh":"docs Setup Guide: 同步代码变更和文档更新","ja":"docs ベストプラクティス: コード変更とドキュメントの同期","ko":"docs 설정 가이드: 코드 변경과 문서 업데이트 자동화","es":"Configuración de Documentación Automatizada con Docs","fr":"Guide d''Installation de l''Agent de Documentation Docs","de":"Docs-Setup-Leitfaden für Automatisierte Dokumentation","pt":"Guia de Configuração do Skill Docs: Sincronize Documentaç...","ru":"Настройка Навыка Документации: Синхронизация Документов с...","ar":"دليل إعداد مهارة الوثائق: مزامنة الوثائق مع تغييرات التعل..."},"description":{"en":"Discover how to synchronize documentation with code changes using the docs AI agent skill. Learn how to keep your README.md, API docs, and postman collection...","zh":"使用docs AIエージェント自动更新README.md、CLAUDE.md和docs目录文件，确保文档准确性","ja":"docs AIエージェントを使用してREADME.md、CLAUDE.md、docsディレクトリファイルを自動更新","ko":"docs AI 에이전트를 사용하여 README.md, CLAUDE.md 및 문서 디렉토리 파일을 자동 업데이트","es":"Aprende a configurar el agente de documentación Docs para mantener tus archivos de documentación actualizados con cambios de código","fr":"Découvrez comment configurer l''agent de documentation Docs pour synchroniser vos fichiers de documentation avec les modifications de code","de":"Erfahren Sie, wie Sie den Docs-Dokumentationsagenten konfigurieren, um Ihre Dokumentationsdateien mit Codeänderungen zu aktualisieren","pt":"Aprenda a configurar o skill Docs para manter sua documentação atualizada e precisa, sincronizando alterações de código e APIs","ru":"Узнайте, как настроить навык документации для поддержания актуальности и точности документов, синхронизируя изменения кода и API с помощью ИИ Агенты","ar":"تعرف على كيفية إعداد مهارة الوثائق لتحديث وثائقك وتحسين دقتها، ومزامنة تغييرات التعليمات البرمجية والواجهات البرمجية"},"definition":{"en":"docs is a skill that automates documentation updates, ensuring consistency between code changes and documentation files such as README.md, CLAUDE.md, and API docs.","zh":"docs是用于自动更新代码变更的文档，包括README.md、CLAUDE.md和docs目录文件","ja":"docsは、コードの変更を反映するために、README.md、CLAUDE.md、docsディレクトリファイルなどのドキュメントを自動更新するAIエージェント","ko":"docs는 코드 변경을 반영하기 위해 README.md, CLAUDE.md 및 문서 디렉토리 파일을 자동으로 업데이트하는 AI 에이전트","es":"El agente de documentación Docs es una herramienta de inteligencia artificial que ayuda a mantener la documentación actualizada con los cambios de código","fr":"L''agent de documentation Docs est un outil d''intelligence artificielle qui aide à maintenir la documentation à jour avec les modifications de code","de":"Der Docs-Dokumentationsagent ist ein KI-Tool, das hilft, die Dokumentation mit Codeänderungen auf dem neuesten Stand zu halten","pt":"O que é o skill Docs? É uma ferramenta de sincronização de documentação que atualiza arquivos de documentação com alterações de código","ru":"Что такое навык документации? Это инструмент синхронизации документации, который обновляет файлы документации с изменениями кода","ar":"ما هي مهارة الوثائق؟ هي أداة مزامنة الوثائق التي تحدث ملفات الوثائق مع تغييرات التعليمات البرمجية"},"features":{"en":["Updates README.md files to reflect code changes","Synchronizes API docs with modifications to APIs, endpoints, or response schemas","Modifies postman collections to ensure accuracy","Restructures files and directories to maintain consistency","Updates docs/* directory files to keep them current","Handles changes to configuration options or environment variables"],"zh":["自动更新README.md","自动更新CLAUDE.md","自动更新docs目录文件","支持API文档和Postman集合更新","支持代码变更和环境变量更新"],"ja":["README.mdの自動更新","CLAUDE.mdの自動更新","docsディレクトリファイルの自動更新","APIドキュメントとPostmanコレクションの更新をサポート","コードの変更と環境変数の更新をサポート"],"ko":["README.md 자동 업데이트","CLAUDE.md 자동 업데이트","문서 디렉토리 파일 자동 업데이트","API 문서 및 Postman 컬렉션 업데이트를 지원","코드 변경 및 환경 변수 업데이트를 지원"],"es":["Actualiza archivos de documentación como README.md y CLAUDE.md","Sincroniza la documentación con cambios de código en la carpeta docs/*","Mantiene la documentación de API y colecciones de Postman actualizadas","Soporta la actualización de archivos de configuración y variables de entorno","Permite la reestructuración de archivos y directorios"],"fr":["Met à jour des fichiers de documentation tels que README.md et CLAUDE.md","Synchronise la documentation avec les modifications de code dans le répertoire docs/*","Maintient la documentation de l''API et les collections de Postman à jour","Prend en charge la mise à jour des fichiers de configuration et des variables d''environnement","Permet la réorganisation de fichiers et de répertoires"],"de":["Aktualisiert Dokumentationsdateien wie README.md und CLAUDE.md","Synchronisiert die Dokumentation mit Codeänderungen im Verzeichnis docs/*","Hält die API-Dokumentation und Postman-Sammlungen auf dem neuesten Stand","Unterstützt die Aktualisierung von Konfigurationsdateien und Umgebungsvariablen","Ermöglicht die Umstrukturierung von Dateien und Verzeichnissen"],"pt":["Sincronização de documentação com alterações de código","Atualização de arquivos README.md e CLAUDE.md","Suporte a diretórios docs/*","Integração com API docs e postman collections","Suporte a reestruturação de arquivos e diretórios"],"ru":["Синхронизация документации с изменениями кода","Обновление файлов README.md и CLAUDE.md","Поддержка директорий docs/*","Интеграция с API документации и postman collections","Поддержка переструктуризации файлов и директорий"],"ar":["مزامنة الوثائق مع تغييرات التعليمات البرمجية","تحديث ملفات README.md و CLAUDE.md","دعم مجلدات docs/*","دمج مع وثائق API وجمعيات بوستمان","دعم إعادة هيكلة الملفات والمجلدات"]},"keywords":{"en":["how to use docs","what is docs","docs alternative","docs vs dox","docs install","docs setup guide","automated documentation tools","API documentation best practices","README.md generator"],"zh":["docs AIエージェント","代码变更自动更新","文档自动更新","README.md更新","CLAUDE.md更新","docs目录文件更新","API文档更新","Postman集合更新"],"ja":["docs AIエージェント","コードの変更自動更新","ドキュメント自動更新","README.md更新","CLAUDE.md更新","docsディレクトリファイル更新","APIドキュメント更新","Postmanコレクション更新"],"ko":["docs AI 에이전트","코드 변경 자동 업데이트","문서 자동 업데이트","README.md 업데이트","CLAUDE.md 업데이트","문서 디렉토리 파일 업데이트","API 문서 업데이트","Postman 컬렉션 업데이트"],"es":["agente de documentación","herramientas de inteligencia artificial","documentación automatizada","README.md","API docs","Postman collections","configuración de código","variables de entorno"],"fr":["agent de documentation","outils d''intelligence artificielle","documentation automatisée","README.md","API docs","collections de Postman","configuration de code","variables d''environnement"],"de":["Dokumentationsagent","KI-Tools","automatisierte Dokumentation","README.md","API-Dokumentation","Postman-Sammlungen","Code-Konfiguration","Umgebungsvariablen"],"pt":["skill docs","sincronização de documentação","alterações de código","README.md","CLAUDE.md","docs/*","API docs","postman collections","reestruturação de arquivos"],"ru":["навык документации","синхронизация документации","изменения кода","README.md","CLAUDE.md","docs/*","API документации","postman collections","переструктуризация файлов"],"ar":["مهارة الوثائق","مزامنة الوثائق","تغييرات التعليمات البرمجية","README.md","CLAUDE.md","docs/*","وثائق API","مجموعات بوستمان","إعادة هيكلة الملفات"]}},"owner":"utkudarilmaz","repo":"claude-code-setup","repoPath":"utkudarilmaz/claude-code-setup","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"docs","description":"This skill should be used when the user asks to update documentation, document this change, sync docs with code, audit documentation, restructure docs, update README, update CLAUDE.md, update docs folder, document API, update postman collection, or /docs. Supports scoped, comprehensive (all), and restructuring (simplifier) modes.","bodyPreview":"# Docs Skill\n\n## Purpose\n\nDispatch the docs agent to synchronize documentation with code changes. The agent updates README.md, CLAUDE.md, docs/* directory files, API docs, postman collections, and other documentation files to keep them accurate and current.\n\n## When to Invoke\n\nInvoke this skill after:\n\n- Implementing new features or modifying existing ones\n- Modifying APIs, endpoints, or response schemas\n- Changing configuration options or environment variables\n- Restructuring files or directori","body":"# Docs Skill\n\n## Purpose\n\nDispatch the docs agent to synchronize documentation with code changes. The agent updates README.md, CLAUDE.md, docs/* directory files, API docs, postman collections, and other documentation files to keep them accurate and current.\n\n## When to Invoke\n\nInvoke this skill after:\n\n- Implementing new features or modifying existing ones\n- Modifying APIs, endpoints, or response schemas\n- Changing configuration options or environment variables\n- Restructuring files or directories\n- Updating dependencies\n- Any significant code modification\n- Explicit request to audit or restructure documentation\n\n## Invocation Modes\n\n### Default: `/docs`\n\nDocument current or recent changes. The agent identifies recently modified files and updates related documentation.\n\n```\nTask tool with subagent_type=\"docs\"\nprompt: \"Review recent code changes and update all affected documentation.\nIdentify modified files, scan the docs/ directory for existing files, and update README.md, CLAUDE.md, docs/* files, and any other relevant documentation.\"\n```\n\n### Scoped: `/docs <scope>`\n\nDocument only the specified scope (file, module, feature).\n\n```\nTask tool with subagent_type=\"docs\"\nprompt: \"Review and update documentation for: [scope]\nFocus only on this area. Update all relevant documentation files including any matching files in the docs/ directory.\"\n```\n\n**Scope examples:**\n- `/docs src/auth` - authentication module\n- `/docs API` - all API endpoints\n- `/docs README` - only README.md\n- `/docs config` - configuration options\n- `/docs UserService` - specific class or service\n\n### Comprehensive: `/docs all`\n\nPerform a planned, modular documentation update covering every repository aspect.\n\n```\nTask tool with subagent_type=\"docs\"\nprompt: \"Perform comprehensive documentation audit of all repository areas.\nCreate a TodoWrite plan with one item per documentation aspect, then process sequentially.\nConsult references/comprehensive-mode.md for the full aspect checklist and execution flow.\"\n```\n\nFor detailed aspect checklist and example plan, consult **`references/comprehensive-mode.md`**.\n\n### Simplifier: `/docs simplifier`\n\nPerform documentation restructuring to transform monolithic files into a modular structure with proper cross-linking.\n\n```\nTask tool with subagent_type=\"docs\"\nprompt: \"Perform documentation restructuring analysis and execution.\nAnalyze file sizes, identify files exceeding thresholds, propose modular split plan, and execute.\nConsult references/simplifier-mode.md for analysis checklist and target structure.\"\n```\n\nFor detailed restructuring criteria and target structure, consult **`references/simplifier-mode.md`**.\n\n## Usage Examples\n\n```\n/docs                          # Document recent changes\n/docs src/services/payment     # Document payment service only\n/docs API                      # Update API documentation only\n/docs all                      # Full project documentation audit\n/docs simplifier               # Restructure large docs into modular files\n/docs architecture             # Update architecture docs and .drawio diagrams\n/docs postman                  # Validate and update postman_collection.json\n```\n\n## Additional Resources\n\n### Reference Files\n\nFor detailed mode execution flows, consult:\n- **`references/comprehensive-mode.md`** - Full audit execution flow, aspect checklist, example TodoWrite plan\n- **`references/simplifier-mode.md`** - Restructuring analysis, thresholds, cross-linking templates, target structure\n"},"lastSynced":"2026-03-08T02:02:38.730Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Maintenance Agents needing automated documentation synchronization with code changes.","zh":"非常适合需要自动同步代码变更的代码维护代理","ja":"コードの変更とドキュメントを自動的に同期する必要があるコードメンテナンスエージェントに最適","ko":"코드 변경 사항과 문서를 자동으로同步해야 하는 코드 유지 보수 에이전트에 적합","es":"Perfecto para agentes de mantenimiento de código que necesitan una sincronización automatizada de la documentación con los cambios de código.","fr":"Parfait pour les agents de maintenance de code nécessitant une synchronisation automatique de la documentation avec les modifications de code.","de":"Perfekt für Code-Wartungsagenten, die eine automatisierte Synchronisierung der Dokumentation mit Codeänderungen benötigen.","pt":"Perfeito para Agentes de Manutenção de Código que precisam de sincronização automática de documentação com alterações de código.","ru":"Идеально для агентов по обслуживанию кода, которым требуется автоматическая синхронизация документации с изменениями кода.","ar":"مثالي للوكلاء الذين يحتاجون إلى تنسيق تلقائي للوثائق مع تغييرات الكود."},"recommendation":{"en":"Empowers agents to update README.md, CLAUDE.md, and API docs in real-time, ensuring accuracy and consistency using Markdown formatting and Postman collections.","zh":"使代理能够实时更新README.md、CLAUDE.md和API文档，确保准确性和一致性，使用Markdown格式和Postman集合","ja":"エージェントがREADME.md、CLAUDE.md、APIドキュメントをリアルタイムで更新できるようにし、Markdown形式とPostmanコレクションを使用して正確性と一貫性を確保","ko":"에이전트가 README.md, CLAUDE.md, API 문서를 실시간으로 업데이트할 수 있도록 하여 Markdown 형식과 Postman 컬렉션을 사용하여 정확성과 일관성을 보장","es":"Permite a los agentes actualizar README.md, CLAUDE.md y la documentación de API en tiempo real, garantizando la precisión y la consistencia utilizando la formato Markdown y las colecciones de Postman.","fr":"Permet aux agents de mettre à jour README.md, CLAUDE.md et les documents d''API en temps réel, en garantissant l''exactitude et la cohérence en utilisant le formatage Markdown et les collections Postman.","de":"Ermächtigt die Agenten, README.md, CLAUDE.md und API-Dokumentationen in Echtzeit zu aktualisieren, um Genauigkeit und Konsistenz unter Verwendung von Markdown-Formatierung und Postman-Sammlungen sicherzustellen.","pt":"Habilita os agentes a atualizar README.md, CLAUDE.md e documentação de API em tempo real, garantindo precisão e consistência usando formatação Markdown e coleções Postman.","ru":"Наделяет агентов возможностью обновлять README.md, CLAUDE.md и документацию API в реальном времени, обеспечивая точность и согласованность с помощью форматирования Markdown и коллекций Postman.","ar":"يمنح الوكلاء تحديث README.md و CLAUDE.md ووثائق API في الوقت الفعلي، مما يضمن الدقة والاتساق باستخدام تنسيق Markdown ومجموعات Postman."},"useCases":{"en":["Synchronizing documentation after new feature implementation","Updating API documentation following endpoint modifications","Maintaining accurate README.md files after code refactorings"],"zh":["新功能實施後同步文檔","端點修改後更新API文檔","代碼重構後維護準確的README.md檔"],"ja":["新機能の実装後にドキュメントを同期する","エンドポイントの変更後にAPIドキュメントを更新する","コードのリファクタリング後に正確なREADME.mdファイルを維持する"],"ko":["새 기능 구현 후 문서同步","엔드포인트 수정 후 API 문서 업데이트","코드 리팩토링 후 정확한 README.md 파일 유지"],"es":["Sincronización de la documentación después de la implementación de nuevas características","Actualización de la documentación de API después de la modificación de puntos de conexión","Mantenimiento de archivos README.md precisos después de la reestructuración del código"],"fr":["Synchronisation de la documentation après la mise en œuvre de nouvelles fonctionnalités","Mise à jour de la documentation d''API après la modification des points de terminaison","Maintenance de fichiers README.md précis après la réorganisation du code"],"de":["Synchronisierung der Dokumentation nach der Implementierung neuer Funktionen","Aktualisierung der API-Dokumentation nach der Änderung von Endpunkten","Beibehaltung genauer README.md-Dateien nach dem Refactoring des Codes"],"pt":["Sincronização da documentação após implementação de novos recursos","Atualização da documentação de API após modificações de pontos de extremidade","Manutenção de arquivos README.md precisos após reestruturações de código"],"ru":["Синхронизация документации после реализации новых функций","Обновление документации API после изменений конечных точек","Поддержание точных файлов README.md после рефакторинга кода"],"ar":["تنسيق الوثائق بعد تنفيذ الميزات الجديدة","تحديث وثائق API بعد تعديل النقاط النهائية","الحفاظ على صحة ملفات README.md بعد إعادة هيكلة الكود"]},"limitations":{"en":["Requires access to code repository","Limited to Markdown and Postman collection file formats"],"zh":["需要访问代码仓库","仅限Markdown和Postman集合文件格式"],"ja":["コードリポジトリへのアクセスが必要","MarkdownとPostmanコレクションファイル形式のみ"],"ko":["코드 저장소에 접근해야 함","Markdown 및 Postman 컬렉션 파일 형식만"],"es":["Requiere acceso al repositorio de código","Limitado a los formatos de archivo Markdown y Postman"],"fr":["Nécessite un accès au référentiel de code","Limité aux formats de fichier Markdown et Postman"],"de":["Erfordert Zugriff auf das Code-Repository","Begrenzt auf Markdown- und Postman-Dateiformate"],"pt":["Requer acesso ao repositório de código","Limitado a formatos de arquivo Markdown e coleção Postman"],"ru":["Требует доступа к репозиторию кода","Ограничен форматами файлов Markdown и коллекцией Postman"],"ar":["يتطلب الوصول إلى مستودع الكود","محدود بتنسيقات ملفات Markdown ومجموعة Postman"]},"version":4},"contentHash":"d65e076ec3e88c93366ede7180d8ccb17da1c03e26d40413673e96cf9cdff0c9","qualityScore":54}');
