INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yudame/research/notebooklm-audio', 'notebooklm-audio', 'yudame', 'research', 'community', 'notebooklm-audio yudame research community The notebooklm-audio skill generates audio content for research and analysis, benefiting developers and researchers. It provides a manual fallback for when the NotebookLM Enterprise API is unavailable. NotebookLM Audio 是一个用于研究和分析的工具，提供手动回退机制，使用 Python 脚本和 CLI 工具 NotebookLM Audio は、研究と分析のためにマニュアルフォールバックメカニズムを提供するツールで、Python スクリプトと CLI ツールを使用 NotebookLM Audio는 연구 및 분석을 위한 수동 폴백 메커니즘을 제공하는 도구로, Python 스크립트 및 CLI 도구를 사용 Notebooklm-audio es una herramienta de investigación para análisis basado en evidencia en tecnología, salud y economía Notebooklm-audio est un outil de recherche pour l''analyse basée sur des preuves dans les domaines de la technologie, de la santé et de l''économie Notebooklm-audio ist ein Forschungstool für evidenzbasierte Analyse in Technologie, Gesundheit und Wirtschaft O notebooklm-audio é uma ferramenta de análise baseada em evidências que gera podcasts, relatórios e materiais educacionais ИИ Агент notebooklm-audio - это инструмент evidence-based анализа, который генерирует подкасты, отчеты и образовательные материалы notebooklm-audio هي أداة تحليل مبنية على الأدلة التي تنتج بودكاستات وتقارير ومواد تعليمية how to use notebooklm-audio notebooklm-audio manual fallback notebooklm-audio vs NotebookLM Enterprise API notebooklm-audio setup guide notebooklm-audio install what is notebooklm-audio notebooklm-audio alternative notebooklm-audio for research and analysis NotebookLM Audio AI 工具 研究和分析 手动回退机制 Python 脚本 CLI 工具 NotebookLM Enterprise API Uses Python script for prompt generation Supports manual workflow when NotebookLM Enterprise API is unavailable Generates audio content, including podcasts and reports Utilizes bash commands for script execution Requires explicit user request for manual workflow notebooklm-audio is a research tool that generates audio content, including podcasts and educational materials, using a manual fallback workflow when the NotebookLM Enterprise API is not available.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eleva-labs/agentic-coding-templates/setup-dev', 'community', 'eleva-labs', 'agentic-coding-templates', 'eleva-labs/agentic-coding-templates', 'setup-dev', 0, 0, 54, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:48.834Z', '8e7444931190e74be44db378cfae8f0e1cf430dd6a081fb1655fb423875fdd46', '{"id":"eleva-labs/agentic-coding-templates/setup-dev","name":"setup-dev","description":{"en":"The setup-dev skill provides a standardized development environment setup for mobile apps, ensuring consistent environments across teams. It guides developers through the setup process.","zh":"setup-dev 是一个开发环境设置的标准操作流程，用于设置完整的开发环境。","ja":"setup-dev は開発環境設定の標準操作プロセスです。完全な開発環境を設定するために使用されます。","ko":"setup-dev는 개발 환경 설정의 표준 운영 절차로서 완전한 개발 환경을 설정하는 데 사용됩니다.","es":"Setup-dev es una herramienta de AI para configurar entornos de desarrollo para aplicaciones móviles, garantizando la consistencia y la productividad","fr":"Setup-dev est un outil d''IA pour configurer les environnements de développement pour les applications mobiles, assurant la cohérence et la productivité","de":"Setup-dev ist ein AI-Tool zum Konfigurieren von Entwicklungsumgebungen für mobile Anwendungen, um Konsistenz und Produktivität zu gewährleisten","pt":"O setup-dev é um guia para configurar o ambiente de desenvolvimento completo para aplicativos móveis, garantindo ambientes consistentes.","ru":"Setup-dev - это руководство по настройке полной среды разработки для мобильных приложений, обеспечивающее консистентность.","ar":"setup-dev هو دليل لإعداد بيئة التطوير الكاملة للتطبيقات المحمولة، مما يضمن بيئات متسقة."},"seo":{"title":{"en":"setup-dev: Development Environment Setup Guide | AI Agent...","zh":"setup-dev 开发环境设置指南","ja":"setup-dev 開発環境設定ガイド - AIエージェント","ko":"setup-dev 개발 환경 설정 가이드 - AI Tools","es":"Herramientas de AI: Guía de configuración setup-dev","fr":"Outils d''IA: Guide de configuration setup-dev","de":"AI-Tools: Setup-Dev-Konfigurationsleitfaden","pt":"Guia de Configuração de Desenvolvimento setup-dev","ru":"ИИ Агенты: Настройка Среды Разработки setup-dev","ar":"إعداد بيئة التطوير setup-dev: دليل شامل"},"description":{"en":"Discover how to set up a consistent development environment with setup-dev. Get started with our step-by-step guide and optimize your mobile app development ...","zh":"setup-dev 是一个开发环境设置的标准操作流程，确保团队成员的环境一致性，提高开发效率。","ja":"setup-dev は開発環境設定の標準操作プロセスです。チームメンバーの環境の一貫性を確保し、開発効率を向上させます - AIエージェント","ko":"setup-dev는 개발 환경 설정의 표준 운영 절차로서 팀원들의 환경 일관성을 보장하고 개발 효율성을 높입니다 - AI Tools","es":"Descubre cómo configurar tu entorno de desarrollo con setup-dev, la herramienta de AI para desarrolladores","fr":"Découvrez comment configurer votre environnement de développement avec setup-dev, l''outil d''IA pour les développeurs","de":"Erfahren Sie, wie Sie Ihre Entwicklungsumgebung mit setup-dev, dem AI-Tool für Entwickler, konfigurieren können","pt":"Aprenda a configurar o ambiente de desenvolvimento perfeito com o setup-dev. Garanta ambientes consistentes e produtividade desde o início.","ru":"Настройте среду разработки с помощью setup-dev. Убедитесь в консистентности и продуктивности с первого дня.","ar":"تعلم كيفية إعداد بيئة التطوير المثالية مع setup-dev. ضمان بيئات متسقة وإنتاجية منذ اليوم الأول."},"definition":{"en":"setup-dev is a template-based development environment setup guide for mobile apps, ensuring consistent and productive development environments.","zh":"setup-dev 是一个用于设置开发环境的标准操作流程。","ja":"setup-dev は開発環境設定の標準操作プロセスです。","ko":"setup-dev는 개발 환경 설정의 표준 운영 절차입니다.","es":"Setup-dev es una herramienta de AI que proporciona un proceso estandarizado para configurar entornos de desarrollo","fr":"Setup-dev est un outil d''IA qui fournit un processus standardisé pour configurer les environnements de développement","de":"Setup-dev ist ein AI-Tool, das einen standardisierten Prozess zur Konfiguration von Entwicklungsumgebungen bietet","pt":"O setup-dev é um procedimento operacional padrão para configurar ambientes de desenvolvimento.","ru":"Setup-dev - это стандартная операционная процедура для настройки среды разработки.","ar":"setup-dev هو إجراء تشغيلي معياري لإعداد بيئة التطوير."},"features":{"en":["Provides a template for development environment setup with placeholders for project values like {PROJECT_NAME} and {REPO_DIRECTORY}","Ensures consistent environments across teams with a standardized setup process","Supports versioning with a specified version number, such as 1.0.0","Includes a last updated date for tracking changes, such as 2026-01-11","Guides developers through the setup process with a step-by-step SOP"],"zh":["支持设置完整的开发环境","确保团队成员的环境一致性","提高开发效率","包含版本管理（Version：1.0.0）","支持多个项目（{PROJECT_NAME}）","支持多个仓库目录（{REPO_DIRECTORY}）"],"ja":["完全な開発環境の設定をサポート","チームメンバーの環境の一貫性を確保","開発効率を向上させる","バージョン管理（Version：1.0.0）を含む","複数のプロジェクト（{PROJECT_NAME}）をサポート","複数のリポジトリディレクトリ（{REPO_DIRECTORY}）をサポート"],"ko":["완전한 개발 환경 설정을 지원","팀원들의 환경 일관성을 보장","개발 효율성을 높인다","버전 관리（Version：1.0.0）를 포함","複数의 프로젝트（{PROJECT_NAME}）를 지원","複数の 리포지토리 디렉토리（{REPO_DIRECTORY}）를 지원"],"es":["Configuración de entornos de desarrollo para aplicaciones móviles","Establecimiento de un proceso estandarizado para la configuración","Garantía de la consistencia en la configuración del entorno","Habilitación de la productividad desde el primer día","Compatibilidad con la versión 1.0.0","Actualización más reciente el 11 de enero de 2026"],"fr":["Configuration des environnements de développement pour les applications mobiles","Établissement d''un processus standardisé pour la configuration","Garantie de la cohérence dans la configuration de l''environnement","Activation de la productivité dès le premier jour","Compatibilité avec la version 1.0.0","Dernière mise à jour le 11 janvier 2026"],"de":["Konfiguration von Entwicklungsumgebungen für mobile Anwendungen","Einrichtung eines standardisierten Prozesses für die Konfiguration","Gewährleistung der Konsistenz bei der Konfiguration der Umgebung","Aktivierung der Produktivität ab dem ersten Tag","Kompatibilität mit der Version 1.0.0","Letzte Aktualisierung am 11. Januar 2026"],"pt":["Configuração do ambiente de desenvolvimento para aplicativos móveis","Garantia de ambientes consistentes","Productividade desde o início","Suporte à versão 1.0.0","Atualização em 2026-01-11"],"ru":["Настройка среды разработки для мобильных приложений","Обеспечение консистентности","Продуктивность с первого дня","Поддержка версии 1.0.0","Обновление 2026-01-11"],"ar":["إعداد بيئة التطوير للتطبيقات المحمولة","ضمان البيئات المتسقة","إنتاجية منذ اليوم الأول","دعم الإصدار 1.0.0","تحديث 2026-01-11"]},"keywords":{"en":["how to use setup-dev","setup-dev alternative","setup-dev setup guide","what is setup-dev","setup-dev vs other development environment tools","setup-dev install","setup-dev for mobile app development","setup-dev template","setup-dev development environment setup"],"zh":["setup-dev","开发环境设置","标准操作流程","环境一致性","开发效率","版本管理","项目管理","仓库目录管理"],"ja":["setup-dev","開発環境設定","標準操作プロセス","環境の一貫性","開発効率","バージョン管理","プロジェクト管理","リポジトリディレクトリ管理","AIエージェント"],"ko":["setup-dev","개발 환경 설정","표준 운영 절차","환경 일관성","개발 효율성","버전 관리","프로젝트 관리","리포지토리 디렉토리 관리","AI Tools"],"es":["herramientas de AI para desarrolladores","configuración de entornos de desarrollo","aplicaciones móviles","productividad en el desarrollo","proceso estandarizado de configuración","version 1.0.0","actualización de enero 2026","setup-dev","desarrollo de aplicaciones móviles"],"fr":["outils d''IA pour les développeurs","configuration des environnements de développement","applications mobiles","productivité dans le développement","processus standardisé de configuration","version 1.0.0","mise à jour de janvier 2026","setup-dev","développement d''applications mobiles"],"de":["AI-Tools für Entwickler","Konfiguration von Entwicklungsumgebungen","mobile Anwendungen","Produktivität in der Entwicklung","standardisierter Prozess der Konfiguration","Version 1.0.0","Aktualisierung Januar 2026","setup-dev","Entwicklung von mobilen Anwendungen"],"pt":["setup-dev","configuração de desenvolvimento","ambiente de desenvolvimento","aplicativos móveis","desenvolvimento de software","productividade","consistência"],"ru":["setup-dev","настройка среды разработки","среда разработки","мобильные приложения","разработка программного обеспечения","продуктивность","консистентность"],"ar":["setup-dev","إعداد بيئة التطوير","بيئة التطوير","تطبيقات محمولة","تطوير البرمجيات","إنتاجية","اتساق"]}},"owner":"eleva-labs","repo":"agentic-coding-templates","repoPath":"eleva-labs/agentic-coding-templates","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"setup-dev","description":">-","bodyPreview":"# Development Environment Setup SOP\n\n> **Note**: This is a template. Replace placeholders like `{PROJECT_NAME}`, `{REPO_DIRECTORY}`, and `{BUNDLE_ID}` with your actual project values.\n\n**Version**: 1.0.0\n**Last Updated**: 2026-01-11\n**Status**: Active\n\n---\n\n## Overview\n\n### Purpose\nThis SOP guides developers through setting up the complete development environment for the mobile app. It ensures consistent environments across the team and enables productive development from day one.\n\n### When to U","body":"# Development Environment Setup SOP\n\n> **Note**: This is a template. Replace placeholders like `{PROJECT_NAME}`, `{REPO_DIRECTORY}`, and `{BUNDLE_ID}` with your actual project values.\n\n**Version**: 1.0.0\n**Last Updated**: 2026-01-11\n**Status**: Active\n\n---\n\n## Overview\n\n### Purpose\nThis SOP guides developers through setting up the complete development environment for the mobile app. It ensures consistent environments across the team and enables productive development from day one.\n\n### When to Use\n**ALWAYS**: New developer onboarding, setting up a new machine, clean reinstall, troubleshooting environment issues\n**SKIP**: Already have working environment, only need platform-specific setup (use `setup-ios` or `setup-android`)\n\n---\n\n## Process Workflow\n\n### Flow Diagram\n```\n[Prerequisites] --> [Automated Setup] --> [Verification] --> [First Run]\n```\n\n### Phase Summary\n| Phase | Objective | Deliverable |\n|-------|-----------|-------------|\n| 1. Prerequisites | Ensure required tools installed | macOS, Xcode, Command Line Tools |\n| 2. Setup | Install development tools | Volta, Node.js 20, pnpm, dependencies |\n| 3. Verification | Confirm environment works | `task check-prereqs` passes |\n| 4. First Run | Run the app | App running in simulator |\n\n---\n\n## Quick Start\n\n### Option 1: Fully Automated Setup (5 minutes)\n\n```bash\n# Clone the repository\ngit clone <repository-url>\ncd {REPO_DIRECTORY}\n\n# Run automated setup (installs everything)\n./scripts/setup-development.sh\n```\n\nThe script handles:\n- Volta installation\n- Node.js 20 setup\n- Project dependency installation\n- Development environment configuration\n\n### Option 2: Manual Setup (10 minutes)\n\n```bash\n# 1. Install Volta\ncurl https://get.volta.sh | bash\n\n# 2. Restart terminal, then setup Node\nvolta install node@20\nvolta pin node@20\n\n# 3. Install dependencies\npnpm install\n\n# 4. Setup development environment\ntask setup-dev\n\n# 5. Verify setup\ntask check-prereqs\n```\n\n### Option 3: One-Command Full Setup (Fastest)\n\nIf you already have the repository cloned and just need to complete setup:\n\n```bash\ntask setup-full\n```\n\nThis does everything in one command:\n1. Install all dependencies (`pnpm install`)\n2. Create local environment config (`.env.local`)\n3. Pull development settings from EAS\n4. Verify all patches applied correctly\n\n---\n\n## Detailed Guide\n\nFor comprehensive setup instructions including prerequisites and troubleshooting, see:\n- [SETUP_GUIDE.md](./SETUP_GUIDE.md) - Detailed setup steps\n\n---\n\n## Quick Reference\n\n### Common Commands\n```bash\n# Verify environment\ntask check-prereqs\n\n# Start iOS development\ntask run-ios\n\n# Start Android development\ntask run-android\n\n# Run tests\ntask test\n\n# Clean and regenerate\ntask clean && task generate\n```\n\n### Local Environment Setup\n\n```bash\ntask setup-local-env    # Creates .env.local\ntask verify-patches     # Check patches are applied\ntask setup-full         # Complete setup in one command\n```\n\n### Key Environment Variables\n```bash\n# Check Node version (should be v20.x.x)\nnode --version\n\n# Check Volta version\nvolta --version\n\n# Check pnpm version\npnpm --version\n```\n\n---\n\n## Troubleshooting\n\n| Issue | Solution |\n|-------|----------|\n| Volta not found after install | Restart terminal or source shell config |\n| Wrong Node version | Run `volta pin node@20` in project directory |\n| pnpm not found | Install via `volta install pnpm` |\n| Metro bundler errors | Run `task clean-cache` |\n| iOS build fails | See `setup-ios` skill or [SETUP_GUIDE.md](./SETUP_GUIDE.md) |\n| Android build fails | See `setup-android` skill or [SETUP_GUIDE.md](./SETUP_GUIDE.md) |\n| `.env.local` missing | Run `task setup-local-env` |\n| SIMULATOR variable undefined | Run `task setup-local-env` to recreate `.env.local` |\n\n---\n\n## Related Skills\n\n| Skill | Purpose | When to Use |\n|-------|---------|-------------|\n| `/setup-env` | Configure environment variables | After initial setup |\n| `/setup-ios` | iOS-specific setup | For iOS development |\n| `/setup-android` | Android-specific setup | For Android development |\n| `/help` | Troubleshooting guide | When encountering issues |\n\n> **Note**: Skill paths (`/skill-name`) work after deployment. In the template repo, skills are in domain folders.\n\n---\n\n**End of SOP**\n"},"lastSynced":"2026-03-08T02:02:48.834Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined mobile app development environment setup and standardization across teams.","zh":"适合需要简化移动应用开发环境设置和跨团队标准化的开发代理。","ja":"開発エージェントがモバイルアプリの開発環境設定とチーム間の標準化を簡素化する必要がある場合に適しています。","ko":"개발 환경 설정과 팀 간의 표준화를 단순화해야 하는 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que requieren un entorno de desarrollo de aplicaciones móviles simplificado y estandarizado en equipos.","fr":"Idéal pour les agents de développement nécessitant un environnement de développement d''applications mobiles simplifié et standardisé dans les équipes.","de":"Ideal für Entwicklungsmittel, die ein gestreamtes Mobile-App-Entwicklungsumgebung-Setup und eine Standardisierung in Teams erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem um ambiente de desenvolvimento de aplicativos móveis otimizado e padronizado em equipes.","ru":"Идеально подходит для агентов разработки, требующих упрощенной среды разработки мобильных приложений и стандартизации по командам.","ar":"مثالي لعميلة التطوير الذين يحتاجون إلى بيئة تطوير تطبيقات الجوال المُبسطة والإعداد القياسي عبر الفرق."},"recommendation":{"en":"Empowers agents to establish consistent development environments for mobile apps, ensuring seamless integration and productivity from the outset, utilizing standardized development environment setup and guiding developers through the setup process with Version control and Repository directory management.","zh":"赋予代理建立移动应用的一致开发环境的能力，确保从一开始就实现无缝集成和生产力，利用标准化的开发环境设置，并通过版本控制和存储库目录管理引导开发者完成设置过程。","ja":"エージェントがモバイルアプリの開発環境を一貫して設定できるようにし、最初からシームレスな統合と生産性を確保するための推奨事項です。標準化された開発環境設定を利用し、バージョン管理とリポジトリディレクトリ管理で開発者を導きます。","ko":"에이전트가 모바일 애플리케이션에 대한 일致된 개발 환경을 설정할 수 있도록 하여 처음부터 원활한 통합 및 생산성을 보장하는 것을 권장합니다. 표준화된 개발 환경 설정을 사용하고 버전 관리 및 리포지토리 디렉토리 관리로 개발자를 안내합니다.","es":"Permite a los agentes establecer entornos de desarrollo coherentes para aplicaciones móviles, garantizando una integración y productividad sin problemas desde el principio, utilizando un entorno de desarrollo estandarizado y guiando a los desarrolladores a través del proceso de configuración con control de versiones y gestión de directorios de repositorio.","fr":"Permet aux agents d''établir des environnements de développement cohérents pour les applications mobiles, en garantissant une intégration et une productivité sans problème dès le départ, en utilisant un environnement de développement standardisé et en guidant les développeurs à travers le processus de configuration avec le contrôle de version et la gestion du répertoire de référentiel.","de":"Ermächtigt Agenten, konsistente Entwicklungsumgebungen für Mobile-Apps zu etablieren, indem sie eine nahtlose Integration und Produktivität von Anfang an sicherstellen, indem sie ein standardisiertes Entwicklungsumgebung-Setup verwenden und Entwickler durch den Setup-Prozess mit Versionierung und Repository-Verzeichnisverwaltung führen.","pt":"Permite que os agentes estabeleçam ambientes de desenvolvimento consistentes para aplicativos móveis, garantindo integração e produtividade sem interrupções desde o início, utilizando configuração de ambiente de desenvolvimento padronizada e orientando os desenvolvedores durante o processo de configuração com Controle de Versão e Gerenciamento de Diretório de Repositório.","ru":"Наделяет агентов возможностью создавать последовательные среды разработки для мобильных приложений, обеспечивая бесперебойную интеграцию и produktivnost с самого начала, используя стандартизированную настройку среды разработки и направляя разработчиков через процесс настройки с помощью Управления Версиями и Управления Каталогом Хранилища.","ar":"تمكن الوكلاء من إنشاء بيئات تطوير متسقة لتطبيقات الجوال، مما يضمن التكامل والانتاجية دون انقطاع منذ البداية، باستخدام إعداد بيئة تطوير قياسي وتوجيه المطورين خلال عملية الإعداد مع التحكم في الإصدار وإدارة دليل المستودع."},"useCases":{"en":["Standardizing development environments across teams","Guiding developers through setup processes for mobile apps","Ensuring consistent environments for productive development"],"zh":["跨团队标准化开发环境","引导开发者完成移动应用设置流程","确保开发环境的一致性以实现高效开发"],"ja":["チーム間で開発環境を標準化する","開発者がモバイルアプリの設定プロセスを通じて導く","開発環境の一貫性を確保し、生産的な開発を実現する"],"ko":["팀 간 개발 환경 표준화","개발자가 모바일 애플리케이션 설정 프로세스를 통해 안내","개발 환경의 일관성을 보장하여 효율적인 개발을 실현"],"es":["Estandarizar entornos de desarrollo en equipos","Guiar a los desarrolladores a través de los procesos de configuración para aplicaciones móviles","Garantizar entornos coherentes para un desarrollo productivo"],"fr":["Standardiser les environnements de développement dans les équipes","Guider les développeurs à travers les processus de configuration pour les applications mobiles","Assurer des environnements cohérents pour un développement productif"],"de":["Entwicklungsumgebungen in Teams standardisieren","Entwickler durch die Einrichtungsprozesse für Mobile-Apps führen","Konsistente Umgebungen für produktives Entwickeln sicherstellen"],"pt":["Padronizar ambientes de desenvolvimento em equipes","Orientar desenvolvedores durante os processos de configuração para aplicativos móveis","Garantir ambientes consistentes para desenvolvimento produtivo"],"ru":["Стандартизировать среды разработки по командам","Направлять разработчиков через процессы настройки для мобильных приложений","Обеспечить последовательные среды для продуктивного разработки"],"ar":["تقييس بيئات التطوير في الفرق","توجيه المطورين خلال عمليات الإعداد لتطبيقات الجوال","ضمان بيئات متسقة لتطوير منتج"]},"limitations":{"en":["Requires project-specific values like {PROJECT_NAME}, {REPO_DIRECTORY}, and {BUNDLE_ID}","Limited to mobile app development environment setup"],"zh":["需要项目特定的值，如 {PROJECT_NAME}、{REPO_DIRECTORY} 和 {BUNDLE_ID}","仅限移动应用开发环境设置"],"ja":["{PROJECT_NAME}、{REPO_DIRECTORY}、{BUNDLE_ID} などのプロジェクト固有の値が必要","モバイルアプリ開発環境設定に限定される"],"ko":["{PROJECT_NAME}, {REPO_DIRECTORY}, {BUNDLE_ID}などの 프로젝트 특정 값이 필요","모바일 애플리케이션 개발 환경 설정에만 제한"],"es":["Requiere valores específicos del proyecto como {PROJECT_NAME}, {REPO_DIRECTORY} y {BUNDLE_ID}","Limitado a la configuración del entorno de desarrollo de aplicaciones móviles"],"fr":["Nécessite des valeurs spécifiques au projet comme {PROJECT_NAME}, {REPO_DIRECTORY} et {BUNDLE_ID}","Limité à la configuration de l''environnement de développement d''applications mobiles"],"de":["Benötigt projektspezifische Werte wie {PROJECT_NAME}, {REPO_DIRECTORY} und {BUNDLE_ID}","Begrenzt auf die Einrichtung der Mobile-App-Entwicklungsumgebung"],"pt":["Exige valores específicos do projeto, como {PROJECT_NAME}, {REPO_DIRECTORY} e {BUNDLE_ID}","Limitado à configuração do ambiente de desenvolvimento de aplicativos móveis"],"ru":["Требует проектно-специфических значений, таких как {PROJECT_NAME}, {REPO_DIRECTORY} и {BUNDLE_ID}","Ограничен настройкой среды разработки мобильных приложений"],"ar":["يتطلب قيم محددة للمشروع، مثل {PROJECT_NAME} و {REPO_DIRECTORY} و {BUNDLE_ID}","محدود بإعداد بيئة تطوير تطبيقات الجوال"]},"version":4},"contentHash":"8e7444931190e74be44db378cfae8f0e1cf430dd6a081fb1655fb423875fdd46","qualityScore":54}');
