INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eleva-labs/agentic-coding-templates/setup-dev', 'setup-dev', 'eleva-labs', 'agentic-coding-templates', 'community', 'setup-dev eleva-labs agentic-coding-templates community The setup-dev skill provides a standardized development environment setup for mobile apps, ensuring consistent environments across teams. It guides developers through the setup process. setup-dev 是一个开发环境设置的标准操作流程，用于设置完整的开发环境。 setup-dev は開発環境設定の標準操作プロセスです。完全な開発環境を設定するために使用されます。 setup-dev는 개발 환경 설정의 표준 운영 절차로서 완전한 개발 환경을 설정하는 데 사용됩니다. Setup-dev es una herramienta de AI para configurar entornos de desarrollo para aplicaciones móviles, garantizando la consistencia y la productividad Setup-dev est un outil d''IA pour configurer les environnements de développement pour les applications mobiles, assurant la cohérence et la productivité Setup-dev ist ein AI-Tool zum Konfigurieren von Entwicklungsumgebungen für mobile Anwendungen, um Konsistenz und Produktivität zu gewährleisten O setup-dev é um guia para configurar o ambiente de desenvolvimento completo para aplicativos móveis, garantindo ambientes consistentes. Setup-dev - это руководство по настройке полной среды разработки для мобильных приложений, обеспечивающее консистентность. setup-dev هو دليل لإعداد بيئة التطوير الكاملة للتطبيقات المحمولة، مما يضمن بيئات متسقة. how to use setup-dev setup-dev alternative setup-dev setup guide what is setup-dev setup-dev vs other development environment tools setup-dev install setup-dev for mobile app development setup-dev template setup-dev development environment setup setup-dev 开发环境设置 标准操作流程 环境一致性 开发效率 版本管理 项目管理 仓库目录管理 Provides a template for development environment setup with placeholders for project values like {PROJECT_NAME} and {REPO_DIRECTORY} Ensures consistent environments across teams with a standardized setup process Supports versioning with a specified version number, such as 1.0.0 Includes a last updated date for tracking changes, such as 2026-01-11 Guides developers through the setup process with a step-by-step SOP setup-dev is a template-based development environment setup guide for mobile apps, ensuring consistent and productive development environments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pcortes/swarm-attack/backlog-champion', 'community', 'pcortes', 'swarm-attack', 'pcortes/swarm-attack', 'backlog-champion', 0, 0, 54, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:48.983Z', '17f714baa147593e030df55a2782d5d947e28a4e8cbc32dd97a050d35833e0a0', '{"id":"pcortes/swarm-attack/backlog-champion","name":"backlog-champion","description":{"en":"The backlog-champion skill advocates for opportunities that maximize team velocity and deliver value. It represents the product perspective in the 3-agent debate system.","zh":"Backlog Champion 是产品速度的倡导者，在 3 个代理商辩论系统中优先处理机会以最大化团队速度和价值交付","ja":"バックログチャンピオンは、3 エージェントの議論システムで最も価値の高い機会を優先してチームの速度を最大化するための製品速度のアドボケートです","ko":"백로그 챔피언은 3개 에이전트 토론 시스템에서 가장 가치 있는 기회를 우선순위 지정하여 팀 속도를 최대화하는 제품 속도의 옹호자입니다","es":"Backlog Champion es un defensor del producto que prioriza oportunidades para maximizar la velocidad del equipo. Representa la perspectiva del producto en el debate de priorización.","fr":"Backlog Champion est un défenseur de produit qui priorise les opportunités pour optimiser la vitesse d''équipe. Il représente la perspective produit dans le débat de priorisation.","de":"Backlog Champion ist ein Produktverfechter, der Chancen priorisiert, um die Teamgeschwindigkeit zu maximieren. Er vertritt die Produktsperspektive im Priorisierungsdebatten.","pt":"O Backlog Champion é um Product Champion que prioriza oportunidades para maximizar a velocidade da equipe","ru":"Backlog Champion - это Product Champion, который расставляет приоритеты для максимальной скорости команды","ar":"بطل قائمة الإنتظار هو بطل المنتج الذي يركز على فرص لزيادة سرعة الفريق"},"seo":{"title":{"en":"backlog-champion: Prioritization Debate Advocate for AI A...","zh":"Backlog Champion 设置指南：最大化团队速度","ja":"バックログチャンピオンのベストプラクティス：AIエージェントを活用した優先順位付け","ko":"백로그 챔피언 설정 가이드: 팀 속도 최적화","es":"Guía de configuración de Backlog Champion para maximizar ...","fr":"Guide de mise en place de Backlog Champion pour optimiser...","de":"Einrichtungsleitfaden für Backlog Champion zur Maximierun...","pt":"Guia de Configuração do Backlog Champion para Desenvolved...","ru":"Настройка Backlog Champion: ИИ Агенты для Разработчиков","ar":"دليل إعداد بطل قائمة الإنتظار للطورين"},"description":{"en":"Unlock maximum team velocity with backlog-champion. Discover how to prioritize opportunities and deliver value. Learn more and get started today!","zh":"了解 Backlog Champion 的作用，如何在 3 个代理商辩论系统中优先处理机会，最大化团队速度和价值交付","ja":"バックログチャンピオンの役割と、3 エージェントの議論システムにおける優先順位付けの方法について学びます","ko":"백로그 챔피언의 역할과 3개 에이전트 토론 시스템에서 기회를 우선순위 지정하여 팀 속도와 가치 전달을 최대화하는 방법에 대해 알아보세요","es":"Aprende a utilizar Backlog Champion para priorizar oportunidades y maximizar la velocidad del equipo. Descubre sus características y beneficios.","fr":"Découvrez comment utiliser Backlog Champion pour prioriser les opportunités et optimiser la vitesse d''équipe. Explorez ses fonctionnalités et avantages.","de":"Erfahren Sie, wie Sie Backlog Champion verwenden, um Chancen zu priorisieren und die Teamgeschwindigkeit zu maximieren. Entdecken Sie seine Funktionen und Vo...","pt":"Aprenda a priorizar oportunidades para maximizar a velocidade da equipe e entregar o máximo de valor com o Backlog Champion","ru":"Узнайте, как использовать Backlog Champion, чтобы расставить приоритеты для максимальной скорости команды и доставки максимальной ценности с помощью ИИ Агентов","ar":"تعرف على كيفية ترتيب الأولويات لفرص لزيادة سرعة الفريق وتسليم القيمة القصوى مع بطل قائمة الإنتظار"},"definition":{"en":"backlog-champion is a product champion skill that prioritizes opportunities to maximize team velocity and deliver value in the backlog prioritization debate.","zh":"Backlog Champion 是一种产品速度的倡导者，负责在 3 个代理商辩论系统中优先处理机会","ja":"バックログチャンピオンは、3 エージェントの議論システムで最も価値の高い機会を優先するための製品速度のアドボケートです","ko":"백로그 챔피언은 3개 에이전트 토론 시스템에서 기회를 우선순위 지정하여 제품 속도를 최대화하는 역할을 수행하는 제품 속도의 옹호자입니다","es":"Backlog Champion es un agente de IA que actúa como defensor del producto en el debate de priorización de backlog.","fr":"Backlog Champion est un agent IA qui agit comme défenseur de produit dans le débat de priorisation de backlog.","de":"Backlog Champion ist ein IA-Agent, der als Produktverfechter im Priorisierungsdebatten von Backlog auftritt.","pt":"O que é Backlog Champion? Um Product Champion que prioriza oportunidades para maximizar a velocidade da equipe","ru":"Что такое Backlog Champion? Product Champion, который расставляет приоритеты для максимальной скорости команды","ar":"ما هو بطل قائمة الإنتظار? بطل المنتج الذي يركز على فرص لزيادة سرعة الفريق"},"features":{"en":["Argues for prioritizing the best opportunities in the backlog prioritization debate","Represents the product perspective in the 3-agent debate system","Works with the Critic to address engineering concerns","Collaborates with the Moderator to synthesize final rankings","Maximizes team velocity by prioritizing high-value opportunities","Delivers value by advocating for the most impactful opportunities"],"zh":["在 3 个代理商辩论系统中优先处理机会","最大化团队速度和价值交付","产品角度的代表","与 Critic 和 Moderator 协作","优先处理最有价值的机会"],"ja":["3 エージェントの議論システムで最も価値の高い機会を優先する","チームの速度と価値の提供を最大化する","製品の観点からの代表","Critic と Moderator と協力する","最も価値の高い機会を優先する"],"ko":["3개 에이전트 토론 시스템에서 기회를 우선순위 지정","팀 속도와 가치 전달을 최대화","제품 관점의 대표","Critic과 Moderator와 협력","가장 가치 있는 기회를 우선순위 지정"],"es":["Priorización de oportunidades para maximizar la velocidad del equipo","Representación de la perspectiva del producto en el debate de priorización","Colaboración con el crítico y el moderador para determinar las prioridades","Análisis de oportunidades para determinar el valor y la viabilidad","Defensa de las oportunidades priorizadas para asegurar la implementación"],"fr":["Priorisation des opportunités pour optimiser la vitesse d''équipe","Représentation de la perspective produit dans le débat de priorisation","Collaboration avec le critique et le modérateur pour déterminer les priorités","Analyse des opportunités pour déterminer la valeur et la viabilité","Défense des opportunités priorisées pour assurer la mise en œuvre"],"de":["Priorisierung von Chancen zur Maximierung der Teamgeschwindigkeit","Vertretung der Produktsperspektive im Priorisierungsdebatten","Zusammenarbeit mit dem Kritiker und dem Moderator zur Bestimmung der Prioritäten","Analyse von Chancen zur Bestimmung des Wertes und der Machbarkeit","Verteidigung der priorisierten Chancen zur Sicherstellung der Umsetzung"],"pt":["Priorização de oportunidades para maximizar a velocidade da equipe","Debate de 3 agentes: Champion, Critic e Moderator","Representação da perspectiva do produto","Integração com conceitos de engenharia","Otimização da entrega de valor"],"ru":["Расстановка приоритетов для максимальной скорости команды","Дебаты 3-х агентов: Champion, Critic и Moderator","Представление продукта","Интеграция с инженерными концепциями","Оптимизация доставки ценности"],"ar":["ترتيب الأولويات لفرص لزيادة سرعة الفريق","مناقشة 3 وكلاء: البطل، الناقد والمنظم","تمثيل منظور المنتج","التكامل مع مفاهيم الهندسة","تحسين تسليم القيمة"]},"keywords":{"en":["how to use backlog-champion","what is backlog-champion","backlog-champion alternative","backlog-champion vs prioritization tools","backlog-champion install","backlog-champion setup guide","backlog prioritization debate strategies","maximizing team velocity with backlog-champion","product champion skills for AI agents"],"zh":["Backlog Champion","AI 代理商","产品速度","团队速度","价值交付","优先处理机会","3 个代理商辩论系统","产品角度","Critic","Moderator"],"ja":["バックログチャンピオン","AI エージェント","製品速度","チームの速度","価値の提供","機会の優先順位付け","3 エージェントの議論システム","製品の観点","Critic","Moderator"],"ko":["백로그 챔피언","AI 에이전트","제품 속도","팀 속도","가치 전달","기회 우선순위 지정","3개 에이전트 토론 시스템","제품 관점","Critic","Moderator"],"es":["Backlog Champion","priorización de oportunidades","velocidad del equipo","perspectiva del producto","debate de priorización","agentes de IA","herramientas de IA","desarrollo de productos","gestión de proyectos"],"fr":["Backlog Champion","priorisation des opportunités","vitesse d''équipe","perspective produit","débat de priorisation","agents IA","outils IA","développement de produits","gestion de projets"],"de":["Backlog Champion","Priorisierung von Chancen","Teamgeschwindigkeit","Produktsperspektive","Priorisierungsdebatten","IA-Agenten","IA-Tools","Produktentwicklung","Projektmanagement"],"pt":["Backlog Champion","Product Champion","priorização de oportunidades","velocidade da equipe","desenvolvimento de software","gerenciamento de projeto","otimização de entrega","desenvolvedores","equipe de desenvolvimento"],"ru":["Backlog Champion","Product Champion","расстановка приоритетов","скорость команды","разработка программного обеспечения","управление проектом","оптимизация доставки","ИИ Агенты","разработчики"],"ar":["بطل قائمة الإنتظار","بطل المنتج","ترتيب الأولويات","سرعة الفريق","تطوير البرمجيات","إدارة المشروع","تحسين التسليم","أدوات الذكاء الاصطناعي","مطورون"]}},"owner":"pcortes","repo":"swarm-attack","repoPath":"pcortes/swarm-attack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"backlog-champion","description":">","bodyPreview":"# Backlog Champion (Product Velocity Advocate)\n\nYou are a **Product Champion** in the backlog prioritization debate. Your job is to advocate for the opportunities that will maximize team velocity and deliver the most value.\n\n## Your Role\n\nIn the 3-agent debate system:\n- **You** (Champion): Argue for prioritizing the best opportunities\n- **Critic**: Challenge your rankings with engineering concerns\n- **Moderator**: Synthesize both views into final rankings\n\nYou represent the **product perspective","body":"# Backlog Champion (Product Velocity Advocate)\n\nYou are a **Product Champion** in the backlog prioritization debate. Your job is to advocate for the opportunities that will maximize team velocity and deliver the most value.\n\n## Your Role\n\nIn the 3-agent debate system:\n- **You** (Champion): Argue for prioritizing the best opportunities\n- **Critic**: Challenge your rankings with engineering concerns\n- **Moderator**: Synthesize both views into final rankings\n\nYou represent the **product perspective**: What should we build next to move fastest?\n\n## Startup Philosophy\n\n**We optimize for:**\n- **Velocity** - What unblocks the most work?\n- **Impact** - What delivers the most value to users?\n- **Momentum** - What keeps the team moving forward?\n- **Quick wins** - What can we ship today?\n\n**We avoid:**\n- Analysis paralysis\n- Perfectionism over progress\n- Large risky bets when small wins exist\n- Technical debt cleanup when features await\n\n## Input Format\n\nYou receive a list of discovered opportunities:\n\n```json\n{\n  \"opportunities\": [\n    {\n      \"opportunity_id\": \"opp-tf-20250115-abc123\",\n      \"title\": \"Fix test_login failing\",\n      \"type\": \"test_failure\",\n      \"actionability\": {\n        \"clarity\": 0.9,\n        \"evidence\": 0.85,\n        \"effort\": \"small\",\n        \"overall\": 0.9\n      },\n      \"affected_files\": [\"tests/test_auth.py\", \"src/auth.py\"],\n      \"description\": \"Test failure with clear assertion error\"\n    }\n  ],\n  \"context\": {\n    \"current_feature\": \"user-dashboard\",\n    \"blocked_issues\": [],\n    \"recent_failures\": 3,\n    \"budget_remaining_usd\": 2.50\n  }\n}\n```\n\n## Prioritization Criteria\n\n### Tier 1: Blockers (Always First)\n- Test failures blocking CI/CD\n- Issues blocking other developers\n- Critical bugs affecting users\n- Failing builds\n\n### Tier 2: Quick Wins (High ROI)\n- Small effort, high clarity opportunities\n- Type errors, import issues, simple fixes\n- Opportunities with actionability score > 0.8\n- < 30 minutes to fix\n\n### Tier 3: Momentum Builders\n- Related to current feature work\n- Build on recent changes\n- Keep developers in flow state\n\n### Tier 4: Technical Health\n- Coverage gaps in critical paths\n- Complexity hotspots (but only if severe)\n- Stalled work that''s almost done\n\n## Argumentation Strategy\n\n### Make Strong Claims\n\n**GOOD**: \"Fix test_login first because it blocks 3 other tests and takes 10 minutes\"\n**BAD**: \"Maybe we could consider looking at the test issues\"\n\n### Use Data\n\n**GOOD**: \"Actionability 0.95, effort small, blocks CI - clear winner\"\n**BAD**: \"This seems important\"\n\n### Acknowledge Trade-offs\n\n**GOOD**: \"Yes, the complexity fix is larger, but test_login unblocks the entire auth suite\"\n**BAD**: Ignore counter-arguments\n\n### Stay Practical\n\n**GOOD**: \"We can fix this in 15 minutes and move on\"\n**BAD**: \"We should design a comprehensive test strategy\"\n\n## Output Format\n\nOutput valid JSON only:\n\n```json\n{\n  \"champion_rankings\": [\n    {\n      \"rank\": 1,\n      \"opportunity_id\": \"opp-tf-20250115-abc123\",\n      \"argument\": \"Highest ROI: 10-minute fix unblocks CI and 3 dependent tests. Actionability 0.95 means we know exactly what to do.\",\n      \"estimated_time_minutes\": 10,\n      \"impact\": \"Unblocks CI, enables 3 other tests\"\n    },\n    {\n      \"rank\": 2,\n      \"opportunity_id\": \"opp-sw-20250115-def456\",\n      \"argument\": \"Stalled feature is 80% complete. 30 minutes to finish means we ship today instead of carrying debt.\",\n      \"estimated_time_minutes\": 30,\n      \"impact\": \"Completes user-dashboard feature\"\n    }\n  ],\n  \"rationale\": \"Prioritizing CI health first, then completing in-progress work. Both are quick wins with clear paths.\",\n  \"deferred\": [\n    {\n      \"opportunity_id\": \"opp-cq-20250115-ghi789\",\n      \"reason\": \"Complexity refactor is large effort, low urgency. Defer until we have a dedicated cleanup sprint.\"\n    }\n  ]\n}\n```\n\n## Debate Rules\n\n1. **Lead with your strongest case** - Put your best argument first\n2. **Quantify when possible** - \"10 minutes\" beats \"quick\"\n3. **Connect to team goals** - Why does this matter for what we''re building?\n4. **Acknowledge the critic''s valid points** - Then explain why you still prioritize differently\n5. **Stay focused on impact** - Not on technical elegance\n\n## Anti-Patterns to Avoid\n\n- \"We should fix everything\" - Prioritization means choosing\n- \"Let''s do a deep analysis\" - We''re moving fast\n- \"The right way would be...\" - The fast way that works is right\n- \"Eventually we''ll need to...\" - Defer future concerns\n\n## Cost Awareness\n\nYou have a budget for this debate session. Keep arguments concise:\n- Round 1: Make your case clearly\n- Round 2: Respond to critic, sharpen if needed\n- Round 3 (if needed): Final synthesis\n\nDon''t pad arguments. Say what matters, move on.\n\n## Remember\n\n**You are the velocity advocate.** Your job is to argue for the opportunities that move the team forward fastest. The critic will push back on feasibility. The moderator will balance. Trust the process, make your case strongly.\n"},"lastSynced":"2026-03-08T02:02:48.983Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing advanced product prioritization and velocity optimization capabilities.","zh":"适用于Cursor、Windsurf和Claude Code等AI代理，需要高级产品优先级和速度优化能力。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しています。これらのエージェントは、先進的な製品の優先順位付けと速度の最適化機能を必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 이러한 에이전트는 고급 제품 우선순위 지정 및 속도 최적화 기능을 필요로 합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan capacidades de priorización de productos avanzadas y optimización de velocidad.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin de capacités de priorisation de produits avancées et d''optimisation de vitesse.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die erweiterte Produkt-Priorisierungs- und Geschwindigkeits-Optimierungs-Funktionen benötigen.","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que necessitam de capacidades avançadas de priorização de produtos e otimização de velocidade.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым требуются продвинутые возможности приоритизации продукта и оптимизации скорости.","ar":"مثالية لعمليات الوكيل الذكي مثل Cursor و Windsurf و Claude Code التي تحتاج إلى قدرات متقدمة لتحديد الأولويات المنتج وتحسين السرعة."},"recommendation":{"en":"Empowers agents to advocate for opportunities that maximize team velocity and deliver value, leveraging the product perspective in the 3-agent debate system, and utilizing protocols like backlog prioritization and debate synthesis.","zh":"赋予代理能力，以倡导能够最大化团队速度和交付价值的机会，利用产品视角在3代理辩论系统中，并利用后台优先级和辩论合成等协议。","ja":"エージェントに、チームの速度を最大化し、価値を提供する機会を主張する能力を与え、3エージェントの議論システムにおける製品の視点を利用し、バックログの優先順位付けや議論の合成などのプロトコルを利用する。","ko":"에이전트에게 팀의 속도와 가치를 최대화하는 기회를 주장할 수 있는 능력을 부여하며, 3에이전트 토론 시스템에서 제품 관점을 활용하고, 백로그 우선순위 지정 및 토론 합성과 같은 프로토콜을 활용한다.","es":"Permite a los agentes abogar por oportunidades que maximizan la velocidad del equipo y entregan valor, aprovechando la perspectiva del producto en el sistema de debate de 3 agentes y utilizando protocolos como la priorización de la lista de tareas pendientes y la síntesis del debate.","fr":"Permet aux agents de plaider en faveur d''opportunités qui maximisent la vitesse de l''équipe et livrent de la valeur, en exploitant la perspective produit dans le système de débat à 3 agents et en utilisant des protocoles tels que la priorisation de la liste de tâches et la synthèse du débat.","de":"Ermächtigt Agents, sich für Chancen einzusetzen, die das Team-Tempo maximieren und Wert liefern, indem sie die Produkt-Perspektive im 3-Agents-Debatt-System nutzen und Protokolle wie die Priorisierung der Aufgabenliste und die Debattensynthese verwenden.","pt":"Habilita os agentes a defender oportunidades que maximizam a velocidade da equipe e entregam valor, aproveitando a perspectiva do produto no sistema de debate de 3 agentes e utilizando protocolos como priorização de backlog e síntese de debate.","ru":"Наделяет агентов возможностью отстаивать возможности, которые максимизируют скорость команды и поставляют ценность, используя перспективу продукта в системе дебатов из 3 агентов и используя протоколы, такие как приоритизация бэклога и синтез дебатов.","ar":"تمكّن الوكلاء من الدفاع عن الفرص التي تزيد من سرعة الفريق وتسليم القيمة، مستفيداً من منظور المنتج في نظام المناقشة لعمليات الوكيل الثلاثة و sửة بروتوكولات مثل تحديد أولويات الأعمال المتراكمة وتحليل المناقشة."},"useCases":{"en":["Prioritizing product features for maximum velocity","Debating engineering concerns with the Critic agent","Synthesizing product and engineering views with the Moderator agent"],"zh":["为了最大化速度而优先考虑产品功能","与Critic代理进行工程担忧的辩论","与Moderator代理合成产品和工程视角"],"ja":["最大速度を実現するための製品機能の優先順位付け","Criticエージェントとのエンジニアリングに関する議論","Moderatorエージェントとの製品とエンジニアリングの視点の統合"],"ko":["최대 속도를 위해 제품 기능을 우선순위 지정","Critic 에이전트와의 엔지니어링 관련 토론","Moderator 에이전트와의 제품 및 엔지니어링 관점의 통합"],"es":["Priorizar características de producto para máxima velocidad","Debatir preocupaciones de ingeniería con el agente Crítico","Sintetizar vistas de producto e ingeniería con el agente Moderador"],"fr":["Prioriser les fonctionnalités de produit pour une vitesse maximale","Débattre des préoccupations d''ingénierie avec l''agent Critique","Synthétiser les vues de produit et d''ingénierie avec l''agent Modérateur"],"de":["Priorisierung von Produktfunktionen für maximale Geschwindigkeit","Erörterung von Ingenieursbedenken mit dem Agenten Kritiker","Synthese von Produkt- und Ingenieuransichten mit dem Agenten Moderator"],"pt":["Priorizar recursos do produto para velocidade máxima","Debater preocupações de engenharia com o agente Crítico","Sintetizar vistas do produto e de engenharia com o agente Moderador"],"ru":["Приоритизация функций продукта для максимальной скорости","Обсуждение проблем инжиниринга с агентом Критик","Синтезирование продукта и инженерных точек зрения с агентом Модератор"],"ar":["تحديد أولويات ميزات المنتج لتحقيق أقصى سرعة","مناقشة المخاوف الهندسية مع عميل الناقد","دمج وجهات نظر المنتج والهندسة مع عميل المُoderador"]},"limitations":{"en":["Requires integration with the 3-agent debate system","Limited to product-centric decision making"],"zh":["需要与3代理辩论系统集成","仅限于产品中心的决策"],"ja":["3エージェントの議論システムとの統合が必要","製品中心の意思決定に限定される"],"ko":["3에이전트 토론 시스템과 통합必要","제품 중심의 의사결정에 한정"],"es":["Requiere integración con el sistema de debate de 3 agentes","Limitado a la toma de decisiones centrada en el producto"],"fr":["Nécessite une intégration avec le système de débat à 3 agents","Limité à la prise de décision centrée sur le produit"],"de":["Erfordert Integration mit dem 3-Agents-Debatt-System","Begrenzt auf produktzentrierte Entscheidungsfindung"],"pt":["Requer integração com o sistema de debate de 3 agentes","Limitado à tomada de decisão centrada no produto"],"ru":["Требует интеграции с системой дебатов из 3 агентов","Ограничен принятием решений, ориентированных на продукт"],"ar":["يتطلب تكاملًا مع نظام المناقشة لعمليات الوكيل الثلاثة","محدود في اتخاذ القرارات المُركّزة على المنتج"]},"version":4},"contentHash":"17f714baa147593e030df55a2782d5d947e28a4e8cbc32dd97a050d35833e0a0","qualityScore":54}');
