INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GolferGeek/orchestrator-ai/Orchestrator Git Standards', 'Orchestrator Git Standards', 'GolferGeek', 'orchestrator-ai', 'community', 'Orchestrator Git Standards GolferGeek orchestrator-ai community Orchestrator Git Standards is a critical skill for AI agents, ensuring consistent Git workflows through conventional branch names, commits, and clean history. It benefits developers working on collaborative projects. Orchestrator Git Standards提供了一套标准化的Git分支命名、提交消息和历史记录管理规则，帮助开发者优化Git工作流程 Orchestrator Git Standardsは、標準化されたGitブランチ名、コミットメッセージ、履歴管理ルールを提供し、開発者がGitワークフローを最適化できるようにします Orchestrator Git Standards는 표준화된 Git 브랜치 이름, 커밋 메시지 및 기록 관리 규칙을 제공하여 개발자가 Git 워크플로우를 최적화할 수 있습니다 El Skill de Estándares Git para Orchestrator garantiza un flujo de trabajo Git organizado y limpio Le Skill de Normes Git pour Orchestrator assure un workflow Git organisé et propre Das Skill für Git-Standards für Orchestrator gewährleistet einen organisierten und sauberen Git-Workflow O Orchestrator Git Standards é uma habilidade crítica para melhorar a organização e produtividade do seu time de desenvolvimento Orchestrator Git Standards - это критический навык для улучшения организации и производительности вашей команды разработки معايير Git للorchestrator هو مهارة حرجة لتحسين التنظيم والإنتاجية لفريق التطوير Orchestrator Git Standards setup guide how to use Orchestrator Git Standards what is Orchestrator Git Standards Orchestrator Git Standards vs GitFlow Orchestrator Git Standards install Git workflow management best practices conventional commit messages branch naming conventions Orchestrator Git Standards AIエージェント Git工作流程 项目管理 代码质量 维护性 Git分支命名 提交消息格式 Enforces conventional branch names, such as feature/user-authentication and fix/login-bug Supports conventional commits for clean history management Provides guidelines for organizing Git workflows, including creating branches and making commits Ensures consistency in Git workflows through standardized naming conventions Allows for easy identification of branch types, such as feature, fix, chore, and docs Streamlines Git workflow management through standardized commit messages Orchestrator Git Standards is a set of guidelines for managing Git workflows, including branch naming conventions and commit best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cameronapak/freedom-stack-v3/bknd-deploy-hosting', 'community', 'cameronapak', 'freedom-stack-v3', 'cameronapak/freedom-stack-v3', 'bknd-deploy-hosting', 0, 0, 54, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.000Z', '7ca0ed3feae12535774c981c3f6a987f4aed766194f18defee8361bc80b38617', '{"id":"cameronapak/freedom-stack-v3/bknd-deploy-hosting","name":"bknd-deploy-hosting","description":{"en":"The bknd-deploy-hosting skill enables developers to deploy their Bknd applications to multiple hosting platforms, including Cloudflare and Vercel, with a no-build, un-bloated stack. It benefits developers who need a flexible and efficient deployment process.","zh":"Bknd部署托管是一个无需构建、无冗余的栈，基于Web标准，能够轻松部署到任何地方","ja":"Bkndデプロイホスティングは、ビルド不要、無駄のないスタックで、Web標準に基づいており、どこにでも簡単にデプロイできます","ko":"Bknd 배포 호스팅은 빌드가 필요 없는 부풀리지 않은 스택으로, 웹 표준을 기반으로 하여 어디에でも 쉽게 배포할 수 있습니다","es":"El skill de bknd-deploy-hosting permite desplegar aplicaciones Bknd en diferentes plataformas de hosting sin necesidad de construir. Se basa en estándares web y ofrece una experiencia de uso liberadora.","fr":"Le skill de bknd-deploy-hosting permet de déployer des applications Bknd sur diverses plateformes d''hébergement sans nécessité de construction. Il repose sur les normes web et offre une expérience d''utilisation libératrice.","de":"Der bknd-deploy-hosting-Skill ermöglicht die Bereitstellung von Bknd-Anwendungen auf verschiedenen Hosting-Plattformen ohne Aufbau. Er basiert auf Web-Standards und bietet eine befreiende Benutzererfahrung.","pt":"O skill bknd-deploy-hosting permite a implantação de aplicativos Bknd em diferentes plataformas de hospedagem, sem a necessidade de compilação.","ru":"Навык bknd-deploy-hosting позволяет развертывать приложения Bknd на различных платформах хостинга без необходимости сборки.","ar":"تمكن مهارة bknd-deploy-hosting من نشر تطبيقات Bknd على منصات استضافة مختلفة دون الحاجة إلى بناء"},"seo":{"title":{"en":"bknd-deploy-hosting: Deployment Setup Guide | AI Agent Skill","zh":"Bknd 部署托管设置指南 - AI工具","ja":"Bknd デプロイ ホスティング設定ガイド - AIエージェント","ko":"Bknd 배포 호스팅 설정 가이드 - AI 에이전트","es":"Guía de configuración de bknd-deploy-hosting: Despliegue ...","fr":"Guide de configuration de bknd-deploy-hosting : Déploieme...","de":"Konfigurationsleitfaden für bknd-deploy-hosting: Bereitst...","pt":"Guia de Configuração bknd-deploy-hosting: Implantação de ...","ru":"Настройка bknd-deploy-hosting: ИИ Агенты для Развертывани...","ar":"دليل الإعداد bknd-deploy-hosting: نشر التطبيقات بسهولة"},"description":{"en":"Discover how to deploy your Bknd application to various hosting platforms with ease. Learn more about the bknd-deploy-hosting skill and get started today!","zh":"使用Bknd部署托管功能，快速轻松地将应用程序部署到各种托管平台，支持Cloudflare和Vercel等","ja":"Bkndデプロイホスティング機能を使用して、アプリケーションを簡単にさまざまなホスティングプラットフォームにデプロイします。CloudflareやVercelをサポート","ko":"Bknd 배포 호스팅 기능을 사용하여 애플리케이션을 쉽고 빠르게 다양한 호스팅 플랫폼에 배포합니다. Cloudflare 및 Vercel 지원","es":"Aprende a desplegar tu aplicación Bknd en diferentes plataformas de hosting con nuestro skill de despliegue de bknd-deploy-hosting","fr":"Découvrez comment déployer votre application Bknd sur diverses plateformes d''hébergement avec notre compétence de déploiement de bknd-deploy-hosting","de":"Erfahren Sie, wie Sie Ihre Bknd-Anwendung auf verschiedenen Hosting-Plattformen mit unserem bknd-deploy-hosting-Setup-Skill bereitstellen","pt":"Aprenda a implantar aplicativos Bknd em diferentes plataformas de hospedagem com o skill bknd-deploy-hosting","ru":"Развертывайте приложения Bknd на различных платформах хостинга с помощью навыка bknd-deploy-hosting и ИИ Агентов","ar":"تعلم نشر تطبيقات Bknd على منصات استضافة مختلفة باستخدام مهارة bknd-deploy-hosting"},"definition":{"en":"bknd-deploy-hosting is a skill that allows for the deployment of Bknd applications to various hosting platforms, utilizing Web Standards and supporting both UI and Code modes.","zh":"Bknd部署托管是指使用Bknd技术栈将应用程序部署到各种托管平台的过程","ja":"Bkndデプロイホスティングとは、Bkndテクノロジースタックを使用してアプリケーションをさまざまなホスティングプラットフォームにデプロイすることを指します","ko":"Bknd 배포 호스팅은 Bknd 기술 스택을 사용하여 애플리케이션을 다양한 호스팅 플랫폼에 배포하는 것을 의미합니다","es":"El skill de bknd-deploy-hosting es una herramienta de despliegue de aplicaciones que permite la implementación de aplicaciones Bknd en diferentes plataformas de hosting","fr":"Le skill de bknd-deploy-hosting est un outil de déploiement d''applications qui permet la mise en œuvre d''applications Bknd sur diverses plateformes d''hébergement","de":"Der bknd-deploy-hosting-Skill ist ein Tool für die Bereitstellung von Anwendungen, das die Implementierung von Bknd-Anwendungen auf verschiedenen Hosting-Plattformen ermöglicht","pt":"O que é bknd-deploy-hosting? É um skill que permite a implantação de aplicativos Bknd em diferentes plataformas de hospedagem.","ru":"Что такое bknd-deploy-hosting? Это навык, который позволяет развертывать приложения Bknd на различных платформах хостинга.","ar":"ما هي مهارة bknd-deploy-hosting؟ هي مهارة позволяет نشر تطبيقات Bknd على منصات استضافة مختلفة"},"features":{"en":["Deploy Bknd applications to Cloudflare and Vercel dashboards","Utilize environment variables prepared with bknd-env-config","Provision databases using bknd-database-provision","View deployment logs in UI Mode","Configure deployment settings using Code Mode","Adapt deployment configuration and commands"],"zh":["支持Cloudflare和Vercel等托管平台","基于Web标准，能够轻松部署到任何地方","无需构建，减少冗余代码","支持环境变量和平台特定部署设置","提供deployment logs查看功能"],"ja":["CloudflareやVercelなどのホスティングプラットフォームをサポート","Web標準に基づいており、どこにでも簡単にデプロイできます","ビルド不要、無駄のないコード","環境変数とプラットフォーム特有のデプロイ設定をサポート","デプロイログの表示機能を提供"],"ko":["Cloudflare 및 Vercel 등의 호스팅 플랫폼을 지원","웹 표준을 기반으로 하여 어디에でも 쉽게 배포할 수 있습니다","빌드가 필요 없으며, 코드의 중복을 줄입니다","환경 변수 및 플랫폼 특정 배포 설정을 지원","배포 로그를查看하는 기능을 제공"],"es":["Despliegue de aplicaciones Bknd sin construir","Compatibilidad con diferentes plataformas de hosting","Configuración de variables de entorno mediante Cloudflare/Vercel","Visualización de registros de despliegue","Adaptación de la configuración de despliegue","Soporte para base de datos provisionada"],"fr":["Déploiement d''applications Bknd sans construction","Compatibilité avec diverses plateformes d''hébergement","Configuration des variables d''environnement via Cloudflare/Vercel","Affichage des journaux de déploiement","Adaptation de la configuration de déploiement","Prise en charge de la base de données provisionnée"],"de":["Bereitstellung von Bknd-Anwendungen ohne Aufbau","Kompatibilität mit verschiedenen Hosting-Plattformen","Konfiguration von Umgebungsvariablen über Cloudflare/Vercel","Anzeige von Bereitstellungsprotokollen","Anpassung der Bereitstellungs-Konfiguration","Unterstützung für bereitgestellte Datenbanken"],"pt":["Implantação de aplicativos Bknd em diferentes plataformas de hospedagem","Sem necessidade de compilação","Suporte a variáveis de ambiente","Configuração de deploy personalizada","Logs de deploy visíveis no modo UI","Comandos de deploy personalizados no modo Code"],"ru":["Развертывание приложений Bknd на различных платформах хостинга","Без необходимости сборки","Поддержка переменных окружения","Настройка развертывания под вашу потребность","Журналы развертывания доступны в режиме UI","Пользовательские команды развертывания в режиме Code"],"ar":["نشر تطبيقات Bknd على منصات استضافة مختلفة","دون الحاجة إلى بناء","دعم متغيرات البيئة","تكوين نشر مخصص","سجلات النشر مرئية في الوضع UI","أوامر نشر مخصصة في الوضع Code"]},"keywords":{"en":["how to use bknd-deploy-hosting","bknd-deploy-hosting setup guide","bknd-deploy-hosting vs vercel","bknd-deploy-hosting install","what is bknd-deploy-hosting","bknd-deploy-hosting alternative","bknd-deploy-hosting cloudflare integration","bknd-deploy-hosting code mode","bknd-deploy-hosting ui mode"],"zh":["Bknd部署托管","AI工具","Web标准","Cloudflare","Vercel","环境变量","部署设置","deployment logs"],"ja":["Bkndデプロイホスティング","AIエージェント","Web標準","Cloudflare","Vercel","環境変数","デプロイ設定","デプロイログ"],"ko":["Bknd 배포 호스팅","AI 에이전트","웹 표준","Cloudflare","Vercel","환경 변수","배포 설정","배포 로그"],"es":["despliegue de aplicaciones","bknd-deploy-hosting","herramientas de despliegue","plataformas de hosting","configuración de variables de entorno","registros de despliegue","adaptación de configuración","base de datos provisionada","Agentes de IA para desarrolladores"],"fr":["déploiement d''applications","bknd-deploy-hosting","outils de déploiement","plateformes d''hébergement","configuration des variables d''environnement","journaux de déploiement","adaptation de configuration","base de données provisionnée","Outils d''IA pour les développeurs"],"de":["Bereitstellung von Anwendungen","bknd-deploy-hosting","Tools für die Bereitstellung","Hosting-Plattformen","Konfiguration von Umgebungsvariablen","Bereitstellungsprotokolle","Anpassung der Konfiguration","bereitgestellte Datenbanken","AI-Tools für Entwickler"],"pt":["bknd-deploy-hosting","implantação de aplicativos","plataformas de hospedagem","variáveis de ambiente","configuração de deploy","logs de deploy","comandos de deploy","desenvolvimento de aplicativos","hospedagem de aplicativos"],"ru":["bknd-deploy-hosting","развертывание приложений","платформы хостинга","переменные окружения","настройка развертывания","журналы развертывания","команды развертывания","разработка приложений","хостинг приложений","ИИ Агенты"],"ar":["bknd-deploy-hosting","نشر تطبيقات","منصات استضافة","متغيرات البيئة","تكوين نشر","سجلات النشر","أوامر النشر","تطوير تطبيقات","استضافة تطبيقات","أدوات الذكاء الاصطناعي"]}},"owner":"cameronapak","repo":"freedom-stack-v3","repoPath":"cameronapak/freedom-stack-v3","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"bknd-deploy-hosting","description":"Use when deploying a Bknd application to production hosting. Covers Cloudflare Workers/Pages, Node.js/Bun servers, Docker, Vercel, AWS Lambda, and other platforms.","bodyPreview":"# Deploy to Hosting\n\nDeploy your Bknd application to various hosting platforms.\n\n## Prerequisites\n\n- Working Bknd application locally\n- Schema defined and tested\n- Database provisioned (see `bknd-database-provision`)\n- Environment variables prepared (see `bknd-env-config`)\n\n## When to Use UI Mode\n\n- Cloudflare/Vercel dashboards for environment variables\n- Platform-specific deployment settings\n- Viewing deployment logs\n\n## When to Use Code Mode\n\n- All deployment configuration and commands\n- Adapt","body":"# Deploy to Hosting\n\nDeploy your Bknd application to various hosting platforms.\n\n## Prerequisites\n\n- Working Bknd application locally\n- Schema defined and tested\n- Database provisioned (see `bknd-database-provision`)\n- Environment variables prepared (see `bknd-env-config`)\n\n## When to Use UI Mode\n\n- Cloudflare/Vercel dashboards for environment variables\n- Platform-specific deployment settings\n- Viewing deployment logs\n\n## When to Use Code Mode\n\n- All deployment configuration and commands\n- Adapter setup for target platform\n- CI/CD pipeline configuration\n\n## Platform Selection Guide\n\n| Platform | Best For | Database Options | Cold Start |\n|----------|----------|------------------|------------|\n| **Cloudflare Workers** | Edge, global low-latency | D1, Turso | ~0ms |\n| **Cloudflare Pages** | Static + API | D1, Turso | ~0ms |\n| **Vercel** | Next.js apps | Turso, Neon | ~200ms |\n| **Node.js/Bun VPS** | Full control, dedicated | Any | N/A |\n| **Docker** | Containerized, portable | Any | N/A |\n| **AWS Lambda** | Serverless, pay-per-use | Turso, RDS | ~500ms |\n\n## Code Approach\n\n### Cloudflare Workers\n\n**Step 1: Install Wrangler**\n\n```bash\nnpm install -D wrangler\n```\n\n**Step 2: Create `wrangler.toml`**\n\n```toml\nname = \"my-bknd-app\"\nmain = \"src/index.ts\"\ncompatibility_date = \"2024-01-01\"\n\n[[d1_databases]]\nbinding = \"DB\"\ndatabase_name = \"my-database\"\ndatabase_id = \"your-d1-database-id\"\n\n# Optional: R2 for media storage\n[[r2_buckets]]\nbinding = \"R2_BUCKET\"\nbucket_name = \"my-bucket\"\n\n[vars]\nENVIRONMENT = \"production\"\n```\n\n**Step 3: Configure Adapter**\n\n```typescript\n// src/index.ts\nimport { hybrid, type CloudflareBkndConfig } from \"bknd/adapter/cloudflare\";\nimport { d1Sqlite } from \"bknd/adapter/cloudflare\";\nimport { em, entity, text } from \"bknd\";\n\nconst schema = em({\n  posts: entity(\"posts\", {\n    title: text().required(),\n  }),\n});\n\nexport default hybrid<CloudflareBkndConfig>({\n  app: (env) => ({\n    connection: d1Sqlite({ binding: env.DB }),\n    schema,\n    isProduction: true,\n    auth: {\n      jwt: {\n        secret: env.JWT_SECRET,\n      },\n    },\n    config: {\n      media: {\n        enabled: true,\n        adapter: {\n          type: \"r2\",\n          config: { bucket: env.R2_BUCKET },\n        },\n      },\n    },\n  }),\n});\n```\n\n**Step 4: Create D1 Database**\n\n```bash\n# Create database\nwrangler d1 create my-database\n\n# Copy the database_id to wrangler.toml\n```\n\n**Step 5: Set Secrets**\n\n```bash\nwrangler secret put JWT_SECRET\n# Enter your secret (min 32 chars)\n```\n\n**Step 6: Deploy**\n\n```bash\nwrangler deploy\n```\n\n---\n\n### Cloudflare Pages (with Functions)\n\n**Step 1: Create `functions/api/[[bknd]].ts`**\n\n```typescript\nimport { hybrid, type CloudflareBkndConfig } from \"bknd/adapter/cloudflare\";\nimport { d1Sqlite } from \"bknd/adapter/cloudflare\";\nimport schema from \"../../bknd.config\";\n\nexport const onRequest = hybrid<CloudflareBkndConfig>({\n  app: (env) => ({\n    connection: d1Sqlite({ binding: env.DB }),\n    schema,\n    isProduction: true,\n    auth: {\n      jwt: { secret: env.JWT_SECRET },\n    },\n  }),\n});\n```\n\n**Step 2: Configure Pages**\n\nIn Cloudflare dashboard:\n1. Connect your git repository\n2. Set build command (if any)\n3. Add D1 binding under Settings > Functions > D1 Database Bindings\n4. Add environment variables under Settings > Environment Variables\n\n---\n\n### Node.js / Bun (VPS)\n\n**Step 1: Create Production Entry**\n\n```typescript\n// index.ts\nimport { serve, type BunBkndConfig } from \"bknd/adapter/bun\";\n// or for Node.js:\n// import { serve } from \"bknd/adapter/node\";\n\nconst config: BunBkndConfig = {\n  connection: {\n    url: process.env.DB_URL!,\n    authToken: process.env.DB_TOKEN,\n  },\n  isProduction: true,\n  auth: {\n    jwt: {\n      secret: process.env.JWT_SECRET!,\n      expires: \"7d\",\n    },\n  },\n  config: {\n    media: {\n      enabled: true,\n      adapter: {\n        type: \"s3\",\n        config: {\n          bucket: process.env.S3_BUCKET!,\n          region: process.env.S3_REGION!,\n          accessKeyId: process.env.S3_ACCESS_KEY!,\n          secretAccessKey: process.env.S3_SECRET_KEY!,\n        },\n      },\n    },\n    guard: {\n      enabled: true,\n    },\n  },\n};\n\nserve(config);\n```\n\n**Step 2: Set Environment Variables**\n\n```bash\nexport DB_URL=\"libsql://your-db.turso.io\"\nexport DB_TOKEN=\"your-turso-token\"\nexport JWT_SECRET=\"your-32-char-minimum-secret\"\nexport PORT=3000\n```\n\n**Step 3: Run with Process Manager**\n\n```bash\n# Using PM2\nnpm install -g pm2\npm2 start \"bun run index.ts\" --name bknd-app\n\n# Or systemd (create /etc/systemd/system/bknd.service)\n```\n\n---\n\n### Docker\n\n**Step 1: Create `Dockerfile`**\n\n```dockerfile\nFROM oven/bun:1.0-alpine\n\nWORKDIR /app\n\nCOPY package.json bun.lockb ./\nRUN bun install --frozen-lockfile --production\n\nCOPY . .\n\n# Create data directory for SQLite (if using file-based)\nRUN mkdir -p /app/data\n\nENV PORT=3000\n\nEXPOSE 3000\n\nCMD [\"bun\", \"run\", \"index.ts\"]\n```\n\n**Step 2: Create `docker-compose.yml`**\n\n```yaml\nversion: \"3.8\"\nservices:\n  bknd:\n    build: .\n    ports:\n      - \"3000:3000\"\n    volumes:\n      - bknd-data:/app/data\n    environment:\n      - DB_URL=file:/app/data/bknd.db\n      - JWT_SECRET=${JWT_SECRET}\n      - NODE_ENV=production\n    restart: unless-stopped\n\nvolumes:\n  bknd-data:\n```\n\n**Step 3: Deploy**\n\n```bash\n# Build and run\ndocker compose up -d\n\n# View logs\ndocker compose logs -f bknd\n```\n\n---\n\n### Vercel (Next.js)\n\n**Step 1: Create API Route**\n\n```typescript\n// app/api/bknd/[[...bknd]]/route.ts\nexport { GET, POST, PUT, DELETE, PATCH } from \"bknd/adapter/nextjs\";\n```\n\n**Step 2: Create `bknd.config.ts`**\n\n```typescript\nimport type { NextjsBkndConfig } from \"bknd/adapter/nextjs\";\nimport { em, entity, text } from \"bknd\";\n\nconst schema = em({\n  posts: entity(\"posts\", {\n    title: text().required(),\n  }),\n});\n\ntype Database = (typeof schema)[\"DB\"];\ndeclare module \"bknd\" {\n  interface DB extends Database {}\n}\n\nexport default {\n  app: (env) => ({\n    connection: {\n      url: env.DB_URL,\n      authToken: env.DB_TOKEN,\n    },\n    schema,\n    isProduction: env.NODE_ENV === \"production\",\n    auth: {\n      jwt: { secret: env.JWT_SECRET },\n    },\n  }),\n} satisfies NextjsBkndConfig;\n```\n\n**Step 3: Set Vercel Environment Variables**\n\nIn Vercel dashboard or CLI:\n\n```bash\nvercel env add DB_URL\nvercel env add DB_TOKEN\nvercel env add JWT_SECRET\n```\n\n**Step 4: Deploy**\n\n```bash\nvercel deploy --prod\n```\n\n---\n\n### AWS Lambda\n\n**Step 1: Install Dependencies**\n\n```bash\nnpm install -D serverless serverless-esbuild\n```\n\n**Step 2: Create `handler.ts`**\n\n```typescript\nimport { createHandler } from \"bknd/adapter/aws\";\n\nexport const handler = createHandler({\n  connection: {\n    url: process.env.DB_URL!,\n    authToken: process.env.DB_TOKEN,\n  },\n  isProduction: true,\n  auth: {\n    jwt: { secret: process.env.JWT_SECRET! },\n  },\n});\n```\n\n**Step 3: Create `serverless.yml`**\n\n```yaml\nservice: bknd-api\n\nprovider:\n  name: aws\n  runtime: nodejs20.x\n  region: us-east-1\n  environment:\n    DB_URL: ${env:DB_URL}\n    DB_TOKEN: ${env:DB_TOKEN}\n    JWT_SECRET: ${env:JWT_SECRET}\n\nplugins:\n  - serverless-esbuild\n\nfunctions:\n  api:\n    handler: handler.handler\n    events:\n      - http:\n          path: /{proxy+}\n          method: ANY\n      - http:\n          path: /\n          method: ANY\n```\n\n**Step 4: Deploy**\n\n```bash\nserverless deploy --stage prod\n```\n\n---\n\n## Pre-Deployment Checklist\n\n```bash\n# 1. Generate types\nnpx bknd types\n\n# 2. Test locally with production-like config\nDB_URL=\"your-prod-db\" JWT_SECRET=\"your-secret\" npx bknd run\n\n# 3. Verify schema sync\n# Schema auto-syncs on first request in production\n```\n\n## Environment Variables (All Platforms)\n\n| Variable | Required | Description |\n|----------|----------|-------------|\n| `DB_URL` | Yes | Database connection URL |\n| `DB_TOKEN` | Depends | Auth token (Turso/LibSQL) |\n| `JWT_SECRET` | Yes | Min 32 chars for security |\n| `PORT` | No | Server port (default: 3000) |\n\n## Common Pitfalls\n\n### \"Module not found\" for Native SQLite\n\n**Problem:** `better-sqlite3` not available in serverless\n\n**Fix:** Use LibSQL/Turso instead of file-based SQLite:\n```typescript\nconnection: {\n  url: \"libsql://your-db.turso.io\",\n  authToken: process.env.DB_TOKEN,\n}\n```\n\n### \"JWT_SECRET required\" Error\n\n**Problem:** Auth fails in production\n\n**Fix:** Set JWT_SECRET environment variable:\n```bash\n# Cloudflare\nwrangler secret put JWT_SECRET\n\n# Vercel\nvercel env add JWT_SECRET\n\n# Docker\ndocker run -e JWT_SECRET=\"your-secret\" ...\n```\n\n### Cold Start Timeouts (Lambda)\n\n**Problem:** First request times out\n\n**Fix:**\n- Use lighter database (Turso over RDS)\n- Reduce bundle size\n- Enable provisioned concurrency for critical functions\n\n### D1 Binding Not Found\n\n**Problem:** `env.DB is undefined`\n\n**Fix:** Check wrangler.toml D1 binding:\n```toml\n[[d1_databases]]\nbinding = \"DB\"  # Must match env.DB in code\ndatabase_name = \"my-database\"\ndatabase_id = \"actual-id-from-wrangler-d1-create\"\n```\n\n### Media Uploads Fail in Serverless\n\n**Problem:** Local storage doesn''t work in serverless\n\n**Fix:** Use cloud storage adapter:\n```typescript\nconfig: {\n  media: {\n    adapter: {\n      type: \"s3\",  // or \"r2\", \"cloudinary\"\n      config: { /* credentials */ },\n    },\n  },\n}\n```\n\n### CORS Errors\n\n**Problem:** Frontend can''t access API\n\n**Fix:** Configure CORS in your adapter:\n```typescript\n// Most adapters handle this automatically\n// For custom needs, check platform docs\n```\n\n## Deployment Commands Reference\n\n```bash\n# Cloudflare Workers\nwrangler deploy\nwrangler tail  # View logs\n\n# Vercel\nvercel deploy --prod\nvercel logs\n\n# Docker\ndocker compose up -d\ndocker compose logs -f\n\n# AWS Lambda\nserverless deploy --stage prod\nserverless logs -f api\n```\n\n## DOs and DON''Ts\n\n**DO:**\n- Set `isProduction: true` in production config\n- Use cloud storage (S3/R2/Cloudinary) for media\n- Set strong JWT_SECRET (min 32 chars)\n- Enable Guard for authorization\n- Test with production database before deploying\n- Use environment variables for all secrets\n\n**DON''T:**\n- Use file-based SQLite in serverless\n- Hardcode secrets in code\n- Deploy without testing schema sync\n- Use local storage adapter in production\n- Skip JWT_SECRET configuration\n- Commit `.env` files with real secrets\n\n## Related Skills\n\n- **bknd-database-provision** - Set up production database\n- **bknd-production-config** - Production security settings\n- **bknd-storage-config** - Configure media storage\n- **bknd-env-config** - Environment variable setup\n- **bknd-local-setup** - Local development (pre-deploy testing)\n"},"lastSynced":"2026-03-08T02:03:06.000Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud-Native Agents needing streamlined deployment to Cloudflare and Vercel with no-build, un-bloated stacks.","zh":"非常适合需要简化部署到 Cloudflare 和 Vercel 的云原生代理，具有无构建、无冗余的栈。","ja":"Cloudflare と Vercel へのデプロイをストリームライン化する必要がある Cloud-Native エージェントに最適です。ビルド不要、無駄のないスタックです。","ko":"Cloudflare와 Vercel에 대한 배포를 간소화해야 하는 클라우드 네이티브 에이전트에 적합합니다. 빌드가 필요하지 않은 간소화된 스택을 제공합니다.","es":"Perfecto para agentes Cloud-Native que necesitan una implementación optimizada en Cloudflare y Vercel con pilas sin compilación y sin sobrecarga.","fr":"Parfait pour les agents Cloud-Native nécessitant un déploiement simplifié sur Cloudflare et Vercel avec des piles sans construction et sans surcharge.","de":"Perfekt für Cloud-Native-Agents, die eine optimierte Bereitstellung in Cloudflare und Vercel mit build-freien, unüberschaubaren Stacks benötigen.","pt":"Perfeito para Agents Cloud-Native que precisam de uma implantação simplificada para Cloudflare e Vercel com pilhas sem compilação e sem excesso de código.","ru":"Идеально подходит для Cloud-Native Agents, которым требуется упрощенная развертка в Cloudflare и Vercel с использованием стеков без сборки и без излишеств.","ar":"مثالي لعميل الحوسبة السحابية الذي يحتاج إلى نشر مبسط إلى Cloudflare و Vercel مع كومة بدون بناء وبدون زوائد."},"recommendation":{"en":"Empowers agents to deploy Bknd applications to multiple hosting platforms using environment variables and platform-specific settings, leveraging Cloudflare and Vercel dashboards for seamless deployment and log viewing.","zh":"赋予代理将 Bknd 应用程序部署到多个托管平台的能力，使用环境变量和特定于平台的设置，利用 Cloudflare 和 Vercel 仪表板实现无缝的部署和日志查看。","ja":"エージェントに、環境変数とプラットフォーム固有の設定を使用して、Bknd アプリケーションを複数のホスティング プラットフォームにデプロイする能力を提供します。Cloudflare と Vercel のダッシュボードを利用して、シームレスなデプロイとログビューを実現します。","ko":"에이전트가 환경 변수와 플랫폼별 설정을 사용하여 Bknd 애플리케이션을 여러 호스팅 플랫폼에 배포할 수 있는 기능을 제공합니다. Cloudflare와 Vercel 대시보드를 활용하여無縫な 배포 및 로그 보기를实现합니다.","es":"Habilita a los agentes a implementar aplicaciones Bknd en varias plataformas de alojamiento utilizando variables de entorno y configuraciones específicas de la plataforma, aprovechando los paneles de Cloudflare y Vercel para una implementación y visualización de registros sin problemas.","fr":"Permet aux agents de déployer des applications Bknd sur plusieurs plateformes d''hébergement en utilisant des variables d''environnement et des paramètres spécifiques à la plateforme, en exploitant les tableaux de bord de Cloudflare et Vercel pour un déploiement et une visualisation de journaux sans accroc.","de":"Ermächtigt Agenten, Bknd-Anwendungen auf mehreren Hosting-Plattformen mithilfe von Umgebungsvariablen und plattformspezifischen Einstellungen zu bereitstellen, indem es die Cloudflare- und Vercel-Dashboards für eine nahtlose Bereitstellung und Protokollanzeige nutzt.","pt":"Habilita os agentes a implantar aplicativos Bknd em várias plataformas de hospedagem usando variáveis de ambiente e configurações específicas da plataforma, aproveitando os painéis de Cloudflare e Vercel para implantação e visualização de logs sem problemas.","ru":"Позволяет агентам развертывать приложения Bknd на нескольких платформах хостинга, используя переменные среды и настройки, специфичные для платформы, используя панели управления Cloudflare и Vercel для бесшовного развертывания и просмотра журналов.","ar":"تمكين العميل من نشر تطبيقات Bknd على منصات استضافة متعددة باستخدام متغيرات البيئة والإعدادات الخاصة بالمنصة ، واستخدام لوحات التحكم في Cloudflare و Vercel لنشر وتحليل السجلات بشكل مُتكامل."},"useCases":{"en":["Deploying Bknd applications to Cloudflare","Configuring environment variables for Vercel hosting","Viewing deployment logs for troubleshooting"],"zh":["将 Bknd 应用程序部署到 Cloudflare","为 Vercel 托管配置环境变量","查看部署日志以进行故障排除"],"ja":["Bknd アプリケーションを Cloudflare にデプロイする","Vercel ホスティングの環境変数を構成する","デプロイ ログを表示してトラブルシューティングを行う"],"ko":["Bknd 애플리케이션을 Cloudflare에 배포한다","Vercel 호스팅을 위한 환경 변수 구성","배포 로그를 보며 트러블슈팅을 수행한다"],"es":["Implementar aplicaciones Bknd en Cloudflare","Configurar variables de entorno para hosting en Vercel","Ver registros de implementación para solucionar problemas"],"fr":["Déployer des applications Bknd sur Cloudflare","Configurer des variables d''environnement pour l''hébergement sur Vercel","Afficher les journaux de déploiement pour la résolution de problèmes"],"de":["Bereitstellen von Bknd-Anwendungen in Cloudflare","Konfigurieren von Umgebungsvariablen für die Ausführung in Vercel","Anzeigen von Bereitstellungsprotokollen zur Fehlerbehebung"],"pt":["Implantando aplicativos Bknd em Cloudflare","Configurando variáveis de ambiente para hospedagem Vercel","Visualizando logs de implantação para solução de problemas"],"ru":["Развертывание приложений Bknd в Cloudflare","Настройка переменных среды для хостинга Vercel","Просмотр журналов развертывания для устранения неполадок"],"ar":["نشر تطبيقات Bknd على Cloudflare","تكوين متغيرات البيئة لاستضافة Vercel","عرض سجلات النشر لحل المشكلات"]},"limitations":{"en":["Requires working Bknd application locally","Schema must be defined and tested","Database must be provisioned"],"zh":["需要在本地工作的 Bknd 应用程序","模式必须定义和测试","数据库必须预配"],"ja":["ローカルで動作する Bknd アプリケーションが必要","スキーマが定義され、テストされている","データベースがプロビジョニングされている"],"ko":["로컬에서 작동하는 Bknd 애플리케이션이 필요하다","스키마가 정의되어 있고 테스트된 것","데이터베이스가 프로비저닝되어야 함"],"es":["Requiere una aplicación Bknd funcionando localmente","El esquema debe estar definido y probado","La base de datos debe estar aprovisionada"],"fr":["Nécessite une application Bknd fonctionnelle en local","Le schéma doit être défini et testé","La base de données doit être provisionnée"],"de":["Benötigt eine funktionierende Bknd-Anwendung lokal","Das Schema muss definiert und getestet werden","Die Datenbank muss bereitgestellt werden"],"pt":["Requer aplicativo Bknd funcionando localmente","O esquema deve ser definido e testado","O banco de dados deve ser provisionado"],"ru":["Требуется работающее приложение Bknd на локальной машине","Схема должна быть определена и протестирована","База данных должна быть подготовлена"],"ar":["يتطلب تطبيق Bknd يعمل محليًا","يجب تعريف مخطط البيانات واختباره","يجب توفير قاعدة البيانات"]},"version":4},"contentHash":"7ca0ed3feae12535774c981c3f6a987f4aed766194f18defee8361bc80b38617","qualityScore":54}');
