INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cameronapak/freedom-stack-v3/bknd-deploy-hosting', 'bknd-deploy-hosting', 'cameronapak', 'freedom-stack-v3', 'community', 'bknd-deploy-hosting cameronapak freedom-stack-v3 community The bknd-deploy-hosting skill enables developers to deploy their Bknd applications to multiple hosting platforms, including Cloudflare and Vercel, with a no-build, un-bloated stack. It benefits developers who need a flexible and efficient deployment process. Bknd部署托管是一个无需构建、无冗余的栈，基于Web标准，能够轻松部署到任何地方 Bkndデプロイホスティングは、ビルド不要、無駄のないスタックで、Web標準に基づいており、どこにでも簡単にデプロイできます Bknd 배포 호스팅은 빌드가 필요 없는 부풀리지 않은 스택으로, 웹 표준을 기반으로 하여 어디에でも 쉽게 배포할 수 있습니다 El skill de bknd-deploy-hosting permite desplegar aplicaciones Bknd en diferentes plataformas de hosting sin necesidad de construir. Se basa en estándares web y ofrece una experiencia de uso liberadora. Le skill de bknd-deploy-hosting permet de déployer des applications Bknd sur diverses plateformes d''hébergement sans nécessité de construction. Il repose sur les normes web et offre une expérience d''utilisation libératrice. Der bknd-deploy-hosting-Skill ermöglicht die Bereitstellung von Bknd-Anwendungen auf verschiedenen Hosting-Plattformen ohne Aufbau. Er basiert auf Web-Standards und bietet eine befreiende Benutzererfahrung. O skill bknd-deploy-hosting permite a implantação de aplicativos Bknd em diferentes plataformas de hospedagem, sem a necessidade de compilação. Навык bknd-deploy-hosting позволяет развертывать приложения Bknd на различных платформах хостинга без необходимости сборки. تمكن مهارة bknd-deploy-hosting من نشر تطبيقات Bknd على منصات استضافة مختلفة دون الحاجة إلى بناء how to use bknd-deploy-hosting bknd-deploy-hosting setup guide bknd-deploy-hosting vs vercel bknd-deploy-hosting install what is bknd-deploy-hosting bknd-deploy-hosting alternative bknd-deploy-hosting cloudflare integration bknd-deploy-hosting code mode bknd-deploy-hosting ui mode Bknd部署托管 AI工具 Web标准 Cloudflare Vercel 环境变量 部署设置 deployment logs Deploy Bknd applications to Cloudflare and Vercel dashboards Utilize environment variables prepared with bknd-env-config Provision databases using bknd-database-provision View deployment logs in UI Mode Configure deployment settings using Code Mode Adapt deployment configuration and commands bknd-deploy-hosting is a skill that allows for the deployment of Bknd applications to various hosting platforms, utilizing Web Standards and supporting both UI and Code modes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('offloadmywork/pokemon-app/base44-sdk', 'community', 'offloadmywork', 'pokemon-app', 'offloadmywork/pokemon-app', 'base44-sdk', 0, 0, 54, '2026-03-08T01:57:15.329Z', '2026-03-08T02:03:10.271Z', '981c78c1075d71e505280d3ab8584b7e65314004408e701800698e28eecb1a6b', '{"id":"offloadmywork/pokemon-app/base44-sdk","name":"base44-sdk","description":{"en":"The base44-sdk skill enables developers to build apps on the Base44 platform using React and Cloudflare Workers, handling requests and implementing features","zh":"Base44 SDK 是一个使用 React 和 Cloudflare Workers 构建 Pokémon 游戏的工具，提供了一种快速简单的开发方式","ja":"Base44 SDK は、React と Cloudflare Workers を使用して Pokémon ゲームを構築するツールで、迅速な開発方法を提供します","ko":"Base44 SDK는 React와 Cloudflare Workers를 사용하여 Pokémon 게임을 구축하는 도구로 빠르고 간단한 개발 방법을 제공합니다","es":"Base44-sdk es un kit de desarrollo para construir aplicaciones en la plataforma Base44 con React y Cloudflare Workers. Permite implementar características y gestionar proyectos de manera eficiente","fr":"Base44-sdk est un kit de développement pour créer des applications sur la plateforme Base44 avec React et Cloudflare Workers. Il permet de mettre en œuvre des fonctionnalités et de gérer des projets de manière efficace","de":"Base44-sdk ist ein Entwicklungskit für den Bau von Anwendungen auf der Base44-Plattform mit React und Cloudflare Workers. Es ermöglicht die Implementierung von Funktionen und die effiziente Verwaltung von Projekten","pt":"O base44-sdk é uma plataforma para construir aplicações com React e Cloudflare Workers. Aprenda a configurar e usar a plataforma para desenvolver aplicações personalizadas.","ru":"Base44-sdk - это платформа для разработки приложений с использованием React и Cloudflare Workers. Узнайте, как настроить и использовать платформу для создания индивидуальных приложений.","ar":"base44-sdk هي منصة لبناء التطبيقات مع React و Cloudflare Workers. تعلم كيفية إعداد واستخدام المنصة لإنشاء تطبيقات مخصصة."},"seo":{"title":{"en":"base44-sdk: React and Cloudflare Workers Setup Guide | AI...","zh":"Base44 SDK 指南：使用 React 和 Cloudflare Workers 构建 Pokémon 游戏","ja":"Base44 SDK セットアップガイド：React と Cloudflare Workers で Pokémon...","ko":"Base44 SDK 설정 가이드: React와 Cloudflare Workers로 Pokémon 게임 구축","es":"Guía de configuración de base44-sdk para desarrolladores","fr":"Configurer base44-sdk pour les développeurs - Guide étape...","de":"Einrichten von base44-sdk für Entwickler - Schritt-für-Sc...","pt":"Guia de Configuração do base44-sdk: Desenvolvimento de Ap...","ru":"Настройка base44-sdk: Руководство по разработке приложени...","ar":"دليل إعداد base44-sdk: بناء تطبيقات مع React و Cloudflare..."},"description":{"en":"Unlock the power of base44-sdk! Discover how to build apps with React and Cloudflare Workers, and get started with our expert setup guide","zh":"了解如何使用 Base44 SDK 构建 Pokémon 游戏，结合 React 和 Cloudflare Workers 的强大功能","ja":"Base44 SDK を使用して Pokémon ゲームを構築する方法を学び、React と Cloudflare Workers の強力な機能を活用しましょう","ko":"Base44 SDK를 사용하여 Pokémon 게임을 구축하는 방법을 알아보고 React와 Cloudflare Workers의 강력한 기능을 활용하세요","es":"Aprende a configurar base44-sdk para tus proyectos de desarrollo con React y Cloudflare Workers. Descubre cómo implementar características y más","fr":"Découvrez comment configurer base44-sdk pour vos projets de développement avec React et Cloudflare Workers. Étapes à suivre et fonctionnalités","de":"Erfahren Sie, wie Sie base44-sdk für Ihre Entwicklungsprojekte mit React und Cloudflare Workers einrichten. Schritt-für-Schritt-Anleitungen und Funktionen","pt":"Aprenda a configurar o base44-sdk para desenvolver aplicações com React e Cloudflare Workers. Guia passo a passo para começar a usar a plataforma base44.","ru":"Узнайте, как настроить base44-sdk для разработки приложений с использованием React и Cloudflare Workers. Шаг за шагом руководство по началу работы с платформ...","ar":"تعلم كيفية إعداد base44-sdk لإنشاء تطبيقات مع React و Cloudflare Workers. دليل خطوة بخطوة للبدء في استخدام منصة base44."},"definition":{"en":"base44-sdk is a JavaScript SDK for building apps on the Base44 platform, utilizing React and Cloudflare Workers","zh":"Base44 SDK 是一个用于构建 Pokémon 游戏的 JavaScript SDK，支持 React 和 Cloudflare Workers","ja":"Base44 SDK は、React と Cloudflare Workers をサポートする Pokémon ゲーム構築用の JavaScript SDK です","ko":"Base44 SDK는 React와 Cloudflare Workers를 지원하는 Pokémon 게임 구축용 JavaScript SDK입니다","es":"Base44-sdk es un kit de desarrollo de software que permite a los desarrolladores crear aplicaciones en la plataforma Base44","fr":"Base44-sdk est un kit de développement logiciel qui permet aux développeurs de créer des applications sur la plateforme Base44","de":"Base44-sdk ist ein Software-Entwicklungskit, der es Entwicklern ermöglicht, Anwendungen auf der Base44-Plattform zu erstellen","pt":"O base44-sdk é um kit de desenvolvimento de software que permite construir aplicações com React e Cloudflare Workers.","ru":"Base44-sdk - это набор разработки программного обеспечения, который позволяет создавать приложения с использованием React и Cloudflare Workers.","ar":"base44-sdk هو حزمة تطوير برمجية تسمح ببناء التطبيقات مع React و Cloudflare Workers."},"features":{"en":["Checks for existing base44/config.jsonc files in the current directory","Handles requests when a base44/ folder exists","Implements features based on the Base44 platform","Uses React for building app interfaces","Leverages Cloudflare Workers for serverless functionality","Activates on mentions of ''base44'' for immediate action"],"zh":["使用 React 构建 Pokémon 游戏","集成 Cloudflare Workers 实现高性能","支持 base44/config.jsonc 配置文件","自动检测 base44/ 文件夹","快速简单的开发方式"],"ja":["React を使用して Pokémon ゲームを構築","Cloudflare Workers を統合して高パフォーマンスを実現","base44/config.jsonc 構成ファイルをサポート","base44/ フォルダを自動検出","迅速な開発方法"],"ko":["React를 사용하여 Pokémon 게임 구축","Cloudflare Workers를 통합하여 고성능 구현","base44/config.jsonc 구성 파일 지원","base44/ 폴더 자동 검출","빠르고 간단한 개발 방법"],"es":["Implementación de características con React","Integración con Cloudflare Workers","Gestión de proyectos con base44/config.jsonc","Compatibilidad con la plataforma Base44","Desarrollo de aplicaciones con JavaScript"],"fr":["Mise en œuvre de fonctionnalités avec React","Intégration avec Cloudflare Workers","Gestion de projets avec base44/config.jsonc","Compatibilité avec la plateforme Base44","Développement d''applications avec JavaScript"],"de":["Implementierung von Funktionen mit React","Integration mit Cloudflare Workers","Projektverwaltung mit base44/config.jsonc","Kompatibilität mit der Base44-Plattform","Anwendungsentwicklung mit JavaScript"],"pt":["Desenvolvimento de aplicações com React","Integração com Cloudflare Workers","Configuração simplificada com base44/config.jsonc","Implementação de recursos personalizados","Suporte a projetos existentes com base44/"],"ru":["Разработка приложений с использованием React","Интеграция с Cloudflare Workers","Упрощенная настройка с base44/config.jsonc","Реализация индивидуальных функций","Поддержка существующих проектов с base44/"],"ar":["بناء التطبيقات مع React","التكامل مع Cloudflare Workers","إعداد مبسط مع base44/config.jsonc","تنفيذ ميزات مخصصة","دعم المشاريع الحالية مع base44/"]},"keywords":{"en":["how to use base44-sdk","what is base44-sdk","base44-sdk alternative","base44-sdk vs react-sdk","base44-sdk install","base44-sdk setup guide","cloudflare workers tutorial","react and cloudflare workers integration"],"zh":["Base44 SDK","React","Cloudflare Workers","Pokémon 游戏","JavaScript SDK","AI エージェント","AI 工具","游戏开发","云计算"],"ja":["Base44 SDK","React","Cloudflare Workers","Pokémon ゲーム","JavaScript SDK","AI エージェント","AI ツール","ゲーム開発","クラウドコンピューティング"],"ko":["Base44 SDK","React","Cloudflare Workers","Pokémon 게임","JavaScript SDK","AI 에이전트","AI 도구","게임 개발","클라우드 컴퓨팅"],"es":["base44-sdk","desarrollo de aplicaciones","React","Cloudflare Workers","JavaScript","kit de desarrollo","Base44","herramientas de desarrollo","desarrollo web","AI Agentes"],"fr":["base44-sdk","développement d''applications","React","Cloudflare Workers","JavaScript","kit de développement","Base44","outils de développement","développement web","Agents IA"],"de":["base44-sdk","Anwendungsentwicklung","React","Cloudflare Workers","JavaScript","Entwicklungskit","Base44","Entwicklungstools","Webentwicklung","KI-Tools"],"pt":["base44-sdk","desenvolvimento de aplicações","React","Cloudflare Workers","configuração de plataforma","desenvolvimento de software","kit de desenvolvimento","ferramentas de desenvolvimento","tecnologias de desenvolvimento"],"ru":["base44-sdk","разработка приложений","React","Cloudflare Workers","настройка платформы","разработка программного обеспечения","набор разработки","инструменты разработки","технологии разработки"],"ar":["base44-sdk","بناء التطبيقات","React","Cloudflare Workers","إعداد المنصة","تطوير البرمجيات","حزمة التطوير","أدوات التطوير","تقنيات التطوير"]}},"owner":"offloadmywork","repo":"pokemon-app","repoPath":"offloadmywork/pokemon-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.329Z","topics":[],"category":"community","skillMd":{"name":"base44-sdk","description":"The base44 SDK is the library to communicate with base44 services. In projects, you use it to communicate with remote resources (entities, backend functions, ai agents) and to write backend functions. This skill is the place for learning about available modules and types. When you plan or implement a feature, you must learn this skill","bodyPreview":"# Base44 Coder\n\nBuild apps on the Base44 platform using the Base44 JavaScript SDK.\n\n## ⚡ IMMEDIATE ACTION REQUIRED - Read This First\n\nThis skill activates on ANY mention of \"base44\" or when a `base44/` folder exists. **DO NOT read documentation files or search the web before acting.**\n\n**Your first action MUST be:**\n1. Check if `base44/config.jsonc` exists in the current directory\n2. If **YES** (existing project scenario):\n   - This skill (base44-sdk) handles the request\n   - Implement features","body":"# Base44 Coder\n\nBuild apps on the Base44 platform using the Base44 JavaScript SDK.\n\n## ⚡ IMMEDIATE ACTION REQUIRED - Read This First\n\nThis skill activates on ANY mention of \"base44\" or when a `base44/` folder exists. **DO NOT read documentation files or search the web before acting.**\n\n**Your first action MUST be:**\n1. Check if `base44/config.jsonc` exists in the current directory\n2. If **YES** (existing project scenario):\n   - This skill (base44-sdk) handles the request\n   - Implement features using Base44 SDK\n   - Do NOT use base44-cli unless user explicitly requests CLI commands\n3. If **NO** (new project scenario):\n   - Transfer to base44-cli skill for project initialization\n   - This skill cannot help until project is initialized\n\n## When to Use This Skill vs base44-cli\n\n**Use base44-sdk when:**\n- Building features in an **EXISTING** Base44 project\n- `base44/config.jsonc` already exists in the project\n- Base44 SDK imports are present (`@base44/sdk`)\n- Writing JavaScript/TypeScript code using Base44 SDK modules\n- Implementing functionality, components, or features\n- User mentions: \"implement\", \"build a feature\", \"add functionality\", \"write code for\"\n- User says \"create a [type] app\" **and** a Base44 project already exists\n\n**DO NOT USE base44-sdk for:**\n- ❌ Initializing new Base44 projects (use `base44-cli` instead)\n- ❌ Empty directories without Base44 configuration\n- ❌ When user says \"create a new Base44 project/app/site\" and no project exists\n- ❌ CLI commands like `npx base44 create`, `npx base44 deploy`, `npx base44 login` (use `base44-cli`)\n\n**Skill Dependencies:**\n- `base44-sdk` assumes a Base44 project is **already initialized**\n- `base44-cli` is a **prerequisite** for `base44-sdk` in new projects\n- If user wants to \"create an app\" and no Base44 project exists, use `base44-cli` first\n\n**State Check Logic:**\nBefore selecting this skill, verify:\n- IF (user mentions \"create/build app\" OR \"make a project\"):\n  - IF (directory is empty OR no `base44/config.jsonc` exists):\n    → Use **base44-cli** (project initialization needed)\n  - ELSE:\n    → Use **base44-sdk** (project exists, build features)\n\n## Quick Start\n\n```javascript\n// In Base44-generated apps, base44 client is pre-configured and available\n\n// CRUD operations\nconst task = await base44.entities.Task.create({ title: \"New task\", status: \"pending\" });\nconst tasks = await base44.entities.Task.list();\nawait base44.entities.Task.update(task.id, { status: \"done\" });\n\n// Get current user\nconst user = await base44.auth.me();\n```\n\n```javascript\n// External apps\nimport { createClient } from \"@base44/sdk\";\n\n// IMPORTANT: Use ''appId'' (NOT ''clientId'' or ''id'')\nconst base44 = createClient({ appId: \"your-app-id\" });\nawait base44.auth.loginViaEmailPassword(\"user@example.com\", \"password\");\n```\n\n## ⚠️ CRITICAL: Do Not Hallucinate APIs\n\n**Before writing ANY Base44 code, verify method names against this table or [QUICK_REFERENCE.md](references/QUICK_REFERENCE.md).**\n\nBase44 SDK has unique method names. Do NOT assume patterns from Firebase, Supabase, or other SDKs.\n\n### Authentication - WRONG vs CORRECT\n\n| ❌ WRONG (hallucinated) | ✅ CORRECT |\n|------------------------|-----------|\n| `signInWithGoogle()` | `loginWithProvider(''google'')` |\n| `signInWithProvider(''google'')` | `loginWithProvider(''google'')` |\n| `auth.google()` | `loginWithProvider(''google'')` |\n| `signInWithEmailAndPassword(email, pw)` | `loginViaEmailPassword(email, pw)` |\n| `signIn(email, pw)` | `loginViaEmailPassword(email, pw)` |\n| `createUser()` / `signUp()` | `register({email, password})` |\n| `onAuthStateChanged()` | `me()` (no listener, call when needed) |\n| `currentUser` | `await auth.me()` |\n\n### Functions - WRONG vs CORRECT\n\n| ❌ WRONG (hallucinated) | ✅ CORRECT |\n|------------------------|-----------|\n| `functions.call(''name'', data)` | `functions.invoke(''name'', data)` |\n| `functions.run(''name'', data)` | `functions.invoke(''name'', data)` |\n| `callFunction(''name'', data)` | `functions.invoke(''name'', data)` |\n| `httpsCallable(''name'')(data)` | `functions.invoke(''name'', data)` |\n\n### Integrations - WRONG vs CORRECT\n\n| ❌ WRONG (hallucinated) | ✅ CORRECT |\n|------------------------|-----------|\n| `ai.generate(prompt)` | `integrations.Core.InvokeLLM({prompt})` |\n| `openai.chat(prompt)` | `integrations.Core.InvokeLLM({prompt})` |\n| `llm(prompt)` | `integrations.Core.InvokeLLM({prompt})` |\n| `sendEmail(to, subject, body)` | `integrations.Core.SendEmail({to, subject, body})` |\n| `email.send()` | `integrations.Core.SendEmail({to, subject, body})` |\n| `uploadFile(file)` | `integrations.Core.UploadFile({file})` |\n| `storage.upload(file)` | `integrations.Core.UploadFile({file})` |\n\n### Entities - WRONG vs CORRECT\n\n| ❌ WRONG (hallucinated) | ✅ CORRECT |\n|------------------------|-----------|\n| `entities.Task.find({...})` | `entities.Task.filter({...})` |\n| `entities.Task.findOne(id)` | `entities.Task.get(id)` |\n| `entities.Task.insert(data)` | `entities.Task.create(data)` |\n| `entities.Task.remove(id)` | `entities.Task.delete(id)` |\n| `entities.Task.onChange(cb)` | `entities.Task.subscribe(cb)` |\n\n## SDK Modules\n\n| Module | Purpose | Reference |\n|--------|---------|-----------|\n| `entities` | CRUD operations on data models | [entities.md](references/entities.md) |\n| `auth` | Login, register, user management | [auth.md](references/auth.md) |\n| `agents` | AI conversations and messages | [base44-agents.md](references/base44-agents.md) |\n| `functions` | Backend function invocation | [functions.md](references/functions.md) |\n| `integrations` | AI, email, file uploads, custom APIs | [integrations.md](references/integrations.md) |\n| `connectors` | OAuth tokens (service role only) | [connectors.md](references/connectors.md) |\n| `analytics` | Track custom events and user activity | [analytics.md](references/analytics.md) |\n| `appLogs` | Log user activity in app | [app-logs.md](references/app-logs.md) |\n| `users` | Invite users to the app | [users.md](references/users.md) |\n\nFor client setup and authentication modes, see [client.md](references/client.md).\n\n**TypeScript Support:** Each reference file includes a \"Type Definitions\" section with TypeScript interfaces and types for the module''s methods, parameters, and return values.\n\n## Installation\n\nInstall the Base44 SDK:\n\n```bash\nnpm install @base44/sdk\n```\n\n**Important:** Never assume or hardcode the `@base44/sdk` package version. Always install without a version specifier to get the latest version.\n\n## Creating a Client (External Apps)\n\nWhen creating a client in external apps, **ALWAYS use `appId` as the parameter name**:\n\n```javascript\nimport { createClient } from \"@base44/sdk\";\n\n// ✅ CORRECT\nconst base44 = createClient({ appId: \"your-app-id\" });\n\n// ❌ WRONG - Do NOT use these:\n// const base44 = createClient({ clientId: \"your-app-id\" });  // WRONG\n// const base44 = createClient({ id: \"your-app-id\" });        // WRONG\n```\n\n**Required parameter:** `appId` (string) - Your Base44 application ID\n\n**Optional parameters:**\n- `token` (string) - Pre-authenticated user token\n- `options` (object) - Configuration options\n  - `options.onError` (function) - Global error handler\n\n**Example with error handler:**\n```javascript\nconst base44 = createClient({\n  appId: \"your-app-id\",\n  options: {\n    onError: (error) => {\n      console.error(\"Base44 error:\", error);\n    }\n  }\n});\n```\n\n## Module Selection\n\n**Working with app data?**\n- Create/read/update/delete records → `entities`\n- Import data from file → `entities.importEntities()`\n- Realtime updates → `entities.EntityName.subscribe()`\n\n**User management?**\n- Login/register/logout → `auth`\n- Get current user → `auth.me()`\n- Update user profile → `auth.updateMe()`\n- Invite users → `users.inviteUser()`\n\n**AI features?**\n- Chat with AI agents → `agents` (requires logged-in user)\n- Create new conversation → `agents.createConversation()`\n- Manage conversations → `agents.getConversations()`\n- Generate text/JSON with AI → `integrations.Core.InvokeLLM()`\n- Generate images → `integrations.Core.GenerateImage()`\n\n**Custom backend logic?**\n- Run server-side code → `functions.invoke()`\n- Need admin access → `base44.asServiceRole.functions.invoke()`\n\n**External services?**\n- Send emails → `integrations.Core.SendEmail()`\n- Upload files → `integrations.Core.UploadFile()`\n- Custom APIs → `integrations.custom.call()`\n- OAuth tokens (Google, Slack) → `connectors` (backend only)\n\n**Tracking and analytics?**\n- Track custom events → `analytics.track()`\n- Log page views/activity → `appLogs.logUserInApp()`\n\n## Common Patterns\n\n### Filter and Sort Data\n\n```javascript\nconst pendingTasks = await base44.entities.Task.filter(\n  { status: \"pending\", assignedTo: userId },  // query\n  \"-created_date\",                             // sort (descending)\n  10,                                          // limit\n  0                                            // skip\n);\n```\n\n### Protected Routes (check auth)\n\n```javascript\nconst user = await base44.auth.me();\nif (!user) {\n  // Navigate to your custom login page\n  navigate(''/login'', { state: { returnTo: window.location.pathname } });\n  return;\n}\n```\n\n### Backend Function Call\n\n```javascript\n// Frontend\nconst result = await base44.functions.invoke(\"processOrder\", {\n  orderId: \"123\",\n  action: \"ship\"\n});\n\n// Backend function (Deno)\nimport { createClientFromRequest } from \"npm:@base44/sdk\";\n\nDeno.serve(async (req) => {\n  const base44 = createClientFromRequest(req);\n  const { orderId, action } = await req.json();\n  // Process with service role for admin access\n  const order = await base44.asServiceRole.entities.Orders.get(orderId);\n  return Response.json({ success: true });\n});\n```\n\n### Service Role Access\n\nUse `asServiceRole` in backend functions for admin-level operations:\n\n```javascript\n// User mode - respects permissions\nconst myTasks = await base44.entities.Task.list();\n\n// Service role - full access (backend only)\nconst allTasks = await base44.asServiceRole.entities.Task.list();\nconst token = await base44.asServiceRole.connectors.getAccessToken(\"slack\");\n```\n\n## Frontend vs Backend\n\n| Capability | Frontend | Backend |\n|------------|----------|---------|\n| `entities` (user''s data) | Yes | Yes |\n| `auth` | Yes | Yes |\n| `agents` | Yes | Yes |\n| `functions.invoke()` | Yes | Yes |\n| `integrations` | Yes | Yes |\n| `analytics` | Yes | Yes |\n| `appLogs` | Yes | Yes |\n| `users` | Yes | Yes |\n| `asServiceRole.*` | No | Yes |\n| `connectors` | No | Yes |\n\nBackend functions use `Deno.serve()` and `createClientFromRequest(req)` to get a properly authenticated client.\n"},"lastSynced":"2026-03-08T02:03:10.271Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare-focused Agents needing streamlined app development on the Base44 platform using React and Cloudflare Workers.","zh":"非常适合需要在Base44平台上使用React和Cloudflare Workers进行流线化应用开发的Cloudflare专注的代理。","ja":"Cloudflareに焦点を当てたエージェントがBase44プラットフォーム上でReactとCloudflare Workersを使用してアプリ開発をストリームライン化する必要がある場合に最適です。","ko":"Cloudflare에 중점을 둔 에이전트가 Base44 플랫폼에서 React와 Cloudflare Workers를 사용하여 애플리케이션 개발을 간소화해야 하는 경우에 적합합니다.","es":"Perfecto para agentes centrados en Cloudflare que necesitan un desarrollo de aplicaciones optimizado en la plataforma Base44 utilizando React y Cloudflare Workers.","fr":"Parfait pour les agents axés sur Cloudflare qui ont besoin d''un développement d''applications rationalisé sur la plate-forme Base44 en utilisant React et Cloudflare Workers.","de":"Perfekt für Cloudflare-fokussierte Agenten, die ein optimiertes App-Entwicklung auf der Base44-Plattform mit React und Cloudflare Workers benötigen.","pt":"Perfeito para Agentes focados em Cloudflare que necessitam de desenvolvimento de aplicativos simplificado na plataforma Base44 usando React e Cloudflare Workers.","ru":"Идеально подходит для агентов, ориентированных на Cloudflare, которым необходим упрощенный разработка приложений на платформе Base44 с использованием React и Cloudflare Workers.","ar":"مثالي للوكلاء المُركّزين على Cloudflare الذين يحتاجون إلى تطوير تطبيقات مبسط على منصة Base44 باستخدام React و Cloudflare Workers."},"recommendation":{"en":"Empowers agents to handle requests and implement features on the Base44 platform using the Base44 JavaScript SDK, leveraging React and Cloudflare Workers for robust app development, and handling configurations via `base44/config.jsonc` files.","zh":"赋予代理在Base44平台上处理请求和实现功能的能力，使用Base44 JavaScript SDK，利用React和Cloudflare Workers进行强大的应用开发，并通过`base44/config.jsonc`文件处理配置。","ja":"エージェントがBase44プラットフォーム上でリクエストを処理し、機能を実装する能力を与え、Base44 JavaScript SDKを使用し、ReactとCloudflare Workersを使用して堅牢なアプリ開発を行い、`base44/config.jsonc`ファイルを介して構成を処理します。","ko":"에이전트가 Base44 플랫폼에서 요청을 처리하고 기능을 구현할 수 있는 능력을 부여하며, Base44 JavaScript SDK를 사용하고, React와 Cloudflare Workers를 사용하여 강력한 애플리케이션 개발을 수행하며, `base44/config.jsonc` 파일을 통해 구성 설정을 처리합니다.","es":"Habilita a los agentes a manejar solicitudes e implementar características en la plataforma Base44 utilizando el SDK de JavaScript de Base44, aprovechando React y Cloudflare Workers para un desarrollo de aplicaciones robusto, y manejando configuraciones a través de archivos `base44/config.jsonc`.","fr":"Permet aux agents de gérer les requêtes et de mettre en œuvre des fonctionnalités sur la plate-forme Base44 en utilisant le SDK JavaScript de Base44, en exploitant React et Cloudflare Workers pour un développement d''applications robuste, et en gérant les configurations via des fichiers `base44/config.jsonc`.","de":"Ermächtigt Agenten, Anfragen zu bearbeiten und Funktionen auf der Base44-Plattform mit dem Base44 JavaScript SDK zu implementieren, React und Cloudflare Workers für robustes App-Entwicklung nutzt und Konfigurationen über `base44/config.jsonc`-Dateien handhabt.","pt":"Habilita os agentes a lidar com solicitações e implementar recursos na plataforma Base44 usando o SDK de JavaScript da Base44, aproveitando React e Cloudflare Workers para um desenvolvimento de aplicativos robusto, e lidar com configurações via arquivos `base44/config.jsonc`.","ru":"Наделяет агентов возможностью обрабатывать запросы и реализовывать функции на платформе Base44 с помощью SDK JavaScript Base44, используя React и Cloudflare Workers для прочной разработки приложений, а также обрабатывать конфигурации через файлы `base44/config.jsonc`.","ar":"تمكّن الوكلاء من التعامل مع الطلبات وتطبيق الميزات على منصة Base44 باستخدام SDK جافاسكريبت Base44، واستخدام React و Cloudflare Workers لتطوير تطبيقات قوي، وتعامل مع الإعدادات عبر ملفات `base44/config.jsonc`."},"useCases":{"en":["Building apps on the Base44 platform","Implementing features using the Base44 JavaScript SDK","Handling requests with Cloudflare Workers","Configuring projects via `base44/config.jsonc` files"],"zh":["在Base44平台上构建应用","使用Base44 JavaScript SDK实现功能","使用Cloudflare Workers处理请求","通过`base44/config.jsonc`文件配置项目"],"ja":["Base44プラットフォーム上でアプリを構築する","Base44 JavaScript SDKを使用して機能を実装する","Cloudflare Workersを使用してリクエストを処理する","`base44/config.jsonc`ファイルを介してプロジェクトを構成する"],"ko":["Base44 플랫폼에서 애플리케이션을 구축하는 것","Base44 JavaScript SDK를 사용하여 기능을 구현하는 것","Cloudflare Workers를 사용하여 요청을 처리하는 것","`base44/config.jsonc` 파일을 통해 프로젝트를 구성하는 것"],"es":["Construir aplicaciones en la plataforma Base44","Implementar características utilizando el SDK de JavaScript de Base44","Manejar solicitudes con Cloudflare Workers","Configurar proyectos a través de archivos `base44/config.jsonc`"],"fr":["Construire des applications sur la plate-forme Base44","Mettre en œuvre des fonctionnalités en utilisant le SDK JavaScript de Base44","Gérer les requêtes avec Cloudflare Workers","Configurer des projets via des fichiers `base44/config.jsonc`"],"de":["Apps auf der Base44-Plattform erstellen","Funktionen mit dem Base44 JavaScript SDK implementieren","Anfragen mit Cloudflare Workers bearbeiten","Projekte über `base44/config.jsonc`-Dateien konfigurieren"],"pt":["Construir aplicativos na plataforma Base44","Implementar recursos usando o SDK de JavaScript da Base44","Lidar com solicitações com Cloudflare Workers","Configurar projetos via arquivos `base44/config.jsonc`"],"ru":["Построение приложений на платформе Base44","Реализация функций с помощью SDK JavaScript Base44","Обработка запросов с помощью Cloudflare Workers","Настройка проектов через файлы `base44/config.jsonc`"],"ar":["بناء التطبيقات على منصة Base44","تطبيق الميزات باستخدام SDK جافاسكريبت Base44","التعامل مع الطلبات باستخدام Cloudflare Workers","تكوين المشاريع عبر ملفات `base44/config.jsonc`"]},"limitations":{"en":["Requires `base44/config.jsonc` file for existing project scenarios","Activated by mentions of ''base44'' or `base44/` folder existence","Dependent on React and Cloudflare Workers for development"],"zh":["需要`base44/config.jsonc`文件来处理现有项目场景","通过提及''base44''或`base44/`文件夹存在来激活","依赖于React和Cloudflare Workers进行开发"],"ja":["既存のプロジェクトシナリオを処理するために`base44/config.jsonc`ファイルが必要","''base44''または`base44/`フォルダの存在を提及してアクティブ化","開発のためにReactとCloudflare Workersに依存"],"ko":["기존 프로젝트 시나리오를 처리하기 위해 `base44/config.jsonc` 파일이 필요","''base44'' 또는 `base44/` 폴더 존재를 언급하여 활성화","개발을 위해 React와 Cloudflare Workers에 의존"],"es":["Requiere un archivo `base44/config.jsonc` para escenarios de proyectos existentes","Activado por menciones de ''base44'' o la existencia de la carpeta `base44/`","Dependiente de React y Cloudflare Workers para el desarrollo"],"fr":["Nécessite un fichier `base44/config.jsonc` pour les scénarios de projets existants","Activé par des mentions de ''base44'' ou l''existence du dossier `base44/`","Dépendant de React et Cloudflare Workers pour le développement"],"de":["Benötigt eine `base44/config.jsonc`-Datei für Szenarien bestehender Projekte","Aktiviert durch Erwähnungen von ''base44'' oder das Vorhandensein des Ordners `base44/`","Von React und Cloudflare Workers für die Entwicklung abhängig"],"pt":["Requer arquivo `base44/config.jsonc` para cenários de projetos existentes","Ativado por menções de ''base44'' ou existência da pasta `base44/`","Dependente de React e Cloudflare Workers para desenvolvimento"],"ru":["Требует файла `base44/config.jsonc` для существующих сценариев проектов","Активируется при упоминании ''base44'' или наличии папки `base44/`","Зависит от React и Cloudflare Workers для разработки"],"ar":["يتطلب ملف `base44/config.jsonc` لسيناريوهات المشاريع الحالية","مفعّل بواسطة ذكر ''base44'' أو وجود مجلد `base44/`","يعتمد على React و Cloudflare Workers للتطوير"]},"version":4},"contentHash":"981c78c1075d71e505280d3ab8584b7e65314004408e701800698e28eecb1a6b","qualityScore":54}');
