INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('offloadmywork/pokemon-app/base44-sdk', 'base44-sdk', 'offloadmywork', 'pokemon-app', 'community', 'base44-sdk offloadmywork pokemon-app community The base44-sdk skill enables developers to build apps on the Base44 platform using React and Cloudflare Workers, handling requests and implementing features Base44 SDK 是一个使用 React 和 Cloudflare Workers 构建 Pokémon 游戏的工具，提供了一种快速简单的开发方式 Base44 SDK は、React と Cloudflare Workers を使用して Pokémon ゲームを構築するツールで、迅速な開発方法を提供します Base44 SDK는 React와 Cloudflare Workers를 사용하여 Pokémon 게임을 구축하는 도구로 빠르고 간단한 개발 방법을 제공합니다 Base44-sdk es un kit de desarrollo para construir aplicaciones en la plataforma Base44 con React y Cloudflare Workers. Permite implementar características y gestionar proyectos de manera eficiente Base44-sdk est un kit de développement pour créer des applications sur la plateforme Base44 avec React et Cloudflare Workers. Il permet de mettre en œuvre des fonctionnalités et de gérer des projets de manière efficace Base44-sdk ist ein Entwicklungskit für den Bau von Anwendungen auf der Base44-Plattform mit React und Cloudflare Workers. Es ermöglicht die Implementierung von Funktionen und die effiziente Verwaltung von Projekten O base44-sdk é uma plataforma para construir aplicações com React e Cloudflare Workers. Aprenda a configurar e usar a plataforma para desenvolver aplicações personalizadas. Base44-sdk - это платформа для разработки приложений с использованием React и Cloudflare Workers. Узнайте, как настроить и использовать платформу для создания индивидуальных приложений. base44-sdk هي منصة لبناء التطبيقات مع React و Cloudflare Workers. تعلم كيفية إعداد واستخدام المنصة لإنشاء تطبيقات مخصصة. how to use base44-sdk what is base44-sdk base44-sdk alternative base44-sdk vs react-sdk base44-sdk install base44-sdk setup guide cloudflare workers tutorial react and cloudflare workers integration Base44 SDK React Cloudflare Workers Pokémon 游戏 JavaScript SDK AI エージェント AI 工具 游戏开发 云计算 Checks for existing base44/config.jsonc files in the current directory Handles requests when a base44/ folder exists Implements features based on the Base44 platform Uses React for building app interfaces Leverages Cloudflare Workers for serverless functionality Activates on mentions of ''base44'' for immediate action base44-sdk is a JavaScript SDK for building apps on the Base44 platform, utilizing React and Cloudflare Workers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DishaAnand/FocusNest/mobile-app-testing', 'community', 'DishaAnand', 'FocusNest', 'DishaAnand/FocusNest', 'mobile-app-testing', 0, 0, 54, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:12.460Z', '656add9094129451d3606c2712db0a052093d74d43053bb4450ba277a39118f7', '{"id":"DishaAnand/FocusNest/mobile-app-testing","name":"mobile-app-testing","description":{"en":"Mobile-app-testing enables developers to implement comprehensive testing strategies for mobile applications, including unit tests, UI tests, and performance testing. This skill benefits mobile app developers and testers.","zh":"移动应用测试是确保应用程序可靠性和性能的关键步骤，包括单元测试、UI 测试、集成测试和性能测试","ja":"モバイルアプリテストは、信頼性とパフォーマンスを確保するために不可欠です - ユニットテスト、UI テスト、統合テスト、パフォーマンステスト","ko":"모바일 앱 테스팅은 애플리케이션의 신뢰성과 성능을 보장하는 중요한 단계입니다 - 단위 테스트, UI 테스트, 통합 테스트, 성능 테스트","es":"Implementa pruebas de aplicaciones móviles con React Native, Jest y Detox. Mejora la confiabilidad y el rendimiento de tus aplicaciones móviles","fr":"Mettez en place des tests d''applications mobiles avec React Native, Jest et Detox. Améliorez la fiabilité et les performances de vos applications mobiles","de":"Implementieren Sie mobile App-Tests mit React Native, Jest und Detox. Verbessern Sie die Zuverlässigkeit und Leistung Ihrer mobilen Anwendungen","pt":"Implemente estratégias de teste abrangentes para aplicativos móveis com React Native e Jest & Detox","ru":"Реализуйте комплексные стратегии тестирования мобильных приложений с помощью React Native и ИИ Агентов","ar":"نفذ استراتيجيات اختبار شاملة للتطبيقات المحمولة مع React Native وادوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Mobile-App-Testing: Comprehensive Setup Guide | AI Agent ...","zh":"移动应用测试设置指南","ja":"モバイルアプリテストベストプラクティス - AIエージェント","ko":"모바일 앱 테스팅 가이드 - React Native 및 Detox","es":"Guía de configuración para pruebas de aplicaciones móvile...","fr":"Guid