INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bdarcus/style-hub/enhance-prompt', 'enhance-prompt', 'bdarcus', 'style-hub', 'community', 'enhance-prompt bdarcus style-hub community Enhance-prompt is a web-based hub for optimizing prompts for Stitch, helping prompt engineers create better results. It''s designed in lockstep with the CSL Next ecosystem. 增强提示是一个用于优化Stitch生成的UI的工具，通过修改和创建提示来提高结果质量 プロンプト強化は、StitchのUI生成を最適化するためのツールで、プロンプトの修正と生成により結果の品質を向上させる 프롬프트 강화는 Stitch의 UI 생성을 최적화하기 위한 툴로, 프롬프트의 수정 및 생성을 통해 결과의 품질을 향상 Enhance-prompt es una herramienta para mejorar los prompts de Stitch. Ayuda a los desarrolladores a crear promtps de UI más eficaces Enhance-prompt est un outil pour améliorer les prompts de Stitch. Il aide les développeurs à créer des prompts de UI plus efficaces Enhance-prompt ist ein Tool zur Verbesserung der Prompts von Stitch. Es hilft Entwicklern, effektivere UI-Prompts zu erstellen O Enhance-Prompt é uma ferramenta de desenvolvimento que ajuda a criar prompts otimizados para Stitch, melhorando a geração de UI Enhance-Prompt - это инструмент разработки, помогающий создавать оптимизированные промпты для Stitch, улучшающие генерацию UI для ИИ Агентов Enhance-Prompt هو أداة تطوير تساعد على tạo برومتات محسّنة لبرنامج Stitch، مما يحسن توليد واجهة المستخدم how to use enhance-prompt what is enhance-prompt enhance-prompt setup guide enhance-prompt vs Stitch enhance-prompt install Stitch prompt engineering CSL Next ecosystem optimized prompt generation 增强提示 AIエージェント工具 Stitch有效提示指南 CSL Next生态系统 提示修改 UI生成优化 结果质量提高 开发者友好接口 AI开发工具 Consults the official Stitch documentation for the latest best practices Utilizes the Stitch Effective Prompting Guide for up-to-date recommendations Transforms rough or vague UI generation ideas into polished prompts Produces better results from Stitch through optimized prompt engineering Developed in lockstep with the CSL Next ecosystem Enhance-prompt is a skill for transforming rough or vague UI generation ideas into polished, optimized prompts for Stitch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pythoninthegrasses/mt/discover-zig', 'community', 'pythoninthegrasses', 'mt', 'pythoninthegrasses/mt', 'discover-zig', 0, 0, 54, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.550Z', 'a8eee673a13f10abfda7b0325808ae7698044404b2abe685ca8c716f51d5bc7c', '{"id":"pythoninthegrasses/mt/discover-zig","name":"discover-zig","description":{"en":"The discover-zig skill provides automatic access to comprehensive Zig skills, benefiting systems programmers working with Zig, comptime, allocators, and C interop. It auto-activates when working with build.zig or the zon package manager.","zh":"Discover-Zig 技术提供了自动访问 Zig 语言的综合技能，包括系统编程、comptime、分配器、C 互操作等","ja":"Discover-Zig 技術は、Zig 言語の包括的なスキルに自動的にアクセスします。システムプログラミング、comptime、割り当て、C 相互運用などが含まれます","ko":"Discover-Zig 기술은 Zig 언어의 종합적인 기술에 자동으로 액세스합니다. 시스템 프로그래밍, comptime, 할당자, C 상호 운용 등이 포함됩니다","es":"Discover-zig proporciona acceso automático a habilidades de programación de sistemas Zig, incluyendo zig-build-system y zig-c-interop","fr":"Discover-zig fournit un accès automatique aux compétences de programmation système Zig, notamment zig-build-system et zig-c-interop","de":"Discover-zig bietet automatischen Zugriff auf Zig-Systemprogrammierfähigkeiten, einschließlich zig-build-system und zig-c-interop","pt":"O discover-zig fornece acesso automático a habilidades abrangentes de Zig para desenvolvedores","ru":"Discover-zig предоставляет автоматический доступ к всесторонним навыкам Zig для разработчиков ИИ Агентов","ar":"يوفّر discover-zig وصولًا تلقائيًا إلى مهارات شاملة لمنصة Zig للعاملين الذكية"},"seo":{"title":{"en":"discover-zig: Zig Skills Discovery Setup Guide | AI Agent...","zh":"Discover-Zig 设置指南：自动访问 Zig 技术","ja":"Discover-Zig 導入ガイド：Zig スキルの自動発見","ko":"Discover-Zig 설정 가이드: 자동 Zig 기술 탐색","es":"Guía de configuración de discover-zig para programación d...","fr":"Configur