INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Wolverine971/9takes/add-config-field', 'add-config-field', 'Wolverine971', '9takes', 'community', 'add-config-field Wolverine971 9takes community The add-config-field skill allows developers to add new fields to the .agents.yml config schema, supporting versioning and migration. It benefits AI agent developers working with YAML templates. add-config-field技能用于向.agents.yml配置schema添加新字段，支持版本控制和迁移 add-config-fieldスキルは、.agents.ymlの設定スキーマに新しいフィールドを追加し、バージョン管理と移行をサポートします add-config-field 스킬은 .agents.yml 구성 스키마에 새로운 필드를 추가하며 버전 관리와 마이그레이션을 지원합니다 Add-config-field es una habilidad que permite agregar un nuevo campo a la configuración de agente de IA con soporte de versionado y migración. Se utiliza para actualizar la configuración de .agents.yml. Add-config-field est une compétence qui permet d''ajouter un nouveau champ à la configuration d''agent d''IA avec prise en charge de la version et de la migration. Elle est utilisée pour mettre à jour la configuration de .agents.yml. Add-config-field ist eine Fähigkeit, die es ermöglicht, ein neues Feld zur Konfiguration von KI-Agents mit Versionierungs- und Migrationsunterstützung hinzuzufügen. Sie wird verwendet, um die Konfiguration von .agents.yml zu aktualisieren. O add-config-field é uma habilidade que adiciona um novo campo ao esquema de configuração .agents.yml com suporte a versionamento e migração Add-config-field — это навык, который добавляет новое поле в схему конфигурации .agents.yml с поддержкой версионирования и миграции для ИИ Агентов إضافة حقل تكوين هو مهارة تضيف حقلًا جديدًا إلى مخطط تكوين .agents.yml مع دعم الإصدار والهجرة للوكلاء الذكية how to use add-config-field add-config-field setup guide add-config-field vs majestic-engineer add-config-field install what is add-config-field add-config-field alternative YAML config schema setup AI agent config field management add-config-field migration support AI工具 配置schema add-config-field 版本控制 迁移支持 plugins/majestic-engineer YAML模板 AIエージェント开发 Generates .agents.yml files using 4 YAML templates Supports versioning through the config-schema-version plugin Modifies the plugins/majestic-engineer/commands/workflows/init.md file Enables migration support for added config fields Updates the .agents.yml config schema with new field additions add-config-field is a skill that enables the addition of new fields to the .agents.yml config schema with proper versioning and migration support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('liauw-media/CodeAssist/gcp-architecture', 'community', 'liauw-media', 'CodeAssist', 'liauw-media/CodeAssist', 'gcp-architecture', 0, 0, 54, '2026-03-08T01:57:15.343Z', '2026-03-08T02:03:30.493Z', '837cef6e2d84dba312033d4c194ad1cac058035557ea9fcbb02c28d8274db79d', '{"id":"liauw-media/CodeAssist/gcp-architecture","name":"gcp-architecture","description":{"en":"The gcp-architecture skill provides a comprehensive guide for building secure, scalable infrastructure on Google Cloud Platform, benefiting developers and architects. It covers designing GCP architecture, deploying applications, and configuring IAM policies.","zh":"Google Cloud Platform架构综合指南，用于构建安全、可扩展的基础设施","ja":"Google Cloud Platformアーキテクチャの包括的なガイド。セキュアでスケーラブルなインフラストラクチャを構築する","ko":"Google Cloud Platform 아키텍처에 대한 포괄적인 가이드. 보안 및 확장 가능한 인프라 구축","es":"La arquitectura de GCP es fundamental para el éxito de tus proyectos. Aprende a diseñar y implementar infraestructuras seguras y escalables.","fr":"L''architecture GCP est essentielle pour le succès de vos projets. Apprenez à concevoir et à mettre en œuvre des infrastructures sécurisées et évolutives.","de":"Die GCP-Architektur ist entscheidend für den Erfolg Ihrer Projekte. Erfahren Sie, wie Sie sichere und skalierbare Infrastrukturen entwerfen und implementieren können.","pt":"Arquitetura GCP é um guia abrangente para construir infraestruturas seguras e escaláveis na plataforma de nuvem da Google.","ru":"ИИ Агенты для инфраструктуры Google Cloud Platform предоставляют комплексное руководство по созданию безопасных и масштабируемых приложений.","ar":"الهندسة المعمارية لجوجل سحابية هي دليل شامل لإنشاء بنى تحتية آمنة ومتطورة على منصة جوجل سحابية"},"seo":{"title":{"en":"gcp-architecture: Comprehensive Setup Guide | AI Agent Skill","zh":"GCP架构设置指南 - AIエージェント工具","ja":"GCPアーキテクチャ設定ガイド - AIエージェント","ko":"GCP 아키텍처 설정 가이드 - AI 에이전트","es":"Guía de Arquitectura de GCP: Mejores Prácticas para Desar...","fr":"Guide d''Architecture GCP: Mises en Œuvre pour les Dévelop...","de":"GCP-Architektur-Leitfaden: Best Practices für Entwickler","pt":"Guia de Configuração de Arquitetura GCP","ru":"ИИ Агенты для Настройки Инфраструктуры Google Cloud Platform","ar":"دليل إعداد هندسة البنية التحتية لأجهزة الحوسبة السحابية م..."},"description":{"en":"Discover how to design secure and scalable infrastructure on Google Cloud Platform with our gcp-architecture skill - get started now and optimize your deploy...","zh":"了解GCP架构的设置和优化，包括VPC、IAM、GKE和成本优化","ja":"GCPアーキテクチャの設定と最適化について学びます。VPC、IAM、GKE、コスト最適化など","ko":"GCP 아키텍처 설정과 최적화를 배우세요. VPC, IAM, GKE, 비용 최적화 등","es":"Aprende a diseñar y implementar arquitecturas de GCP seguras y escalables con nuestros expertos en desarrollo. Descubre las mejores prácticas para GKE, IAM y...","fr":"Découvrez comment concevoir et mettre en œuvre des architectures GCP sécurisées et évolutives avec nos experts en développement. Apprenez les meilleures prat...","de":"Erfahren Sie, wie Sie sichere und skalierbare GCP-Architekturen entwerfen und implementieren können. Entdecken Sie die besten Praktiken für GKE, IAM und mehr.","pt":"Aprenda a projetar e implantar aplicações seguras e escaláveis na plataforma de nuvem da Google com nossa guia de arquitetura GCP","ru":"Используйте ИИ Агенты для создания безопасной и масштабируемой инфраструктуры на платформе Google Cloud","ar":"تعلم كيفية تصميم وتطبيق تطبيقات آمنة ومتناسقة على منصة جوجل سحابية باستخدام دليلنا للهندسة المعمارية لجوجل"},"definition":{"en":"gcp-architecture is a comprehensive guide for building secure, scalable infrastructure on Google Cloud Platform, covering core services like Compute, networking, and IAM policies.","zh":"GCP架构是指在Google Cloud Platform上构建和设置安全、可扩展的基础设施","ja":"GCPアーキテクチャとは、Google Cloud Platform上でセキュアでスケーラブルなインフラストラクチャを構築すること","ko":"GCP 아키텍처는 Google Cloud Platform에서 보안 및 확장 가능한 인프라를 구축하고 설정하는 것을 말함","es":"La arquitectura de GCP se refiere al diseño y la implementación de infraestructuras de Google Cloud Platform para aplicaciones y servicios.","fr":"L''architecture GCP fait référence à la conception et à la mise en œuvre d''infrastructures de Google Cloud Platform pour les applications et les services.","de":"Die GCP-Architektur bezieht sich auf das Design und die Implementierung von Google Cloud Platform-Infrastrukturen für Anwendungen und Dienste.","pt":"Arquitetura GCP é um conjunto de diretrizes para projetar e implantar aplicações na plataforma de nuvem da Google","ru":"ИИ Агенты для инфраструктуры Google Cloud Platform - это набор правил для создания приложений на платформе Google Cloud","ar":"الهندسة المعمارية لجوجل سحابية هي مجموعة من الإرشادات لتصميم وتطبيق التطبيقات على منصة جوجل سحابية"},"features":{"en":["Designs GCP architecture for new projects","Deploys applications to GCP services like Google Kubernetes Engine (GKE)","Configures IAM policies and service accounts","Sets up networking with VPC and firewall rules","Optimizes costs and performance on Google Cloud Platform"],"zh":["设计和设置VPC和防火墙规则","配置IAM策略和服务账户","部署应用到GCP服务","使用GKE（Google Kubernetes Engine）","优化成本和性能"],"ja":["VPCとファイアウォールルールの設計と設定","IAMポリシーとサービスアカウントの構成","アプリケーションのGCPサービスへのデプロイ","GKE（Google Kubernetes Engine）の使用","コストとパフォーマンスの最適化"],"ko":["VPC 및 방화벽 규칙 설계 및 설정","IAM 정책 및 서비스 계정 구성","애플리케이션을 GCP 서비스에 배포","GKE（Google Kubernetes Engine） 사용","비용 및 성능 최적화"],"es":["Diseño de arquitecturas de GCP para nuevos proyectos","Implementación de aplicaciones en servicios de GCP","Configuración de redes (VPC, reglas de firewall)","Configuración de políticas de IAM y cuentas de servicio","Trabajo con GKE (Google Kubernetes Engine)","Optimización de costos y rendimiento"],"fr":["Conception d''architectures GCP pour les nouveaux projets","Mise en œuvre d''applications sur les services GCP","Configuration des réseaux (VPC, règles de pare-feu)","Configuration des stratégies IAM et des comptes de service","Travail avec GKE (Google Kubernetes Engine)","Optimisation des coûts et des performances"],"de":["Entwurf von GCP-Architekturen für neue Projekte","Implementierung von Anwendungen in GCP-Diensten","Konfiguration von Netzwerken (VPC, Firewall-Regeln)","Konfiguration von IAM-Richtlinien und Dienstkonto","Arbeit mit GKE (Google Kubernetes Engine)","Optimierung von Kosten und Leistung"],"pt":["Design de arquitetura GCP para novos projetos","Implantação de aplicações em serviços GCP","Configuração de redes (VPC, regras de firewall)","Configuração de políticas IAM e contas de serviço","Trabalho com GKE (Google Kubernetes Engine)","Otimização de custos e desempenho"],"ru":["Проектирование инфраструктуры GCP для новых проектов","Развертывание приложений на сервисах GCP","Настройка сетей (VPC, правила брандмауэра)","Настройка политик IAM и учетных записей сервиса","Работа с GKE (Google Kubernetes Engine)","Оптимизация затрат и производительности"],"ar":["تصميم هندسة البنية التحتية لأجهزة الحوسبة السحابية من جوجل للمشاريع الجديدة","تطبيق التطبيقات على خدمات جوجل سحابية","ضبط الشبكات (VPC و قواعد الحماية من الحرائق)","ضبط سياسات IAM و حسابات الخدمة","العمل مع GKE (محرك كوبرنيتس من جوجل)","تحسين التكاليف والأداء"]},"keywords":{"en":["how to use gcp-architecture","gcp-architecture setup guide","gcp-architecture vs aws architecture","what is gcp-architecture","gcp-architecture install","gcp-architecture best practices","google cloud platform architecture","gcp-architecture tutorial","gcp-architecture example"],"zh":["GCP架构","Google Cloud Platform","VPC","IAM","GKE","成本优化","性能优化","AIエージェント工具","云计算"],"ja":["GCPアーキテクチャ","Google Cloud Platform","VPC","IAM","GKE","コスト最適化","パフォーマンス最適化","AIエージェント","クラウドコンピューティング"],"ko":["GCP 아키텍처","Google Cloud Platform","VPC","IAM","GKE","비용 최적화","성능 최적화","AI 에이전트","클라우드 컴퓨팅"],"es":["arquitectura de GCP","desarrollo de aplicaciones en GCP","GKE","IAM","VPC","reglas de firewall","optimización de costos","mejores prácticas de GCP"],"fr":["architecture GCP","développement d''applications sur GCP","GKE","IAM","VPC","règles de pare-feu","optimisation des coûts","meilleures pratiques GCP"],"de":["GCP-Architektur","Anwendungsentwicklung in GCP","GKE","IAM","VPC","Firewall-Regeln","Kostenoptimierung","Best Practices für GCP"],"pt":["arquitetura GCP","infraestrutura de nuvem","segurança na nuvem","escalabilidade na nuvem","GKE","IAM","VPC","firewall","otimização de custos"],"ru":["инфраструктура GCP","облачные вычисления","безопасность в облаке","масштабируемость в облаке","GKE","IAM","VPC","брандмауэр","оптимизация затрат"],"ar":["هندسة البنية التحتية لأجهزة الحوسبة السحابية من جوجل","الحوسبة السحابية","الأمان في السحابة","التناسق في السحابة","GKE","IAM","VPC","حماية الحرائق","تحسين التكاليف"]}},"owner":"liauw-media","repo":"CodeAssist","repoPath":"liauw-media/CodeAssist","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.343Z","topics":[],"category":"community","skillMd":{"name":"gcp-architecture","description":"Google Cloud Platform architecture patterns and best practices. Use when designing, deploying, or reviewing GCP infrastructure including GKE, Cloud Run, Cloud Functions, BigQuery, and IAM.","bodyPreview":"# Google Cloud Platform Architecture\n\nComprehensive guide for building secure, scalable infrastructure on Google Cloud Platform.\n\n## When to Use\n\n- Designing GCP architecture for new projects\n- Deploying applications to GCP services\n- Setting up networking (VPC, firewall rules)\n- Configuring IAM policies and service accounts\n- Working with GKE (Google Kubernetes Engine)\n- Optimizing costs and performance\n\n## Core Services Overview\n\n### Compute\n\n| Service | Use Case | Key Features |\n|---------|--","body":"# Google Cloud Platform Architecture\n\nComprehensive guide for building secure, scalable infrastructure on Google Cloud Platform.\n\n## When to Use\n\n- Designing GCP architecture for new projects\n- Deploying applications to GCP services\n- Setting up networking (VPC, firewall rules)\n- Configuring IAM policies and service accounts\n- Working with GKE (Google Kubernetes Engine)\n- Optimizing costs and performance\n\n## Core Services Overview\n\n### Compute\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| Compute Engine | Virtual machines | Full control, custom images |\n| GKE | Managed Kubernetes | Autopilot mode, node auto-provisioning |\n| Cloud Run | Serverless containers | Scale to zero, any container |\n| Cloud Functions | Serverless functions | Event-driven, 2nd gen |\n| App Engine | PaaS | Standard/Flexible environments |\n\n### Storage\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| Cloud Storage | Object storage | Multi-regional, lifecycle |\n| Persistent Disk | Block storage (GCE) | SSD/HDD, snapshots |\n| Filestore | Managed NFS | High performance |\n| Cloud SQL | Managed SQL | MySQL, PostgreSQL, SQL Server |\n| Firestore | NoSQL document | Serverless, realtime |\n| BigQuery | Data warehouse | Serverless, petabyte-scale |\n| Cloud Spanner | Global SQL | Horizontal scaling |\n| Memorystore | Managed Redis | In-memory cache |\n\n### Networking\n\n| Service | Use Case | Key Features |\n|---------|----------|--------------|\n| VPC | Virtual network | Global, shared VPC |\n| Cloud Load Balancing | Global LB | Layer 4/7, anycast IPs |\n| Cloud CDN | Content delivery | Edge caching |\n| Cloud DNS | DNS management | 100% SLA |\n| Cloud NAT | Outbound NAT | No external IPs needed |\n\n## VPC Architecture\n\n### Shared VPC Pattern\n\n```\n┌──────────────────────────────────────────────────────────────────┐\n│ Host Project (Shared VPC)                                        │\n│                                                                  │\n│  ┌────────────────────────────────────────────────────────────┐  │\n│  │ VPC Network: shared-vpc                                    │  │\n│  │                                                            │  │\n│  │  ┌─────────────────────┐    ┌─────────────────────┐       │  │\n│  │  │ Subnet: prod-app    │    │ Subnet: prod-data   │       │  │\n│  │  │ 10.0.0.0/20         │    │ 10.0.16.0/20        │       │  │\n│  │  │ us-central1         │    │ us-central1         │       │  │\n│  │  └─────────────────────┘    └─────────────────────┘       │  │\n│  │                                                            │  │\n│  │  ┌─────────────────────┐    ┌─────────────────────┐       │  │\n│  │  │ Subnet: staging-app │    │ Subnet: staging-data│       │  │\n│  │  │ 10.1.0.0/20         │    │ 10.1.16.0/20        │       │  │\n│  │  │ us-central1         │    │ us-central1         │       │  │\n│  │  └─────────────────────┘    └─────────────────────┘       │  │\n│  └────────────────────────────────────────────────────────────┘  │\n└──────────────────────────────────────────────────────────────────┘\n         │                              │\n         ▼                              ▼\n┌─────────────────────┐      ┌─────────────────────┐\n│ Service Project A   │      │ Service Project B   │\n│ (Production)        │      │ (Staging)           │\n│                     │      │                     │\n│ GKE, Cloud Run      │      │ GKE, Cloud Run      │\n│ Cloud SQL           │      │ Cloud SQL           │\n└─────────────────────┘      └─────────────────────┘\n```\n\n### Terraform VPC\n\n```hcl\n# VPC Network\nresource \"google_compute_network\" \"main\" {\n  name                    = \"${var.project_id}-vpc\"\n  auto_create_subnetworks = false\n  routing_mode            = \"GLOBAL\"\n}\n\n# Subnets\nresource \"google_compute_subnetwork\" \"app\" {\n  name          = \"${var.project_id}-app-subnet\"\n  ip_cidr_range = \"10.0.0.0/20\"\n  region        = var.region\n  network       = google_compute_network.main.id\n\n  secondary_ip_range {\n    range_name    = \"pods\"\n    ip_cidr_range = \"10.100.0.0/16\"\n  }\n\n  secondary_ip_range {\n    range_name    = \"services\"\n    ip_cidr_range = \"10.200.0.0/20\"\n  }\n\n  private_ip_google_access = true\n\n  log_config {\n    aggregation_interval = \"INTERVAL_5_SEC\"\n    flow_sampling        = 0.5\n    metadata             = \"INCLUDE_ALL_METADATA\"\n  }\n}\n\n# Cloud NAT\nresource \"google_compute_router\" \"main\" {\n  name    = \"${var.project_id}-router\"\n  region  = var.region\n  network = google_compute_network.main.id\n}\n\nresource \"google_compute_router_nat\" \"main\" {\n  name                               = \"${var.project_id}-nat\"\n  router                             = google_compute_router.main.name\n  region                             = var.region\n  nat_ip_allocate_option             = \"AUTO_ONLY\"\n  source_subnetwork_ip_ranges_to_nat = \"ALL_SUBNETWORKS_ALL_IP_RANGES\"\n\n  log_config {\n    enable = true\n    filter = \"ERRORS_ONLY\"\n  }\n}\n\n# Firewall Rules\nresource \"google_compute_firewall\" \"allow_internal\" {\n  name    = \"${var.project_id}-allow-internal\"\n  network = google_compute_network.main.name\n\n  allow {\n    protocol = \"tcp\"\n  }\n  allow {\n    protocol = \"udp\"\n  }\n  allow {\n    protocol = \"icmp\"\n  }\n\n  source_ranges = [\"10.0.0.0/8\"]\n}\n\nresource \"google_compute_firewall\" \"allow_health_checks\" {\n  name    = \"${var.project_id}-allow-health-checks\"\n  network = google_compute_network.main.name\n\n  allow {\n    protocol = \"tcp\"\n  }\n\n  source_ranges = [\n    \"35.191.0.0/16\",   # GCP Health Checks\n    \"130.211.0.0/22\",  # GCP Health Checks\n  ]\n\n  target_tags = [\"allow-health-checks\"]\n}\n```\n\n## IAM & Service Accounts\n\n### Service Account Best Practices\n\n```hcl\n# Application Service Account\nresource \"google_service_account\" \"app\" {\n  account_id   = \"${var.project_id}-app-sa\"\n  display_name = \"Application Service Account\"\n}\n\n# Workload Identity for GKE\nresource \"google_service_account_iam_binding\" \"workload_identity\" {\n  service_account_id = google_service_account.app.name\n  role               = \"roles/iam.workloadIdentityUser\"\n  members = [\n    \"serviceAccount:${var.project_id}.svc.id.goog[${var.namespace}/${var.k8s_service_account}]\"\n  ]\n}\n\n# Grant specific permissions\nresource \"google_project_iam_member\" \"app_storage\" {\n  project = var.project_id\n  role    = \"roles/storage.objectUser\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n\n  condition {\n    title      = \"Only app bucket\"\n    expression = \"resource.name.startsWith(''projects/_/buckets/${var.project_id}-app-data'')\"\n  }\n}\n\nresource \"google_project_iam_member\" \"app_secretmanager\" {\n  project = var.project_id\n  role    = \"roles/secretmanager.secretAccessor\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n}\n\nresource \"google_project_iam_member\" \"app_cloudsql\" {\n  project = var.project_id\n  role    = \"roles/cloudsql.client\"\n  member  = \"serviceAccount:${google_service_account.app.email}\"\n}\n```\n\n### Custom IAM Role\n\n```hcl\nresource \"google_project_iam_custom_role\" \"app_deployer\" {\n  role_id     = \"appDeployer\"\n  title       = \"Application Deployer\"\n  description = \"Can deploy applications to Cloud Run and GKE\"\n\n  permissions = [\n    \"run.services.create\",\n    \"run.services.update\",\n    \"run.services.delete\",\n    \"run.services.get\",\n    \"container.deployments.create\",\n    \"container.deployments.update\",\n    \"container.services.create\",\n    \"container.services.update\",\n  ]\n}\n```\n\n## GKE (Google Kubernetes Engine)\n\n### GKE Autopilot Cluster\n\n```hcl\nresource \"google_container_cluster\" \"main\" {\n  name     = \"${var.project_id}-gke\"\n  location = var.region\n\n  # Autopilot mode\n  enable_autopilot = true\n\n  network    = google_compute_network.main.name\n  subnetwork = google_compute_subnetwork.app.name\n\n  ip_allocation_policy {\n    cluster_secondary_range_name  = \"pods\"\n    services_secondary_range_name = \"services\"\n  }\n\n  private_cluster_config {\n    enable_private_nodes    = true\n    enable_private_endpoint = false\n    master_ipv4_cidr_block  = \"172.16.0.0/28\"\n  }\n\n  master_authorized_networks_config {\n    cidr_blocks {\n      cidr_block   = var.authorized_network\n      display_name = \"Authorized Network\"\n    }\n  }\n\n  release_channel {\n    channel = \"REGULAR\"\n  }\n\n  workload_identity_config {\n    workload_pool = \"${var.project_id}.svc.id.goog\"\n  }\n\n  # Security\n  binary_authorization {\n    evaluation_mode = \"PROJECT_SINGLETON_POLICY_ENFORCE\"\n  }\n\n  deletion_protection = var.environment == \"prod\"\n}\n```\n\n### GKE Standard Cluster\n\n```hcl\nresource \"google_container_cluster\" \"standard\" {\n  name     = \"${var.project_id}-gke-standard\"\n  location = var.region\n\n  # Remove default node pool\n  remove_default_node_pool = true\n  initial_node_count       = 1\n\n  network    = google_compute_network.main.name\n  subnetwork = google_compute_subnetwork.app.name\n\n  ip_allocation_policy {\n    cluster_secondary_range_name  = \"pods\"\n    services_secondary_range_name = \"services\"\n  }\n\n  workload_identity_config {\n    workload_pool = \"${var.project_id}.svc.id.goog\"\n  }\n\n  addons_config {\n    http_load_balancing {\n      disabled = false\n    }\n    horizontal_pod_autoscaling {\n      disabled = false\n    }\n    gce_persistent_disk_csi_driver_config {\n      enabled = true\n    }\n  }\n}\n\nresource \"google_container_node_pool\" \"primary\" {\n  name       = \"primary-pool\"\n  cluster    = google_container_cluster.standard.name\n  location   = var.region\n\n  node_count = var.environment == \"prod\" ? 3 : 1\n\n  autoscaling {\n    min_node_count = var.environment == \"prod\" ? 3 : 1\n    max_node_count = 10\n  }\n\n  management {\n    auto_repair  = true\n    auto_upgrade = true\n  }\n\n  node_config {\n    machine_type = \"e2-standard-4\"\n    disk_size_gb = 100\n    disk_type    = \"pd-ssd\"\n\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/cloud-platform\"\n    ]\n\n    service_account = google_service_account.gke_nodes.email\n\n    workload_metadata_config {\n      mode = \"GKE_METADATA\"\n    }\n\n    shielded_instance_config {\n      enable_secure_boot          = true\n      enable_integrity_monitoring = true\n    }\n\n    labels = {\n      environment = var.environment\n    }\n\n    tags = [\"gke-node\", var.environment]\n  }\n}\n```\n\n## Cloud Run\n\n### Cloud Run Service\n\n```hcl\nresource \"google_cloud_run_v2_service\" \"app\" {\n  name     = \"${var.project_id}-app\"\n  location = var.region\n  ingress  = \"INGRESS_TRAFFIC_INTERNAL_LOAD_BALANCER\"\n\n  template {\n    service_account = google_service_account.app.email\n\n    scaling {\n      min_instance_count = var.environment == \"prod\" ? 1 : 0\n      max_instance_count = 100\n    }\n\n    containers {\n      image = \"${var.region}-docker.pkg.dev/${var.project_id}/app/myapp:${var.image_tag}\"\n\n      ports {\n        container_port = 8080\n      }\n\n      resources {\n        limits = {\n          cpu    = \"2\"\n          memory = \"1Gi\"\n        }\n        cpu_idle = true  # Scale to zero\n      }\n\n      env {\n        name  = \"PROJECT_ID\"\n        value = var.project_id\n      }\n\n      env {\n        name = \"DATABASE_URL\"\n        value_source {\n          secret_key_ref {\n            secret  = google_secret_manager_secret.db_url.secret_id\n            version = \"latest\"\n          }\n        }\n      }\n\n      startup_probe {\n        http_get {\n          path = \"/health\"\n        }\n        initial_delay_seconds = 10\n        period_seconds        = 3\n        failure_threshold     = 3\n      }\n\n      liveness_probe {\n        http_get {\n          path = \"/health\"\n        }\n        period_seconds    = 30\n        failure_threshold = 3\n      }\n    }\n\n    vpc_access {\n      network_interfaces {\n        network    = google_compute_network.main.name\n        subnetwork = google_compute_subnetwork.app.name\n      }\n      egress = \"PRIVATE_RANGES_ONLY\"\n    }\n  }\n\n  traffic {\n    type    = \"TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST\"\n    percent = 100\n  }\n}\n\n# IAM - Allow unauthenticated (public API)\nresource \"google_cloud_run_v2_service_iam_member\" \"public\" {\n  count    = var.public_access ? 1 : 0\n  location = google_cloud_run_v2_service.app.location\n  name     = google_cloud_run_v2_service.app.name\n  role     = \"roles/run.invoker\"\n  member   = \"allUsers\"\n}\n\n# Custom domain\nresource \"google_cloud_run_domain_mapping\" \"app\" {\n  location = var.region\n  name     = var.domain\n\n  metadata {\n    namespace = var.project_id\n  }\n\n  spec {\n    route_name = google_cloud_run_v2_service.app.name\n  }\n}\n```\n\n## Cloud SQL\n\n### PostgreSQL Instance\n\n```hcl\nresource \"google_sql_database_instance\" \"main\" {\n  name             = \"${var.project_id}-postgres\"\n  database_version = \"POSTGRES_15\"\n  region           = var.region\n\n  settings {\n    tier              = var.environment == \"prod\" ? \"db-custom-4-16384\" : \"db-f1-micro\"\n    availability_type = var.environment == \"prod\" ? \"REGIONAL\" : \"ZONAL\"\n    disk_size         = 100\n    disk_type         = \"PD_SSD\"\n    disk_autoresize   = true\n\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = var.environment == \"prod\"\n      transaction_log_retention_days = 7\n      backup_retention_settings {\n        retained_backups = var.environment == \"prod\" ? 30 : 7\n      }\n    }\n\n    ip_configuration {\n      ipv4_enabled    = false\n      private_network = google_compute_network.main.id\n      require_ssl     = true\n    }\n\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n\n    maintenance_window {\n      day          = 7  # Sunday\n      hour         = 3\n      update_track = \"stable\"\n    }\n\n    insights_config {\n      query_insights_enabled  = true\n      query_string_length     = 1024\n      record_application_tags = true\n      record_client_address   = true\n    }\n  }\n\n  deletion_protection = var.environment == \"prod\"\n}\n\nresource \"google_sql_database\" \"main\" {\n  name     = var.database_name\n  instance = google_sql_database_instance.main.name\n}\n\nresource \"google_sql_user\" \"app\" {\n  name     = \"app\"\n  instance = google_sql_database_instance.main.name\n  password = random_password.db.result\n}\n```\n\n## Cloud Storage\n\n### Secure Bucket\n\n```hcl\nresource \"google_storage_bucket\" \"data\" {\n  name          = \"${var.project_id}-data\"\n  location      = var.region\n  force_destroy = var.environment != \"prod\"\n\n  uniform_bucket_level_access = true\n\n  versioning {\n    enabled = true\n  }\n\n  encryption {\n    default_kms_key_name = google_kms_crypto_key.storage.id\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 90\n    }\n    action {\n      type          = \"SetStorageClass\"\n      storage_class = \"NEARLINE\"\n    }\n  }\n\n  lifecycle_rule {\n    condition {\n      age = 365\n    }\n    action {\n      type          = \"SetStorageClass\"\n      storage_class = \"COLDLINE\"\n    }\n  }\n\n  lifecycle_rule {\n    condition {\n      num_newer_versions = 3\n    }\n    action {\n      type = \"Delete\"\n    }\n  }\n\n  cors {\n    origin          = [\"https://${var.domain}\"]\n    method          = [\"GET\", \"PUT\", \"POST\"]\n    response_header = [\"*\"]\n    max_age_seconds = 3600\n  }\n\n  labels = local.common_labels\n}\n\n# Prevent public access\nresource \"google_storage_bucket_iam_binding\" \"prevent_public\" {\n  bucket = google_storage_bucket.data.name\n  role   = \"roles/storage.objectViewer\"\n  members = [\n    \"serviceAccount:${google_service_account.app.email}\",\n  ]\n}\n```\n\n## Cost Optimization\n\n### Committed Use Discounts\n\n| Commitment | Discount |\n|------------|----------|\n| 1-year CUD | 37% |\n| 3-year CUD | 55% |\n| Spot VMs | 60-91% |\n\n### Budget Alerts\n\n```hcl\nresource \"google_billing_budget\" \"main\" {\n  billing_account = var.billing_account_id\n  display_name    = \"${var.project_id} Budget\"\n\n  budget_filter {\n    projects = [\"projects/${var.project_id}\"]\n  }\n\n  amount {\n    specified_amount {\n      currency_code = \"USD\"\n      units         = var.monthly_budget\n    }\n  }\n\n  threshold_rules {\n    threshold_percent = 0.5\n    spend_basis       = \"CURRENT_SPEND\"\n  }\n\n  threshold_rules {\n    threshold_percent = 0.8\n    spend_basis       = \"CURRENT_SPEND\"\n  }\n\n  threshold_rules {\n    threshold_percent = 1.0\n    spend_basis       = \"FORECASTED_SPEND\"\n  }\n\n  all_updates_rule {\n    pubsub_topic = google_pubsub_topic.budget_alerts.id\n  }\n}\n```\n\n## CLI Reference\n\n```bash\n# Auth\ngcloud auth login\ngcloud auth application-default login\ngcloud config set project PROJECT_ID\n\n# Compute\ngcloud compute instances list\ngcloud compute instances start INSTANCE\ngcloud compute ssh INSTANCE --zone ZONE\n\n# GKE\ngcloud container clusters get-credentials CLUSTER --region REGION\ngcloud container clusters list\n\n# Cloud Run\ngcloud run services list\ngcloud run deploy SERVICE --image IMAGE --region REGION\ngcloud run services update-traffic SERVICE --to-latest\n\n# Cloud SQL\ngcloud sql instances list\ngcloud sql connect INSTANCE --user USER\n\n# Storage\ngsutil ls gs://BUCKET/\ngsutil cp FILE gs://BUCKET/\ngsutil rsync -r ./folder gs://BUCKET/folder\n\n# Secrets\ngcloud secrets list\ngcloud secrets versions access latest --secret SECRET_NAME\n\n# Logs\ngcloud logging read \"resource.type=cloud_run_revision\" --limit 100\n```\n\n## Security Checklist\n\n- [ ] VPC Service Controls enabled\n- [ ] Private Google Access enabled\n- [ ] Cloud NAT for outbound traffic\n- [ ] Workload Identity for GKE\n- [ ] Binary Authorization enabled\n- [ ] Cloud Armor for DDoS protection\n- [ ] Secret Manager for credentials\n- [ ] Cloud Audit Logs enabled\n- [ ] Security Command Center enabled\n\n## Integration\n\nWorks with:\n- `/terraform` - GCP provider configuration\n- `/k8s` - GKE deployments\n- `/devops` - GCP deployment pipelines\n- `/security` - GCP security review\n"},"lastSynced":"2026-03-08T02:03:30.493Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Infrastructure Agents needing advanced Google Cloud Platform architecture design and deployment capabilities.","zh":"非常适合需要高级Google Cloud Platform架构设计和部署能力的Cloud Infrastructure Agents。","ja":"Google Cloud Platformの高度なアーキテクチャ設計およびデプロイ能力が必要なCloud Infrastructure Agentsに最適。","ko":"고급 Google Cloud Platform 아키텍처 디자인 및 배포 기능이 필요한 Cloud Infrastructure 에이전트에 적합합니다.","es":"Perfecto para agentes de infraestructura en la nube que necesitan capacidades de diseño y despliegue de arquitectura avanzada de Google Cloud Platform.","fr":"Parfait pour les agents d''infrastructure cloud qui nécessitent des capacités de conception et de déploiement d''architecture avancée de Google Cloud Platform.","de":"Perfekt für Cloud-Infrastrukturagenten, die erweiterte Design- und Bereitstellungsfunktionen für die Google Cloud Platform-Architektur benötigen.","pt":"Perfeito para Agentes de Infraestrutura em Nuvem que necessitam de capacidades avançadas de design e implantação de arquitetura da Plataforma Google Cloud.","ru":"Идеально подходит для агентов облачной инфраструктуры, которым необходимы расширенные возможности проектирования и развертывания архитектуры Google Cloud Platform.","ar":"مثالي للوكلاء البنية السحابية الذين يحتاجون إلى مهارات متقدمة لتصميم وتنفيذ هيكل منصة جوجل سحابية."},"recommendation":{"en":"Empowers agents to design secure and scalable infrastructure on Google Cloud Platform, leveraging services like Google Kubernetes Engine, IAM policies, and VPC networking, while optimizing costs and performance.","zh":"使得代理能够设计安全且可扩展的基础设施在Google Cloud Platform，利用诸如Google Kubernetes Engine、IAM策略和VPC网络等服务，同时优化成本和性能。","ja":"エージェントがGoogle Cloud Platformでセキュアでスケーラブルなインフラストラクチャを設計できるようにし、Google Kubernetes Engine、IAMポリシー、VPCネットワーキングなどのサービスを活用して、コストとパフォーマンスを最適化します。","ko":"에이전트가 Google Cloud Platform에서 보안이 유지되며 확장 가능한 인프라를 설계할 수 있도록 하며, Google Kubernetes Engine, IAM 정책 및 VPC 네트워킹과 같은 서비스를 활용하여 비용 및 성능을 최적화합니다.","es":"Habilita a los agentes para diseñar infraestructuras seguras y escalables en Google Cloud Platform, aprovechando servicios como Google Kubernetes Engine, políticas de IAM y redes de VPC, al mismo tiempo que se optimizan los costos y el rendimiento.","fr":"Permet aux agents de concevoir des infrastructures sécurisées et évolutives sur Google Cloud Platform, en exploitant des services tels que Google Kubernetes Engine, les stratégies IAM et le réseau VPC, tout en optimisant les coûts et les performances.","de":"Ermöglicht es Agenten, sichere und skalierbare Infrastrukturen auf Google Cloud Platform zu entwerfen, indem Dienste wie Google Kubernetes Engine, IAM-Richtlinien und VPC-Netzwerke genutzt werden, während Kosten und Leistung optimiert werden.","pt":"Habilita os agentes a projetar infraestruturas seguras e escaláveis na Plataforma Google Cloud, utilizando serviços como Google Kubernetes Engine, políticas IAM e networking VPC, ao mesmo tempo em que otimiza custos e desempenho.","ru":"Предоставляет агентам возможность проектировать безопасную и масштабируемую инфраструктуру на платформе Google Cloud, используя сервисы như Google Kubernetes Engine, политики IAM и сетевое взаимодействие VPC, при этом оптимизируя затраты и производительность.","ar":"تمكّن الوكلاء من تصميم بنية تحتية آمنة وقابلة للتوسعة على منصة جوجل سحابية، مع استخدام خدمات مثل محرك كوبرنيتس جوجل وسياسات IAM والشبكات VPC، مع تحسين التكاليف والأداء في نفس الوقت."},"useCases":{"en":["Designing GCP architecture for new projects","Deploying applications to GCP services with configured IAM policies","Optimizing GCP costs and performance for existing deployments"],"zh":["为新项目设计GCP架构","将应用程序部署到具有配置的IAM策略的GCP服务","优化现有部署的GCP成本和性能"],"ja":["新しいプロジェクトのためのGCPアーキテクチャの設計","IAMポリシーを設定したGCPサービスへのアプリケーションのデプロイ","既存のデプロイのGCPコストとパフォーマンスの最適化"],"ko":["새로운 프로젝트를 위한 GCP 아키텍처 디자인","설정된 IAM 정책을 사용하는 GCP 서비스에 대한 애플리케이션 배포","기존 배포의 GCP 비용 및 성능 최적화"],"es":["Diseñar la arquitectura de GCP para nuevos proyectos","Implementar aplicaciones en servicios de GCP con políticas de IAM configuradas","Optimizar los costos y el rendimiento de GCP para despliegues existentes"],"fr":["Concevoir l''architecture GCP pour de nouveaux projets","Déployer des applications sur des services GCP avec des stratégies IAM configurées","Optimiser les coûts et les performances de GCP pour les déploiements existants"],"de":["Entwerfen der GCP-Architektur für neue Projekte","Bereitstellen von Anwendungen in GCP-Diensten mit konfigurierten IAM-Richtlinien","Optimieren von GCP-Kosten und -Leistung für bestehende Bereitstellungen"],"pt":["Projeto de arquitetura GCP para novos projetos","Implantação de aplicações em serviços GCP com políticas IAM configuradas","Otimização de custos e desempenho GCP para implantações existentes"],"ru":["Проектирование архитектуры GCP для новых проектов","Развертывание приложений в сервисах GCP с настроенными политиками IAM","Оптимизация затрат и производительности GCP для существующих развертываний"],"ar":["تصميم هيكل جوجل سحابية لمشاريع جديدة","نشر تطبيقات على خدمات جوجل سحابية مع سياسات IAM معدة مسبقا","تحسين التكاليف والأداء لجوجل سحابية لنشرات موجودة"]},"limitations":{"en":["Requires Google Cloud Platform account and credentials","GCP-specific services and features only"],"zh":["需要Google Cloud Platform账户和凭证","仅限GCP特定服务和功能"],"ja":["Google Cloud Platformアカウントと資格情報が必要","GCP固有のサービスおよび機能のみ"],"ko":["Google Cloud Platform 계정 및 자격 증명이 필요","GCP 특정 서비스 및 기능만"],"es":["Requiere una cuenta y credenciales de Google Cloud Platform","Servicios y características específicos de GCP solo"],"fr":["Nécessite un compte et des informations d''identification de Google Cloud Platform","Services et fonctionnalités spécifiques à GCP uniquement"],"de":["Benötigt ein Google Cloud Platform-Konto und -Anmeldeinformationen","Nur GCP-spezifische Dienste und Funktionen"],"pt":["Requer conta e credenciais da Plataforma Google Cloud","Serviços e recursos específicos do GCP apenas"],"ru":["Требуется учетная запись и учетные данные платформы Google Cloud","Только сервисы и функции, специфичные для GCP"],"ar":["يتطلب حساباً وشهادةً لمنصة جوجل سحابية","خدمات وميزات محددة لجوجل سحابية فقط"]},"version":4},"contentHash":"837cef6e2d84dba312033d4c194ad1cac058035557ea9fcbb02c28d8274db79d","qualityScore":54}');
