INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('maminul007/trading-platform/alpha-decay', 'alpha-decay', 'maminul007', 'trading-platform', 'community', 'alpha-decay maminul007 trading-platform community The alpha-decay skill detects and analyzes alpha decay in trading strategies using statistical methods, benefiting traders and strategists. It provides detailed decay metrics and customizable analysis periods. Alpha-Decay是一种检测和分析交易策略中的统计方法，通过命令行界面（CLI）进行配置和使用。它支持自定义阈值和分析周期 Alpha-Decayはトレーディング戦略の統計的手法を検出および分析するもので、コマンドラインインターフェース（CLI）を使用して設定および使用します。カスタム閾値と分析周期をサポート Alpha-Decay는 거래 전략의 통계적 방법을 감지하고 분석하는 것으로, 명령줄 인터페이스(CLI)를 통해 설정 및 사용합니다. 사용자 지정 임계값 및 분석 기간을 지원 Alpha-decay es una herramienta de detección de decaimiento alfa en estrategias de trading que utiliza métodos estadísticos para analizar el rendimiento de las estrategias Alpha-decay est un outil de détection de décroissance alpha dans les stratégies de trading qui utilise des méthodes statistiques pour analyser les performances des stratégies Alpha-decay ist ein Tool zur Erkennung von Alpha-Zerfall in Tradingstrategien, das statistische Methoden zur Analyse der Strategieergebnisse anwendet O alpha-decay é uma ferramenta para detecção de decaimento alfa em estratégias de negociação, utilizando métodos estatísticos Alpha-decay - это инструмент для обнаружения альфа-распада в торговых стратегиях, использующий статистические методы alpha-decay هو أداة لتحليل الانحلال الألفا في استراتيجيات التداول، باستخدام أساليب إحصائية how to use alpha-decay what is alpha-decay alpha-decay alternative alpha-decay vs trading strategy optimizer alpha-decay install guide alpha-decay setup tutorial statistical analysis for trading alpha decay detection methods customizable trading strategy analysis Alpha-Decay Algotradingstudio AI工具 交易策略 统计方法 命令行界面 CLI 自定义阈值 分析周期 Detects alpha decay in trading strategies using statistical methods Analyzes specific strategies with the /alpha-decay --strategy command Allows custom decay threshold setup with the --threshold option Enables analysis period customization in days with the --period option Provides detailed decay metrics with the --detailed flag alpha-decay is a statistical analysis technique for detecting and analyzing alpha decay in trading strategies, using commands like /alpha-decay and customizable thresholds.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('D0miH/claudsidian/validate_paper_links', 'community', 'D0miH', 'claudsidian', 'D0miH/claudsidian', 'validate_paper_links', 0, 0, 54, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:35.641Z', 'fa82ec3f1a8d8499d83e7550c35e4b20a79b7f31a55ed15e0a6173ebd3b901dc', '{"id":"D0miH/claudsidian/validate_paper_links","name":"validate_paper_links","description":{"en":"The validate_paper_links skill checks paper links against actual references and citation patterns, benefiting researchers and authors. It prevents links to unreferenced papers and incorrect titles.","zh":"验证论文链接，确保链接正确性和可靠性。该技能验证论文标题、引用和文件名","ja":"論文リンクを検証して、リンクの正確性と信頼性を確保する。 このスキルは、論文タイトル、引用、ファイル名を検証する","ko":"논문 링크를 검증하여 링크의 정확성과 신뢰성을 보장합니다. 이 스킬은 논문 제목, 인용, 파일 이름을 검증합니다","es":"Validate_paper_links es una habilidad que valida enlaces de papel contra referencias y patrones de citación reales","fr":"Validate_paper_links est une compétence qui valide les liens de papier contre les références et les modèles de citation réels","de":"Validate_paper_links ist eine Fähigkeit, die Papierlinks gegen tatsächliche Referenzen und Zitiermuster validiert","pt":"O Validate Paper Links é uma habilidade que valida links de artigos contra referências e padrões de citação, prevenindo erros de referência","ru":"Validate Paper Links - это навык, который проверяет ссылки на статьи против ссылок и цитат, предотвращая ошибки ссылок с помощью ИИ Агентов","ar":"validate_paper_links هو مهارة لتأكيد صحة روابط المقالات مقابل المراجع وأنماط الاقتباس، لمنع أخطاء المراجع في أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"validate_paper_links: Paper Link Validation Setup Guide |...","zh":"AI工具：验证论文链接设置指南","ja":"AIエージェント：論文リンク検証ベストプラクティス","ko":"AI 에이전트: 논문 링크 검증 가이드","es":"Guía de configuración de validate_paper_links para preven...","fr":"Configurer validate_paper_links pour éviter les liens de ...","de":"Einrichtungsleitfaden für validate_paper_links zur Vermei...","pt":"Guia de Configuração do Validate Paper Links para Preveni...","ru":"Настройка Validate Paper Links: лучшие практики для ИИ Аг...","ar":"دليل إعداد validate_paper_links لمنع أخطاء المراجع في أدو..."},"description":{"en":"Discover how validate_paper_links prevents hallucinations, incorrect titles, and broken file names in paper notes. Learn how to set up this AI agent skill to...","zh":"验证论文链接，防止幻觉和错误引用。了解如何使用AI工具验证论文链接","ja":"論文リンクを検証して、幻覚や誤引用を防ぐ。AIエージェントを使用して論文リンクを検証する方法を学ぶ","ko":"논문 링크를 검증하여 환각과 오류를 방지합니다. AI 에이전트를 사용하여 논문 링크를 검증하는 방법을 알아보세요","es":"Aprenda a configurar validate_paper_links para validar enlaces de papel y prevenir errores de referencia y citación","fr":"Découvrez comment configurer validate_paper_links pour valider les liens de papier et éviter les erreurs de référence et de citation","de":"Erfahren Sie, wie Sie validate_paper_links einrichten, um Papierlinks zu validieren und Referenz- und Zitierfehler zu vermeiden","pt":"Aprenda a configurar o Validate Paper Links para evitar links inválidos e melhorar a precisão das referências em seus artigos","ru":"Узнайте, как настроить Validate Paper Links, чтобы предотвратить ошибки ссылок и улучшить точность цитат в ваших статьях с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد validate_paper_links لمنع الروابط الخاطئة وتحسين دقة المراجع في مقالاتك مع أدوات الذكاء الاصطناعي"},"definition":{"en":"validate_paper_links is a skill that validates paper links in notes against actual paper references and citations to prevent errors and inconsistencies.","zh":"验证论文链接是指验证论文中的链接是否正确和可靠的过程","ja":"論文リンク検証とは、論文内のリンクが正確で信頼できるかどうかを検証するプロセスである","ko":"논문 링크 검증은 논문 내의 링크가 정확하고 신뢰할 수 있는지 검증하는 과정입니다","es":"Validate_paper_links es una herramienta de AI que verifica la exactitud de los enlaces de papel en notas de investigación","fr":"Validate_paper_links est un outil d''IA qui vérifie l''exactitude des liens de papier dans les notes de recherche","de":"Validate_paper_links ist ein AI-Tool, das die Genauigkeit von Papierlinks in Forschungsnachrichten überprüft","pt":"O Validate Paper Links é uma ferramenta que verifica a validade de links de artigos em notas","ru":"Validate Paper Links - это инструмент, который проверяет допустимость ссылок на статьи в заметках с помощью ИИ Агентов","ar":"validate_paper_links هو أداة لتأكيد صحة روابط المقالات في الملاحظات مع أدوات الذكاء الاصطناعي"},"features":{"en":["Validates [[Paper Title]] links against actual paper references","Prevents links to papers not referenced in the current paper (hallucination)","Checks for incorrect paper titles or formatting","Filters out links to low-influence papers (cited once, not foundational)","Replaces colon (:) with hyphen (-) in file names to prevent broken links"],"zh":["验证论文标题是否正确","检查引用是否存在","检测低影响力论文","修复破损的文件名","防止幻觉和错误引用"],"ja":["論文タイトルの正確性を検証する","引用が存在するかどうかをチェックする","低影響力論文を検出する","破損したファイル名を修復する","幻覚や誤引用を防ぐ"],"ko":["논문 제목의 정확성을 검증합니다","인용이 존재하는지 확인합니다","저영향 논문을 감지합니다","파괴된 파일 이름을 修復합니다","환각과 오류를 방지합니다"],"es":["Validación de enlaces de papel contra referencias reales","Detección de enlaces con títulos incorrectos o formato incorrecto","Filtrado de enlaces a papeles con baja influencia","Corrección de nombres de archivo rotos"],"fr":["Validation des liens de papier contre les références réelles","Détection des liens avec des titres incorrects ou un format incorrect","Filtrage des liens vers des papiers à faible influence","Correction des noms de fichiers cassés"],"de":["Validierung von Papierlinks gegen tatsächliche Referenzen","Erkennung von Links mit falschen Titeln oder falschem Format","Filtern von Links zu Papieren mit geringem Einfluss","Korrektur von fehlerhaften Dateinamen"],"pt":["Validação de links de artigos contra referências","Prevenção de links inválidos e erros de referência","Verificação de títulos e formatação de artigos","Detecção de artigos com influência baixa","Correção de nomes de arquivos quebrados"],"ru":["Проверка ссылок на статьи против ссылок","Предотвращение ошибок ссылок и ошибок цитат с помощью ИИ Агентов","Проверка названий и форматирования статей","Обнаружение статей с низким влиянием","Исправление сломанных имен файлов"],"ar":["التأكد من صحة روابط المقالات مقابل المراجع","منع الروابط الخاطئة وأخطاء المراجع في أدوات الذكاء الاصطناعي","التحقق من أسماء وتنسيق المقالات","الكشف عن المقالات ذات التأثير المنخفض","إصلاح أسماء الملفات المعطوبة"]},"keywords":{"en":["how to use validate_paper_links","validate_paper_links setup guide","paper link validation techniques","validate_paper_links alternative","validate_paper_links vs citation tools","install validate_paper_links","what is validate_paper_links","validate_paper_links for researchers","paper reference validation best practices"],"zh":["AI工具","论文链接验证","论文标题验证","引用检查","低影响力论文检测","文件名修复","幻觉防止","错误引用防止"],"ja":["AIエージェント","論文リンク検証","論文タイトル検証","引用チェック","低影響力論文検出","ファイル名修復","幻覚防止","誤引用防止"],"ko":["AI 에이전트","논문 링크 검증","논문 제목 검증","인용 확인","저영향 논문 감지","파일 이름 修復","환각 방지","오류 방지"],"es":["validación de enlaces de papel","herramientas de AI para investigación","referencias y citación","enlaces de papel incorrectos","papeles con baja influencia","nombres de archivo rotos"],"fr":["validation des liens de papier","outils d''IA pour la recherche","références et citation","liens de papier incorrects","papiers à faible influence","noms de fichiers cassés"],"de":["Validierung von Papierlinks","AI-Tools für Forschung","Referenzen und Zitierung","falsche Papierlinks","Papiere mit geringem Einfluss","fehlerhafte Dateinamen"],"pt":["validate paper links","prevenção de erros de referência","validação de links de artigos","ferramentas de ai para artigos","otimização de referências","correção de erros de citação"],"ru":["validate paper links","предотвращение ошибок ссылок","проверка ссылок на статьи","инструменты ИИ для статей","оптимизация цитат","исправление ошибок цитат с помощью ИИ Агентов"],"ar":["validate_paper_links","منع أخطاء المراجع","التأكد من صحة روابط المقالات","أدوات الذكاء الاصطناعي للمقالات","تحسين دقة المراجع","إصلاح أخطاء الاقتباس في أدوات الذكاء الاصطناعي"]}},"owner":"D0miH","repo":"claudsidian","repoPath":"D0miH/claudsidian","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"validate_paper_links","description":"Validate paper note links against actual paper references and influence","bodyPreview":"## ✅ Validate Paper Links Skill\n\nValidate all `[[Paper Title]]` links in a paper note against the actual paper''s references and citation patterns.\n\n**Goal:** Prevent:\n1. Links to papers NOT referenced in the current paper (hallucination)\n2. Links to papers with incorrect titles or formatting\n3. Links to low-influence papers (cited once, not foundational)\n4. Broken file names (`:` not exchanged to `-`)\n\n---\n\n## CRITICAL RULES\n\n**A link should exist only if:**\n1. ✅ The paper IS referenced in the c","body":"## ✅ Validate Paper Links Skill\n\nValidate all `[[Paper Title]]` links in a paper note against the actual paper''s references and citation patterns.\n\n**Goal:** Prevent:\n1. Links to papers NOT referenced in the current paper (hallucination)\n2. Links to papers with incorrect titles or formatting\n3. Links to low-influence papers (cited once, not foundational)\n4. Broken file names (`:` not exchanged to `-`)\n\n---\n\n## CRITICAL RULES\n\n**A link should exist only if:**\n1. ✅ The paper IS referenced in the current paper''s bibliography/references\n2. ✅ The paper is INFLUENTIAL (cited ≥2 times OR explicitly foundational/cited in intro/abstract)\n3. ✅ Title is in exact Title Case matching the reference\n4. ✅ File name properly formats `:` as `-` (e.g., `Attention - Is All You Need`)\n\n**A link should be removed if:**\n- ❌ Paper is NOT in the current paper''s references\n- ❌ Paper is cited only once in methods/results (low influence)\n- ❌ Title formatting is incorrect\n- ❌ File name violates naming convention\n\n---\n\n## WORKFLOW\n\n### 0. Read last-run timestamp\nRead `.claude/vault_maintanance.md` and note the `validate_paper_links:` timestamp.\n\n**Default: incremental scan** — only validate papers in `Reading/` modified after the `validate_paper_links:` timestamp.\nUse `find Reading/ -newer <reference_file>` to identify changed paper notes.\nTo use a reference file: `touch -t YYYYMMDDHHMI /tmp/validate_ref && find Reading/ -newer /tmp/validate_ref`\n\n- If no papers were modified: skip and report \"All paper links already validated.\"\n- Only run a full rescan if the user explicitly requests it or no timestamp exists yet.\n\n### 1. Get paper and note details\n\nRead the paper note and extract:\n- **Paper URL:** From frontmatter (arXiv HTML URL preferred)\n- **Paper title:** From frontmatter or file name\n- **Authors:** From frontmatter (if available)\n- **Year:** From frontmatter (if available)\n\n### 2. Fetch references section from arXiv HTML\n\n**Access paper:**\n- Use paper URL from frontmatter (typically `https://arxiv.org/html/[paper-id]v[version]`)\n- Use WebFetch with prompt focused **only on references section**\n- Skip all paper content (abstract, introduction, methods, results, etc.)\n- Extract **only** the bibliography/references section\n\n**Extract citation data:**\n- Parse reference list to get: titles, authors, years\n- Build structured reference list from bibliography section\n- Reference section is clearly marked on arXiv HTML pages\n\n**WebFetch optimization:**\n- Prompt: \"Extract ONLY the bibliography/references section. Ignore all other paper content (abstract, introduction, methods, results). Return reference titles, authors, and years.\"\n- This signals to skip 90% of paper content and focus only on references\n- Saves tokens by not parsing paper text\n\n**Why arXiv HTML:**\n- ✅ Direct access to paper bibliography\n- ✅ Pre-formatted references (easy to extract)\n- ✅ No API rate limiting or authentication\n- ✅ Reliable and consistent structure across papers\n- ✅ No JavaScript rendering issues\n- ✅ Can optimize WebFetch to skip content (token savings)\n\n### 3. Read paper note\n\n- Open paper note from `Reading/[filename].md`\n- Extract all `[[Paper Title]]` links from \"🔗 Connections to Other Work\" section\n- Build link list with current formatting\n\n### 4. Validate each link\n\n**For each `[[Paper Title]]` in the note:**\n\n**Check 1: Reference exists?**\n- Does this paper appear in the current paper''s bibliography?\n- If NO → FLAG: \"Not referenced in paper\" (candidate for removal)\n- If YES → PASS\n\n**Check 2: Influence level**\n- Count how many times the paper is cited in the current paper''s text\n- Referenced paper with `≥2` citations in this paper = influential ✓\n- Referenced paper cited once but foundational (cited in abstract/intro)? = influential ✓\n- Referenced paper cited only once in methods/results (low-impact section)? = LOW influence (candidate for removal)\n- If influence is borderline → ask user for judgment\n\n**Check 3: Title formatting**\n- Compare link title against reference list title\n- Is it Title Case?\n- Are colons `:` present in reference but `-` in link?\n- Are special characters consistent?\n- If mismatch → FLAG: \"Title mismatch\" or \"Formatting error\"\n\n**Check 4: File name validity**\n- Expected file name: exact title with `:` → `-`\n- Is current link pointing to correct file name?\n- Example: `[[Attention - Is All You Need]]` should match file `Attention - Is All You Need.md`\n- If mismatch → FLAG: \"File name doesn''t match link\"\n\n### 5. Generate validation report\n\nGroup findings by severity:\n\n**🔴 CRITICAL (remove immediately):**\n- Papers not in references\n- Papers cited only once in low-importance sections\n\n**🟡 NEEDS FIXING:**\n- Title case errors\n- File name formatting errors (`:` not converted to `-`)\n\n**🟢 OK:**\n- Papers properly referenced\n- Properly formatted\n- Appropriately influential\n\n**❓ NEEDS USER JUDGMENT:**\n- Papers cited ~2 times (borderline influence)\n- Foundational papers cited rarely but in key sections\n\n### 6. Apply fixes\n\nWith user approval:\n- **Remove links:** Delete `[[Paper Title]]` lines from \"🔗 Connections to Other Work\"\n- **Fix titles:** Correct Title Case and formatting to match references\n- **Fix file names:** Ensure `:` → `-` conversion\n- **Update note:** Save corrected paper note\n- **Verify:** Re-scan to confirm all links now valid\n\n### 7. Update vault_maintanance.md\nAfter completing validation (regardless of whether fixes were applied):\n- Run `date` via Bash to get the current system time\n- Read `.claude/vault_maintanance.md`\n- Update `validate_paper_links:` line to current date and time in format `DD-MM-YYYY HH:MM`\n- Reset `papers_since_validate_links:` to `0`\n- Write the updated file\n\n**Example update:**\n```\nvalidate_paper_links: 10-02-2026 14:35\n```\n\n---\n\n## TOKEN EFFICIENCY\n\n**Optimizations:**\n- **arXiv HTML** for direct bibliography access (single WebFetch call)\n- **References-only extraction** via targeted WebFetch prompt\n- Skip all paper content (abstract, intro, methods, results)\n- Bibliography section clearly marked and easy to extract\n- No API calls, no rate limiting, no authentication needed\n- Direct title + author list from bibliography\n- Build simple title→reference mapping\n\n**Why this is efficient:**\n- 1 WebFetch call to arXiv HTML (direct paper access via frontmatter URL)\n- **Targeted prompt skips 90% of paper content** (saves major tokens)\n- Bibliography section is well-formatted and clearly delimited\n- No API dependencies or rate limiting concerns\n- Minimal parsing needed (just extract reference titles)\n- No ambiguity in reference data\n\n**Workflow:**\n1. Read paper note frontmatter for arXiv HTML URL\n2. WebFetch the arXiv HTML page with prompt: \"Extract ONLY bibliography/references section. Skip all other content.\"\n3. Extract bibliography/references section\n4. Build reference list from bibliography\n5. Validate links against reference list\n\n**Avoid:**\n- Semantic Scholar (JavaScript rendering, rate limiting issues)\n- PDF parsing\n- Regex patterns for extraction (bibliography is already structured)\n- Processing full paper text (use targeted prompt instead)\n\n**Expected cost:** ~100-150 tokens per paper (1 optimized WebFetch call + validation)\n\n---\n\n## OUTPUT RULES\n\n- Grouped by severity (CRITICAL → needs fixing → OK)\n- File name / Link text / Issue / Suggested fix\n- No prose, bullets only\n- Example:\n\n```\n🔴 CRITICAL (remove):\n- [[Paper Not In References]] - Not in bibliography → REMOVE\n\n🟡 NEEDS FIXING:\n- [[attention is all you need]] - Title case error → Fix to [[Attention Is All You Need]]\n- [[My Paper: A Study]] - File name formatting → Should be [[My Paper - A Study]]\n\n🟢 OK (keep):\n- [[Transformers are All You Need]] ✓\n```\n\n---\n\n## SELF-CHECK\n\n✅ Did I fetch the arXiv HTML page from the frontmatter URL?\n✅ Did I extract all references from the bibliography section?\n✅ Did I extract reference metadata (title, authors, year)?\n✅ Did I check each link against the bibliography references?\n✅ Did I assess influence (citation count/context in paper)?\n✅ Did I validate Title Case formatting against bibliography titles?\n✅ Did I check file name convention (: → -)?\n✅ Did I group findings by severity?\n✅ Did I get user approval before removing links?\n✅ Did I verify all remaining links are valid?\n✅ Did I update vault_maintanance.md with current timestamp?\n"},"lastSynced":"2026-03-08T02:03:35.641Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents requiring accurate citation and reference validation in academic papers.","zh":"适用于需要在学术论文中准确验证引用和参考的研究代理","ja":"研究エージェントが学術論文で正確な引用と参照の検証を必要とする場合に最適","ko":"학술 논문에서 정확한 인용과 참조 검증이 필요한 연구 에이전트에 적합","es":"Ideal para Agentes de Investigación que requieren una citación y validación de referencias precisas en artículos académicos.","fr":"Idéal pour les agents de recherche nécessitant une citation et une validation de références précises dans les articles universitaires.","de":"Ideal für Forschungsagenten, die eine genaue Zitierung und Validierung von Referenzen in akademischen Artikeln erfordern.","pt":"Ideal para Agentes de Pesquisa que exigem citação precisa e validação de referências em artigos acadêmicos.","ru":"Идеально для исследовательских агентов, требующих точной цитаты и проверки ссылок в академических статьях.","ar":"مثالي للوكلاء البحثيين الذين يتطلبون الاستشهاد الدقيق و التحقق من المراجع في الأوراق الأكاديمية."},"recommendation":{"en":"Empowers agents to verify paper links against actual references and citation patterns, preventing hallucinations and ensuring correct titles and formatting using protocols like citation analysis and reference checking.","zh":"赋予代理验证论文链接与实际参考和引用模式的能力，防止出现幻觉并确保使用诸如引用分析和参考检查等协议的正确标题和格式","ja":"エージェントが実際の参照と引用パターンに対して論文リンクを検証する能力を付与し、幻覚を防ぎ、引用分析や参照チェックなどのプロトコルを使用して正しいタイトルとフォーマットを確保する","ko":"에이전트가 실제 참조와 인용 패턴에 대해 논문 링크를 검증할 수 있는 능력을 부여하여 환상을 방지하고 인용 분석 및 참조 확인 등의 프로토콜을 사용하여 올바른 제목과 형식을 보장","es":"Habilita a los agentes a verificar los enlaces de los artículos contra referencias y patrones de citación reales, evitando alucinaciones y asegurando títulos y formatos correctos utilizando protocolos como análisis de citación y verificación de referencias.","fr":"Permet aux agents de vérifier les liens d''articles contre des références et des modèles de citation réels, évitant les hallucinations et assurant des titres et des formats corrects en utilisant des protocoles tels que l''analyse de citation et la vérification de références.","de":"Ermächtigt die Agenten, die Verknüpfungen von Artikeln gegen tatsächliche Referenzen und Zitierungsmuster zu überprüfen, Halluzinationen zu vermeiden und korrekte Titel und Formate unter Verwendung von Protokollen wie Zitieranalyse und Referenzprüfung sicherzustellen.","pt":"Habilita os agentes a verificar links de artigos contra referências reais e padrões de citação, prevenindo alucinações e garantindo títulos e formatação corretos usando protocolos como análise de citação e verificação de referências.","ru":"Наделяет агентов возможностью проверять ссылки на статьи против фактических ссылок и моделей цитирования, предотвращая галлюцинации и гарантируя правильные названия и форматирование с помощью протоколов, таких как анализ цитирования и проверка ссылок.","ar":"يمنح الوكلاء القدرة على التحقق من روابط الأوراق ضد المراجع الفعلية وأنماط الاستشهاد، و منع الوهم و ضمان العناوين الصحيحة وتنسيق باستخدام بروتوكولات مثل تحليل الاستشهاد و فحص المراجع."},"useCases":{"en":["Validating paper links in research notes","Preventing incorrect title formatting in citations","Identifying low-influence papers with minimal citations"],"zh":["验证研究笔记中的论文链接","防止引用中的不正确标题格式","识别具有最小引用次数的低影响论文"],"ja":["研究ノート内の論文リンクの検証","引用内の不正確なタイトルフォーマットの防止","最小の引用回数を持つ低影響論文の特定"],"ko":["연구 노트中的 논문 링크를 검증","인용中的 부정확한 제목 형식을 방지","최소한의 인용 횟수를 가진 저영향 논문을 식별"],"es":["Validar los enlaces de los artículos en las notas de investigación","Prevenir la formato de título incorrecto en las citaciones","Identificar artículos de poca influencia con mínimas citaciones"],"fr":["Valider les liens d''articles dans les notes de recherche","Prévenir la mise en forme de titre incorrecte dans les citations","Identifier les articles à faible influence avec des citations minimales"],"de":["Validieren von Artikellinks in Forschungsnote","Verhindern von falschem Titelformat in Zitaten","Identifizieren von Artikeln mit geringem Einfluss und minimalen Zitaten"],"pt":["Validar links de artigos em notas de pesquisa","Prevenir formatação de título incorreta em citações","Identificar artigos de baixa influência com citações mínimas"],"ru":["Проверка ссылок на статьи в исследовательских заметках","Предотвращение неправильного форматирования названий в цитатах","Определение статей с низким влиянием и минимальным количеством цитат"],"ar":["التحقق من روابط الأوراق في ملاحظات البحث","منع تنسيق عنوان غير صحيح في الاستشهادات","تحديد الأوراق ذات التأثير المنخفض مع الاستشهادات القليلة"]},"limitations":{"en":["Requires access to paper references and citation data","Limited to papers with available citation patterns","May not handle broken file names without additional processing"],"zh":["需要访问论文参考和引用数据","仅限于具有可用引用模式的论文","可能无法处理破损的文件名而不进行额外的处理"],"ja":["論文参照と引用データへのアクセスが必要","利用可能な引用パターンを持つ論文に限定","追加の処理を行わないと破損したファイル名を処理できない場合がある"],"ko":["논문 참조 및 인용 데이터에 대한 액세스가 필요","사용 가능한 인용 패턴을 가진 논문에만 적용","추가 처리 없이 손상된 파일 이름을 처리할 수 없는 경우가 있음"],"es":["Requiere acceso a referencias y datos de citación de los artículos","Limitado a artículos con patrones de citación disponibles","Puede no manejar nombres de archivos rotos sin procesamiento adicional"],"fr":["Nécessite un accès aux références et aux données de citation des articles","Limité aux articles avec des modèles de citation disponibles","Peut ne pas gérer les noms de fichiers cassés sans traitement supplémentaire"],"de":["Erfordert Zugriff auf Referenzen und Zitationsdaten von Artikeln","Begrenzt auf Artikel mit verfügbaren Zitierungsmustern","Kann gebrochene Dateinamen ohne zusätzliche Verarbeitung nicht verarbeiten"],"pt":["Exige acesso a referências e dados de citação de artigos","Limitado a artigos com padrões de citação disponíveis","Pode não lidar com nomes de arquivos quebrados sem processamento adicional"],"ru":["Требует доступа к ссылкам и данным о цитировании статей","Ограничен статьями с доступными моделями цитирования","Может не обрабатывать сломанные имена файлов без дополнительной обработки"],"ar":["يتطلب الوصول إلى المراجع وبيانات الاستشهاد للأوراق","محدود بالأوراق التي تتوفر فيها أنماط الاستشهاد","قد لا يتعامل مع أسماء الملفات المعطوبة بدون معالجة إضافية"]},"version":4},"contentHash":"fa82ec3f1a8d8499d83e7550c35e4b20a79b7f31a55ed15e0a6173ebd3b901dc","qualityScore":54}');
