INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('D0miH/claudsidian/validate_paper_links', 'validate_paper_links', 'D0miH', 'claudsidian', 'community', 'validate_paper_links D0miH claudsidian community The validate_paper_links skill checks paper links against actual references and citation patterns, benefiting researchers and authors. It prevents links to unreferenced papers and incorrect titles. 验证论文链接，确保链接正确性和可靠性。该技能验证论文标题、引用和文件名 論文リンクを検証して、リンクの正確性と信頼性を確保する。 このスキルは、論文タイトル、引用、ファイル名を検証する 논문 링크를 검증하여 링크의 정확성과 신뢰성을 보장합니다. 이 스킬은 논문 제목, 인용, 파일 이름을 검증합니다 Validate_paper_links es una habilidad que valida enlaces de papel contra referencias y patrones de citación reales Validate_paper_links est une compétence qui valide les liens de papier contre les références et les modèles de citation réels Validate_paper_links ist eine Fähigkeit, die Papierlinks gegen tatsächliche Referenzen und Zitiermuster validiert O Validate Paper Links é uma habilidade que valida links de artigos contra referências e padrões de citação, prevenindo erros de referência Validate Paper Links - это навык, который проверяет ссылки на статьи против ссылок и цитат, предотвращая ошибки ссылок с помощью ИИ Агентов validate_paper_links هو مهارة لتأكيد صحة روابط المقالات مقابل المراجع وأنماط الاقتباس، لمنع أخطاء المراجع في أدوات الذكاء الاصطناعي how to use validate_paper_links validate_paper_links setup guide paper link validation techniques validate_paper_links alternative validate_paper_links vs citation tools install validate_paper_links what is validate_paper_links validate_paper_links for researchers paper reference validation best practices AI工具 论文链接验证 论文标题验证 引用检查 低影响力论文检测 文件名修复 幻觉防止 错误引用防止 Validates [[Paper Title]] links against actual paper references Prevents links to papers not referenced in the current paper (hallucination) Checks for incorrect paper titles or formatting Filters out links to low-influence papers (cited once, not foundational) Replaces colon (:) with hyphen (-) in file names to prevent broken links validate_paper_links is a skill that validates paper links in notes against actual paper references and citations to prevent errors and inconsistencies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dailydotdev/daily-api/local-env', 'community', 'dailydotdev', 'daily-api', 'dailydotdev/daily-api', 'local-env', 0, 0, 54, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.351Z', '7b4f84344753ae7562bd4fa6465463dbb8663dfb67649c5b6db268c7f652b9f9', '{"id":"dailydotdev/daily-api/local-env","name":"local-env","description":{"en":"The local-env skill helps developers manage their local development environment for daily-api, providing assistance with PostgreSQL database access and query execution. It benefits developers working with Docker and Kubernetes.","zh":"local-env 是一个本地环境管理工具，帮助开发者管理本地开发环境，包括 PostgreSQL 数据库访问和查询执行","ja":"local-env はローカル開発環境を管理するツールで、PostgreSQL データベースへのアクセスとクエリの実行をサポート","ko":"local-env 는 로컬 개발 환경을 관리하는 도구로, PostgreSQL 데이터베이스에 접근하고 쿼리를 실행하는 것을 지원","es":"El entorno local te permite desarrollar y probar aplicaciones con daily-api de manera eficiente. Aprende a configurar PostgreSQL y Docker para acceder a la base de datos y ejecutar consultas SQL","fr":"L''environnement local vous permet de développer et de tester des applications avec daily-api de manière efficace. Découvrez comment configurer PostgreSQL et Docker pour accéder à la base de données et exécuter des requêtes SQL","de":"Die lokale Umgebung ermöglicht es Ihnen, Anwendungen mit daily-api effizient zu entwickeln und zu testen. Erfahren Sie, wie Sie PostgreSQL und Docker einrichten, um auf die Datenbank zuzugreifen und SQL-Abfragen auszuführen","pt":"O local-env é uma ferramenta para gerenciar ambientes de desenvolvimento local, incluindo acesso ao banco de dados PostgreSQL via Docker e execução de consultas SQL.","ru":"ИИ Агент local-env - это инструмент для управления локальными средами разработки, включая доступ к базе данных PostgreSQL через Docker и выполнение запросов SQL.","ar":"وضع بيئة التطوير المحلية local-env هو أداة لإد