INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dailydotdev/daily-api/local-env', 'local-env', 'dailydotdev', 'daily-api', 'community', 'local-env dailydotdev daily-api community The local-env skill helps developers manage their local development environment for daily-api, providing assistance with PostgreSQL database access and query execution. It benefits developers working with Docker and Kubernetes. local-env 是一个本地环境管理工具，帮助开发者管理本地开发环境，包括 PostgreSQL 数据库访问和查询执行 local-env はローカル開発環境を管理するツールで、PostgreSQL データベースへのアクセスとクエリの実行をサポート local-env 는 로컬 개발 환경을 관리하는 도구로, PostgreSQL 데이터베이스에 접근하고 쿼리를 실행하는 것을 지원 El entorno local te permite desarrollar y probar aplicaciones con daily-api de manera eficiente. Aprende a configurar PostgreSQL y Docker para acceder a la base de datos y ejecutar consultas SQL L''environnement local vous permet de développer et de tester des applications avec daily-api de manière efficace. Découvrez comment configurer PostgreSQL et Docker pour accéder à la base de données et exécuter des requêtes SQL Die lokale Umgebung ermöglicht es Ihnen, Anwendungen mit daily-api effizient zu entwickeln und zu testen. Erfahren Sie, wie Sie PostgreSQL und Docker einrichten, um auf die Datenbank zuzugreifen und SQL-Abfragen auszuführen O local-env é uma ferramenta para gerenciar ambientes de desenvolvimento local, incluindo acesso ao banco de dados PostgreSQL via Docker e execução de consultas SQL. ИИ Агент local-env - это инструмент для управления локальными средами разработки, включая доступ к базе данных PostgreSQL через Docker и выполнение запросов SQL. وضع بيئة التطوير المحلية local-env هو أداة لإدارة بيئات التطوير المحلية، بما في ذلك الوصول إلى قاعدة بيانات PostgreSQL عبر Docker وتنفيذ استفسارات SQL. how to use local-env local-env setup guide dockerized postgresql kubernetes local development local-env alternative local-env vs docker-compose install local-env what is local-env local-env tutorial local-env 本地环境管理 PostgreSQL 数据库访问 Docker 容器管理 k8s 容器化 SQL 查询执行 AIエージェント 本地开发环境设置 Runs PostgreSQL locally via Docker in a k8s container Provides database access using the `docker ps` and `docker exec` commands Supports execution of SQL queries using `psql` command Allows for multi-line queries using the `EOF` syntax Enables container discovery using `grep` and `docker ps` local-env is a skill that enables local environment management for daily-api, utilizing Docker and Kubernetes to run PostgreSQL and execute SQL queries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('giolaq/Multi-TV-dev-power/tmdb-integration', 'community', 'giolaq', 'Multi-TV-dev-power', 'giolaq/Multi-TV-dev-power', 'tmdb-integration', 0, 0, 54, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:47.556Z', 'fa2d4f0aa02edc26fb4045b4cd5454447903110006589d3ee33e405ea270beba', '{"id":"giolaq/Multi-TV-dev-power/tmdb-integration","name":"tmdb-integration","description":{"en":"The tmdb-integration skill enables developers to seamlessly integrate The Movie Database API with React Native TV applications, providing access to movie and TV show data, images, and more.","zh":"本文介绍如何将TMDB API集成到React Native TV应用中，实现电影和电视节目数据的获取、海报和背景图像的显示等功能","ja":"この記事では、TMDB APIをReact Native TVアプリケーションに統合して、映画やテレビ番組のデータを取得したり、ポスターとバックグラウンドイメージを表示したりする方法について説明します","ko":"이 문서는 React Native TV 애플리케이션에 TMDB API를 통합하여 영화와 TV 프로그램 데이터를 가져오고, 포스터와 배경 이미지를 표시하는 방법에 대해 설명합니다","es":"Integra la API de TMDB con aplicaciones de React Native TV para obtener datos de películas y programas de TV","fr":"Intégrez l''API TMDB avec les applications React Native TV pour obtenir des données de films et de séries TV","de":"Integrieren Sie die TMDB-API mit React Native TV-Anwendungen, um Daten von Filmen und Fernsehsendungen zu erhalten","pt":"Integre a API do The Movie Database com aplicações React Native TV para obter dados de filmes e séries, exibir imagens e implementar funcionalidades de busca","ru":"ИИ Агент для интеграции с TMDB API позволяет получать данные фильмов и сериалов, отображать постеры и реализовывать функции поиска","ar":"دمج واجهة برمجة تطبيقات قاعدة بيانات الأفلام مع تطبيقات React Native TV لاسترجاع بيانات الأفلام والمسلسلات و عرض الصور و تنفيذ وظائف البحث"},"seo":{"title":{"en":"tmdb-integration: API Integration Setup Guide | AI Agent ...","zh":"TMDB集成指南：React Native TV应用最佳实践","ja":"TMDB統合セットアップガイド：React Native TVアプリケーション","ko":"TMDB 통합 설정 가이드: React Native TV 애플리케이션","es":"Guía de Integración de TMDB con React Native","fr":"Configurer l''Intégration de TMDB avec React Native","de":"TMDB-Integration mit React Native: Einrichtungsanleitung","pt":"Guia de Integração TMDB com React Native TV","ru":"Настройка ИИ Агента для интеграции с TMDB API","ar":"دليل تكامل TMDB مع تطبيقات React Native TV"},"description":{"en":"Unlock TMDB''s full potential with our expert integration guide. Learn how to fetch movie data, display images, and optimize API usage for your React Native T...","zh":"了解如何将TMDB API集成到React Native TV应用中，包括身份验证、搜索功能和优化","ja":"TMDB APIをReact Native TVアプリケーションに統合する方法について学びます。認証、検索機能、最適化など","ko":"React Native TV 애플리케이션에 TMDB API를 통합하는 방법에 대해 알아보세요. 인증, 검색 기능, 최적화 등","es":"Aprende a integrar la API de TMDB con aplicaciones de React Native TV y mejora tu experiencia de desarrollo","fr":"Découvrez comment intégrer l''API TMDB avec les applications React Native TV et améliorez votre expérience de développement","de":"Erfahren Sie, wie Sie die TMDB-API mit React Native TV-Anwendungen integrieren und Ihre Entwicklungserfahrung verbessern","pt":"Aprenda a integrar a API do The Movie Database com aplicações React Native TV e melhore a experiência do usuário","ru":"ИИ Агент для интеграции с TMDB API: узнайте, как получить данные фильмов и сериалов, а также реализовать функции поиска","ar":"تعلم كيفية دمج واجهة برمجة تطبيقات قاعدة بيانات الأفلام مع تطبيقات React Native TV و تحسين تجربة المستخدم"},"definition":{"en":"tmdb-integration is a skill that facilitates the integration of The Movie Database API with React Native TV applications, enabling features like data fetching and image display.","zh":"TMDB集成是指将The Movie Database API与React Native TV应用结合，实现电影和电视节目数据的获取和展示","ja":"TMDB統合とは、The Movie Database APIとReact Native TVアプリケーションを組み合わせて、映画やテレビ番組のデータを取得して表示すること","ko":"TMDB 통합은 The Movie Database API와 React Native TV 애플리케이션을 결합하여 영화와 TV 프로그램 데이터를 가져와 표시하는 것을 의미합니다","es":"La integración de TMDB es una habilidad que permite a los desarrolladores acceder a datos de películas y programas de TV","fr":"L''intégration de TMDB est une compétence qui permet aux développeurs d''accéder à des données de films et de séries TV","de":"Die TMDB-Integration ist eine Fähigkeit, die es Entwicklern ermöglicht, auf Daten von Filmen und Fernsehsendungen zuzugreifen","pt":"Integração TMDB é uma habilidade que permite conectar aplicações React Native TV à API do The Movie Database","ru":"Интеграция с TMDB - это способность ИИ Агента подключаться к API The Movie Database","ar":"التكامل مع قاعدة بيانات الأفلام هو قدرة تسمح بتوصيل تطبيقات React Native TV بواجهة برمجة التطبيقات"},"features":{"en":["Fetches movie and TV show data using TMDB API","Displays poster and backdrop images in React Native TV apps","Implements search functionality for trending content","Fetches video trailers and handles TMDB authentication","Optimizes API usage with rate limiting and TypeScript types"],"zh":["支持电影和电视节目数据的获取","实现海报和背景图像的显示","提供搜索功能","获取趋势内容","支持视频预告片的获取","支持TMDB身份验证和API密钥"],"ja":["映画やテレビ番組のデータを取得する","ポスターとバックグラウンドイメージを表示する","検索機能を提供する","トレンドコンテンツを取得する","ビデオプレビューの取得をサポートする","TMDB認証とAPIキーをサポートする"],"ko":["영화와 TV 프로그램 데이터를 가져오는 기능","포스터와 배경 이미지를 표시하는 기능","검색 기능 제공","트렌드 콘텐츠를 가져오는 기능","비디오 예고편을 가져오는 기능","TMDB 인증과 API 키 지원"],"es":["Autenticación de TMDB y claves de API","Implementación de funcionalidad de búsqueda","Obtención de contenido de tendencias","Visualización de imágenes de carteles y fondos","Fetch de trailers de video","Optimización y limitación de velocidad"],"fr":["Authentification TMDB et clés d''API","Mise en œuvre de la fonctionnalité de recherche","Obtention de contenu tendance","Affichage d''images d''affiches et de fonds","Récupération de bandes-annonces de vidéo","Optimisation et limitation de vitesse"],"de":["TMDB-Authentifizierung und API-Schlüssel","Implementierung der Suchfunktion","Abruf von Trend-Inhalten","Anzeige von Poster- und Hintergrundbildern","Abruf von Video-Trailern","Optimierung und Rate Limiting"],"pt":["Obtenção de dados de filmes e séries","Exibição de imagens de capa e fundo","Implementação de funcionalidades de busca","Obtenção de conteúdo em tendência","Reprodução de trailers de vídeo","Autenticação e otimização da API do TMDB"],"ru":["Получение данных фильмов и сериалов","Отображение постеров и фонов","Реализация функций поиска","Получение трендового контента","Воспроизведение видео-трейлеров","Аутентификация и оптимизация API TMDB"],"ar":["استرجاع بيانات الأفلام والمسلسلات","عرض الصور و الخلفيات","تنفيذ وظائف البحث","استرجاع المحتوى الشائع","تشغيل مقاطع الفيديو","التحقق و تحسين واجهة برمجة تطبيقات قاعدة بيانات الأفلام"]},"keywords":{"en":["how to use tmdb-integration","tmdb-integration setup guide","react native tv tmdb api","tmdb integration alternative","tmdb-integration vs themoviedb","tmdb-integration install","what is tmdb-integration","tmdb api optimization","typescript types for tmdb"],"zh":["TMDB集成","React Native TV","电影数据获取","电视节目数据获取","海报显示","背景图像显示","搜索功能","趋势内容","视频预告片"],"ja":["TMDB統合","React Native TV","映画データ取得","テレビ番組データ取得","ポスター表示","バックグラウンドイメージ表示","検索機能","トレンドコンテンツ","ビデオプレビュー"],"ko":["TMDB 통합","React Native TV","영화 데이터 가져오기","TV 프로그램 데이터 가져오기","포스터 표시","배경 이미지 표시","검색 기능","트렌드 콘텐츠","비디오 예고편"],"es":["integración de TMDB","React Native TV","API de TMDB","autenticación de TMDB","desarrollo de aplicaciones de TV","datos de películas y programas de TV","herramientas de desarrollo de AI","agentes de AI"],"fr":["intégration de TMDB","React Native TV","API TMDB","authentification TMDB","développement d''applications de TV","données de films et de séries TV","outils de développement d''IA","agents d''IA"],"de":["TMDB-Integration","React Native TV","TMDB-API","TMDB-Authentifizierung","Entwicklung von TV-Anwendungen","Daten von Filmen und Fernsehsendungen","Entwicklungstools für KI","KI-Agents"],"pt":["integração TMDB","React Native TV","API do The Movie Database","autenticação TMDB","otimização da API","desenvolvimento de aplicações","tecnologias de desenvolvimento","ferramentas de desenvolvimento"],"ru":["ИИ Агенты","интеграция с TMDB","React Native TV","API The Movie Database","аутентификация TMDB","оптимизация API","разработка приложений","технологии разработки","инструменты разработки"],"ar":["أدوات الذكاء الاصطناعي","تكامل قاعدة بيانات الأفلام","تطبيقات React Native TV","واجهة برمجة تطبيقات قاعدة بيانات الأفلام","التحقق من قاعدة بيانات الأفلام","تحسين واجهة برمجة التطبيقات","تطوير التطبيقات","تقنيات التطوير","أدوات التطوير"]}},"owner":"giolaq","repo":"Multi-TV-dev-power","repoPath":"giolaq/Multi-TV-dev-power","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"tmdb-integration","description":"TMDB (The Movie Database) API integration for React Native TV streaming apps. Use when users need help with movie/TV show data, poster images, search functionality, trending content, video trailers from TMDB, API authentication, rate limiting, or TypeScript types for TMDB responses.","bodyPreview":"# TMDB Integration Skill\n\nYou are an expert in integrating The Movie Database (TMDB) API with React Native TV applications. This skill activates when users ask about:\n\n- Fetching movie or TV show data\n- Displaying poster and backdrop images\n- Implementing search functionality\n- Getting trending content\n- Fetching video trailers\n- TMDB authentication and API keys\n- Rate limiting and optimization\n- TypeScript types for TMDB responses\n\n## Authentication\n\nTMDB offers two equivalent authentication me","body":"# TMDB Integration Skill\n\nYou are an expert in integrating The Movie Database (TMDB) API with React Native TV applications. This skill activates when users ask about:\n\n- Fetching movie or TV show data\n- Displaying poster and backdrop images\n- Implementing search functionality\n- Getting trending content\n- Fetching video trailers\n- TMDB authentication and API keys\n- Rate limiting and optimization\n- TypeScript types for TMDB responses\n\n## Authentication\n\nTMDB offers two equivalent authentication methods:\n\n### API Key (Query Parameter)\n\n```typescript\nconst url = `https://api.themoviedb.org/3/movie/550?api_key=${API_KEY}`;\n```\n\n### Bearer Token (Header) - Recommended\n\n```typescript\nconst headers = {\n  ''Authorization'': `Bearer ${ACCESS_TOKEN}`,\n  ''Accept'': ''application/json''\n};\n```\n\n**Both tokens are generated in your TMDB account settings.** Bearer token is recommended for production as credentials aren''t visible in URLs.\n\n## Image URL Construction\n\n**Base URL:** `https://image.tmdb.org/t/p/`\n\n**Official Sizes (use these for CDN caching):**\n\n| Type | Available Sizes |\n|------|-----------------|\n| Poster | w92, w154, w185, w342, w500, w780, original |\n| Backdrop | w300, w780, w1280, original |\n| Logo | w45, w92, w154, w185, w300, w500, original |\n| Profile | w45, w185, h632, original |\n\n**Image URL Helper:**\n\n```typescript\nconst TMDB_IMAGE_BASE = ''https://image.tmdb.org/t/p/'';\n\ntype PosterSize = ''w92'' | ''w154'' | ''w185'' | ''w342'' | ''w500'' | ''w780'' | ''original'';\ntype BackdropSize = ''w300'' | ''w780'' | ''w1280'' | ''original'';\n\nexport function getPosterUrl(path: string | null, size: PosterSize = ''w500''): string | null {\n  if (!path) return null;\n  return `${TMDB_IMAGE_BASE}${size}${path}`;\n}\n\nexport function getBackdropUrl(path: string | null, size: BackdropSize = ''w1280''): string | null {\n  if (!path) return null;\n  return `${TMDB_IMAGE_BASE}${size}${path}`;\n}\n```\n\n**Important:** Only use official sizes - non-standard sizes bypass CDN caching and are 10-50x slower.\n\n## Essential Endpoints\n\n### Trending Content\n\n```\nGET /trending/{media_type}/{time_window}\n\nmedia_type: movie, tv, person, all\ntime_window: day, week\n```\n\n### Discovery\n\n```\nGET /discover/movie\nGET /discover/tv\n\nParameters:\n- sort_by: popularity.desc, vote_average.desc, release_date.desc\n- with_genres: 28,12 (AND) or 28|12 (OR)\n- page: pagination (20 items per page)\n```\n\n### Search\n\n```\nGET /search/movie?query={term}\nGET /search/tv?query={term}\nGET /search/multi?query={term}  // Movies, TV, and people\n```\n\n### Details with Related Data\n\n```\nGET /movie/{id}?append_to_response=videos,credits,images\nGET /tv/{id}?append_to_response=videos,credits,images,season/1,season/2\n```\n\n**append_to_response** combines multiple requests into one (doesn''t count toward rate limits).\n\n### Genres\n\n```\nGET /genre/movie/list\nGET /genre/tv/list\n```\n\n## TypeScript Interfaces\n\n```typescript\n// Base types\nexport interface Movie {\n  id: number;\n  title: string;\n  overview: string;\n  poster_path: string | null;\n  backdrop_path: string | null;\n  release_date: string;\n  vote_average: number;\n  vote_count: number;\n  popularity: number;\n  genre_ids?: number[];\n  adult: boolean;\n}\n\nexport interface TVShow {\n  id: number;\n  name: string;\n  overview: string;\n  poster_path: string | null;\n  backdrop_path: string | null;\n  first_air_date: string;\n  vote_average: number;\n  vote_count: number;\n  popularity: number;\n  genre_ids?: number[];\n  origin_country: string[];\n}\n\nexport interface TMDBResponse<T> {\n  page: number;\n  results: T[];\n  total_pages: number;\n  total_results: number;\n}\n\n// Detail types\nexport interface MovieDetails extends Movie {\n  budget: number;\n  revenue: number;\n  runtime: number;\n  status: string;\n  tagline: string;\n  genres: Genre[];\n  production_companies: ProductionCompany[];\n  credits?: Credits;\n  videos?: { results: Video[] };\n  images?: Images;\n}\n\nexport interface TVDetails extends TVShow {\n  number_of_episodes: number;\n  number_of_seasons: number;\n  episode_run_time: number[];\n  seasons: Season[];\n  networks: Network[];\n  status: string;\n  credits?: Credits;\n  videos?: { results: Video[] };\n}\n\nexport interface Genre {\n  id: number;\n  name: string;\n}\n\nexport interface Video {\n  id: string;\n  key: string;           // YouTube/Vimeo video ID\n  name: string;\n  site: ''YouTube'' | ''Vimeo'';\n  size: number;\n  type: ''Trailer'' | ''Teaser'' | ''Clip'' | ''Featurette'' | ''Behind the Scenes'';\n  official: boolean;\n  published_at: string;\n}\n\nexport interface Credits {\n  cast: CastMember[];\n  crew: CrewMember[];\n}\n\nexport interface CastMember {\n  id: number;\n  name: string;\n  character: string;\n  profile_path: string | null;\n  order: number;\n}\n\nexport interface CrewMember {\n  id: number;\n  name: string;\n  job: string;\n  department: string;\n  profile_path: string | null;\n}\n\nexport interface Season {\n  id: number;\n  season_number: number;\n  name: string;\n  overview: string;\n  air_date: string;\n  episode_count: number;\n  poster_path: string | null;\n}\n\nexport interface Episode {\n  id: number;\n  name: string;\n  overview: string;\n  episode_number: number;\n  season_number: number;\n  still_path: string | null;\n  air_date: string;\n  runtime: number;\n  vote_average: number;\n}\n```\n\n## Axios Client Setup\n\n```typescript\nimport axios from ''axios'';\n\nconst TMDB_BASE_URL = ''https://api.themoviedb.org/3'';\n\nconst tmdbClient = axios.create({\n  baseURL: TMDB_BASE_URL,\n  timeout: 10000,\n  headers: {\n    ''Accept'': ''application/json'',\n    ''Authorization'': `Bearer ${process.env.TMDB_ACCESS_TOKEN}`,\n  },\n});\n\n// Add default language\ntmdbClient.interceptors.request.use((config) => {\n  config.params = {\n    ...config.params,\n    language: ''en-US'',\n  };\n  return config;\n});\n\n// Error handling\ntmdbClient.interceptors.response.use(\n  (response) => response,\n  (error) => {\n    if (error.response?.status === 429) {\n      // Rate limited - implement retry with backoff\n      console.warn(''TMDB rate limit hit'');\n    }\n    return Promise.reject(error);\n  }\n);\n\nexport default tmdbClient;\n```\n\n## React Native Hooks\n\n### useTrending Hook\n\n```typescript\nimport { useState, useEffect } from ''react'';\nimport tmdbClient from ''../services/tmdbClient'';\nimport { Movie, TVShow, TMDBResponse } from ''../types/tmdb'';\n\ntype MediaType = ''movie'' | ''tv'' | ''all'';\ntype TimeWindow = ''day'' | ''week'';\n\nexport function useTrending<T extends Movie | TVShow>(\n  mediaType: MediaType = ''movie'',\n  timeWindow: TimeWindow = ''week''\n) {\n  const [data, setData] = useState<T[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<Error | null>(null);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    async function fetchTrending() {\n      try {\n        setLoading(true);\n        const response = await tmdbClient.get<TMDBResponse<T>>(\n          `/trending/${mediaType}/${timeWindow}`\n        );\n        if (!cancelled) {\n          setData(response.data.results);\n        }\n      } catch (err) {\n        if (!cancelled) {\n          setError(err as Error);\n        }\n      } finally {\n        if (!cancelled) {\n          setLoading(false);\n        }\n      }\n    }\n\n    fetchTrending();\n    return () => { cancelled = true; };\n  }, [mediaType, timeWindow]);\n\n  return { data, loading, error };\n}\n```\n\n### useMovieDetails Hook\n\n```typescript\nexport function useMovieDetails(movieId: number) {\n  const [movie, setMovie] = useState<MovieDetails | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<Error | null>(null);\n\n  useEffect(() => {\n    let cancelled = false;\n\n    async function fetchDetails() {\n      try {\n        setLoading(true);\n        const response = await tmdbClient.get<MovieDetails>(\n          `/movie/${movieId}`,\n          {\n            params: {\n              append_to_response: ''videos,credits,images'',\n            },\n          }\n        );\n        if (!cancelled) {\n          setMovie(response.data);\n        }\n      } catch (err) {\n        if (!cancelled) {\n          setError(err as Error);\n        }\n      } finally {\n        if (!cancelled) {\n          setLoading(false);\n        }\n      }\n    }\n\n    if (movieId) {\n      fetchDetails();\n    }\n    return () => { cancelled = true; };\n  }, [movieId]);\n\n  return { movie, loading, error };\n}\n```\n\n### useSearch Hook with Debounce\n\n```typescript\nimport { useState, useCallback, useRef } from ''react'';\nimport { debounce } from ''lodash'';\n\nexport function useSearch() {\n  const [results, setResults] = useState<(Movie | TVShow)[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<Error | null>(null);\n\n  const searchRef = useRef(\n    debounce(async (query: string) => {\n      if (!query.trim()) {\n        setResults([]);\n        return;\n      }\n\n      try {\n        setLoading(true);\n        const response = await tmdbClient.get(''/search/multi'', {\n          params: { query },\n        });\n        setResults(response.data.results.filter(\n          (item: any) => item.media_type === ''movie'' || item.media_type === ''tv''\n        ));\n      } catch (err) {\n        setError(err as Error);\n      } finally {\n        setLoading(false);\n      }\n    }, 300)\n  );\n\n  const search = useCallback((query: string) => {\n    searchRef.current(query);\n  }, []);\n\n  return { results, loading, error, search };\n}\n```\n\n## Rate Limiting\n\n**Current Limits:**\n- 50 requests per second\n- 20 simultaneous connections per IP\n\n**Optimization Strategies:**\n\n1. **Use append_to_response** - Combine requests (free, no rate limit impact)\n2. **Implement caching** - Cache responses with TTL\n3. **Debounce searches** - Wait 300ms after user stops typing\n4. **Batch requests** - Group API calls with small delays\n\n## Common Pitfalls & Solutions\n\n| Pitfall | Solution |\n|---------|----------|\n| API key in client-side code | Use backend proxy in production |\n| Slow image loading | Only use official sizes (w342, w500, w780) |\n| Missing images crash app | Always check for null: `poster_path && getPosterUrl(poster_path)` |\n| Wrong video displayed | Filter: `videos.filter(v => v.type === ''Trailer'' && v.official)` |\n| Rate limit errors | Implement exponential backoff, use append_to_response |\n| State update on unmounted component | Use cleanup flag in useEffect |\n| Search fires too often | Debounce search input (300-500ms) |\n| Can''t get all TV episodes | Use `append_to_response=season/1,season/2,...` (max 20) |\n\n## Error Codes\n\n| Code | Meaning | Action |\n|------|---------|--------|\n| 7 | Invalid API key | Check for typos, verify key in settings |\n| 10 | Suspended API key | Contact TMDB support |\n| 34 | Resource not found | May be temporary - retry once |\n| 429 | Rate limit exceeded | Implement backoff, reduce request rate |\n\n## Video URL Construction\n\n```typescript\nfunction getVideoUrl(video: Video): string {\n  if (video.site === ''YouTube'') {\n    return `https://www.youtube.com/watch?v=${video.key}`;\n  }\n  if (video.site === ''Vimeo'') {\n    return `https://vimeo.com/${video.key}`;\n  }\n  return '''';\n}\n\n// Get official trailer\nfunction getOfficialTrailer(videos: Video[]): Video | undefined {\n  return videos.find(v => v.type === ''Trailer'' && v.official)\n      || videos.find(v => v.type === ''Trailer'')\n      || videos[0];\n}\n```\n\n## Resources\n\n- [TMDB API Docs](https://developer.themoviedb.org/docs/getting-started)\n- [TMDB API Reference](https://developer.themoviedb.org/reference/getting-started)\n- [Image Configuration](https://developer.themoviedb.org/docs/image-basics)\n- [Rate Limiting](https://developer.themoviedb.org/docs/rate-limiting)\n"},"lastSynced":"2026-03-08T02:03:47.556Z","agentAnalysis":{"suitability":{"en":"Ideal for Media Integration Agents needing seamless access to movie and TV show data via The Movie Database API","zh":"适用于需要通过The Movie Database API无缝访问电影和电视节目数据的媒体集成代理","ja":"The Movie Database APIを介して映画やテレビ番組のデータにシームレスにアクセスする必要があるメディア統合エージェントに最適","ko":"The Movie Database API를 통해 영화 및 TV 프로그램 데이터에无缝하게 액세스해야 하는 미디어 통합 에이전트에 적합","es":"Ideal para Agentes de Integración de Medios que necesitan acceso sin problemas a datos de películas y programas de televisión a través de The Movie Database API","fr":"Idéal pour les agents d''intégration des médias nécessitant un accès sans interruption aux données de films et d''émissions de télévision via The Movie Database API","de":"Ideal für Media-Integration-Agents, die einen nahtlosen Zugriff auf Film- und Fernsehsendungendaten über The Movie Database API benötigen","pt":"Ideal para Agentes de Integração de Mídia que necessitam de acesso sem interrupção a dados de filmes e programas de TV via The Movie Database API","ru":"Идеально для агентов интеграции СМИ, которым необходим бесперебойный доступ к данным о фильмах и телешоу через The Movie Database API","ar":"مثالي لعميل التكامل الإعلامي الذي يحتاج إلى الوصول بدون انقطاع إلى بيانات الأفلام والمسلسلات التلفزيونية عبر واجهة برمجة تطبيقات قاعدة بيانات الأفلام"},"recommendation":{"en":"Empowers agents to fetch movie and TV show data, display poster and backdrop images, and implement search functionality using React Native TV and TMDB API, while handling authentication, rate limiting, and optimization","zh":"赋予代理获取电影和电视节目数据、显示海报和背景图像以及使用React Native TV和TMDB API实现搜索功能的能力，同时处理身份验证、速率限制和优化","ja":"エージェントが映画やテレビ番組のデータを取得し、ポスターと背景画像を表示し、React Native TVとTMDB APIを使用して検索機能を実装する能力を付与し、同時に認証、レート制限、最適化を処理","ko":"에이전트가 영화 및 TV 프로그램 데이터를 가져오고 포스터 및 배경 이미지를 표시하고 React Native TV 및 TMDB API를 사용하여 검색 기능을 구현할 수 있는 기능을 제공하며 동시에 인증, 비율 제한 및 최적화를 처리","es":"Permite a los agentes recuperar datos de películas y programas de televisión, mostrar imágenes de póster y fondos, e implementar funcionalidad de búsqueda utilizando React Native TV y TMDB API, mientras maneja la autenticación, la limitación de velocidad y la optimización","fr":"Permet aux agents de récupérer des données de films et d''émissions de télévision, d''afficher des images de posters et de fonds, et de mettre en œuvre une fonctionnalité de recherche en utilisant React Native TV et TMDB API, tout en gérant l''authentification, la limitation de débit et l''optimisation","de":"Ermächtigt Agenten, Film- und Fernsehsendungendaten abzurufen, Poster- und Hintergrundbilder anzuzeigen und Suchfunktionen mit React Native TV und TMDB API zu implementieren, während Authentifizierung, Rate Limiting und Optimierung gehandhabt werden","pt":"Habilita os agentes a buscar dados de filmes e programas de TV, exibir imagens de pôster e fundo, e implementar funcionalidade de busca usando React Native TV e TMDB API, lidando com autenticação, limitação de taxa e otimização","ru":"Позволяет агентам получать данные о фильмах и телешоу, отображать изображения постеров и фонов, и реализовывать функциональность поиска с помощью React Native TV и TMDB API, а также обрабатывать аутентификацию, ограничение скорости и оптимизацию","ar":"يمنح العملاء khảية استرجاع بيانات الأفلام والمسلسلات التلفزيونية، و عرض صور البوسترات والخلفيات، وتنفيذ وظائف البحث باستخدام React Native TV و واجهة برمجة تطبيقات قاعدة بيانات الأفلام، مع معالجة المصادقة، وتقييد معدل التحديث، و Optimization"},"useCases":{"en":["Fetching trending movie and TV show content","Implementing search functionality with TMDB API","Displaying video trailers and poster images in React Native TV applications"],"zh":["获取流行的电影和电视节目内容","使用TMDB API实现搜索功能","在React Native TV应用中显示视频预告片和海报图像"],"ja":["人気の映画やテレビ番組のコンテンツを取得","TMDB APIを使用した検索機能の実装","React Native TVアプリケーションでビデオトレーラーとポスター画像を表示"],"ko":["트렌드하는 영화 및 TV 프로그램 콘텐츠 가져오기","TMDB API를 사용한 검색 기능 구현","React Native TV 애플리케이션에서 비디오 예고편 및 포스터 이미지 표시"],"es":["Recuperación de contenido de películas y programas de televisión tendencias","Implementación de funcionalidad de búsqueda con TMDB API","Visualización de tráileres de video y imágenes de póster en aplicaciones de React Native TV"],"fr":["Récupération de contenu de films et d''émissions de télévision tendance","Mise en œuvre de la fonctionnalité de recherche avec TMDB API","Affichage de bandes-annonces de vidéo et d''images de posters dans des applications React Native TV"],"de":["Abruf von Trend-Inhalten für Filme und Fernsehsendungen","Implementierung der Suchfunktion mit TMDB API","Anzeige von Video-Trailern und Poster-Bildern in React Native TV-Anwendungen"],"pt":["Buscar conteúdo de filmes e programas de TV em tendência","Implementar funcionalidade de busca com TMDB API","Exibir trailers de vídeo e imagens de pôster em aplicações React Native TV"],"ru":["Получение трендового контента фильмов и телешоу","Реализация функциональности поиска с помощью TMDB API","Отображение видео-трейлеров и изображений постеров в приложениях React Native TV"],"ar":["استرجاع المحتوى الشائع من الأفلام والمسلسلات التلفزيونية","تنفيذ وظائف البحث مع واجهة برمجة تطبيقات قاعدة بيانات الأفلام","عرض مقاطع الفيديو والصور في تطبيقات React Native TV"]},"limitations":{"en":["Requires TMDB API key","Rate limiting applies to API requests","Specific to React Native TV applications"],"zh":["需要TMDB API密钥","API请求有速率限制","仅适用于React Native TV应用"],"ja":["TMDB APIキーが必要","APIリクエストにレート制限が適用される","React Native TVアプリケーションのみに適用"],"ko":["TMDB API 키가 필요","API 요청에 비율 제한이 적용","React Native TV 애플리케이션 전용"],"es":["Requiere clave de API de TMDB","La limitación de velocidad se aplica a las solicitudes de API","Específico para aplicaciones de React Native TV"],"fr":["Nécessite une clé d''API TMDB","La limitation de débit s''applique aux requêtes d''API","Spécifique aux applications React Native TV"],"de":["Erfordert TMDB API-Schlüssel","Rate Limiting gilt für API-Anfragen","Spezifisch für React Native TV-Anwendungen"],"pt":["Requer chave de API do TMDB","A limitação de taxa se aplica a solicitações de API","Específico para aplicações React Native TV"],"ru":["Требуется ключ API TMDB","Ограничение скорости применяется к запросам API","Конкретно для приложений React Native TV"],"ar":["يتطلب مفتاح واجهة برمجة تطبيقات قاعدة بيانات الأفلام","تقييد معدل التحديث ينطبق 