INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('giolaq/Multi-TV-dev-power/tmdb-integration', 'tmdb-integration', 'giolaq', 'Multi-TV-dev-power', 'community', 'tmdb-integration giolaq Multi-TV-dev-power community The tmdb-integration skill enables developers to seamlessly integrate The Movie Database API with React Native TV applications, providing access to movie and TV show data, images, and more. 本文介绍如何将TMDB API集成到React Native TV应用中，实现电影和电视节目数据的获取、海报和背景图像的显示等功能 この記事では、TMDB APIをReact Native TVアプリケーションに統合して、映画やテレビ番組のデータを取得したり、ポスターとバックグラウンドイメージを表示したりする方法について説明します 이 문서는 React Native TV 애플리케이션에 TMDB API를 통합하여 영화와 TV 프로그램 데이터를 가져오고, 포스터와 배경 이미지를 표시하는 방법에 대해 설명합니다 Integra la API de TMDB con aplicaciones de React Native TV para obtener datos de películas y programas de TV Intégrez l''API TMDB avec les applications React Native TV pour obtenir des données de films et de séries TV Integrieren Sie die TMDB-API mit React Native TV-Anwendungen, um Daten von Filmen und Fernsehsendungen zu erhalten Integre a API do The Movie Database com aplicações React Native TV para obter dados de filmes e séries, exibir imagens e implementar funcionalidades de busca ИИ Агент для интеграции с TMDB API позволяет получать данные фильмов и сериалов, отображать постеры и реализовывать функции поиска دمج واجهة برمجة تطبيقات قاعدة بيانات الأفلام مع تطبيقات React Native TV لاسترجاع بيانات الأفلام والمسلسلات و عرض الصور و تنفيذ وظائف البحث how to use tmdb-integration tmdb-integration setup guide react native tv tmdb api tmdb integration alternative tmdb-integration vs themoviedb tmdb-integration install what is tmdb-integration tmdb api optimization typescript types for tmdb TMDB集成 React Native TV 电影数据获取 电视节目数据获取 海报显示 背景图像显示 搜索功能 趋势内容 视频预告片 Fetches movie and TV show data using TMDB API Displays poster and backdrop images in React Native TV apps Implements search functionality for trending content Fetches video trailers and handles TMDB authentication Optimizes API usage with rate limiting and TypeScript types tmdb-integration is a skill that facilitates the integration of The Movie Database API with React Native TV applications, enabling features like data fetching and image display.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ianphil/prism/quick-plan', 'community', 'ianphil', 'prism', 'ianphil/prism', 'quick-plan', 0, 0, 54, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:50.713Z', '1affd3a02b6675858510d55896ae6c340c451f140e8d80c53b5483a689c609b7', '{"id":"ianphil/prism/quick-plan","name":"quick-plan","description":{"en":"The quick-plan skill creates lightweight plan documents for capturing ideas and scoping small-to-medium features. It generates plan documents in the backlog/plans/ directory using a standard template.","zh":"快速计划技能创建轻量级计划文档，适用于捕捉想法和范围小至中型功能。使用标准模板在backlog/plans/中创建文档","ja":"クイックプランスキルは、アイデアの 捕捉と小規模〜中規模の機能の範囲に適した軽量プラン文書を作成します。標準テンプレートを使用してbacklog/plans/に文書を作成します","ko":"퀵플랜 스킬은 아이디어 캡처와 소형〜중형 기능 범위에 적합한 경량 계획 문서를 생성합니다. 표준 템플릿을 사용하여 backlog/plans/에 문서를 생성합니다","es":"Quick-plan es una habilidad de AI Agent que crea documentos de plan ligeros para capturar ideas y scoped de características pequeñas a medianas.","fr":"Quick-plan est une compétence d''Outil IA qui crée des documents de plan légers pour capturer des idées et scoped de fonctionnalités petites à moyennes.","de":"Quick-plan ist eine Fähigkeit von KI-Tool, die leichte Plänedokumente erstellt, um Ideen und Scoped von kleinen bis mittleren Funktionen zu erfassen.","pt":"O Quick-Plan é uma ferramenta de IA que cria planos leves e concisos em backlog/plans/, ideal para capturar ideias rapidamente","ru":"Быстрый План - это инструмент ИИ, который создает легковесные и краткие планы в backlog/plans/, подходящий для быстрого захвата идей","ar":"خطة سريعة هي أداة ذكاء اصطناعي التي تخلق خططًا خفيفةً وموجزة في backlog/plans/، مثالية لالتقاط الأفكار بسرعة"},"seo":{"title":{"en":"quick-plan: Lightweight Plan Document Creation | AI Agent...","zh":"快速计划设置指南 - 为您的项目创建轻量级计划文档","ja":"クイックプラン設定ガイド - プロジェクトのための軽量プラン文書を作成する","ko":"퀵플랜 설정 가이드 - 프로젝트를 위한 경량 계획 문서 생성","es":"Guía de configuración de quick-plan: Creación de planes l...","fr":"Guide d''installation de quick-plan: Création de plans lég...","de":"Einrichtungsleitfaden für quick-plan: Erstellung von leic...","pt":"Guia de Configuração do Quick-Plan: Crie Planos Leves com...","ru":"Настройка Быстрого Плана: Создание Легковесных Планов с п...","ar":"دليل إعداد خطة سريعة: إنشاء مستندات خطة خفيفة باستخدام أد..."},"description":{"en":"Discover how quick-plan generates concise plan documents in backlog/plans/ using standard templates. Learn how to create and use quick-plan for scoping small...","zh":"使用快速计划技能，快速创建项目计划文档。适用于捕捉想法、范围小至中型功能和创建起始点","ja":"クイックプランスキルを使用して、プロジェクト計画文書を迅速に作成します。アイデアの 捕捉、 小規模〜中規模の機能の範囲、開始点の作成に適しています","ko":"퀵플랜 스킬을 사용하여 프로젝트 계획 문서를 빠르게 생성합니다. 아이디어 캡처, 소형〜중형 기능 범위, 시작 지점 생성에 적합합니다","es":"Aprende a crear planes ligeros con quick-plan, una habilidad de AI Agent para desarrolladores. Descubre su funcionamiento y beneficios.","fr":"Découvrez comment créer des plans légers avec quick-plan, une compétence d''Outil IA pour les développeurs. Comprenez son fonctionnement et ses avantages.","de":"Erfahren Sie, wie Sie leichte Pläne mit quick-plan erstellen, einer Fähigkeit von KI-Tool für Entwickler. Entdecken Sie deren Funktionsweise und Vorteile.","pt":"Aprenda a criar planos leves e eficazes com o Quick-Plan, uma ferramenta de IA para desenvolvedores","ru":"Узнайте, как создать легковесные и эффективные планы с помощью Быстрого Плана, инструмента ИИ для разработчиков","ar":"تعلم كيفية إنشاء خطط خفيفة وفعالة مع خطة سريعة، أداة ذكاء اصطناعي للdevelopers"},"definition":{"en":"quick-plan is a skill that creates concise plan documents in a standardized format for rapid idea capture and feature scoping.","zh":"快速计划是创建轻量级计划文档的技能，使用标准模板在backlog/plans/中创建文档","ja":"クイックプランは、標準テンプレートを使用してbacklog/plans/に文書を作成する軽量プラン文書を作成するスキルです","ko":"퀵플랜은 표준 템플릿을 사용하여 backlog/plans/에 문서를 생성하는 경량 계획 문서를 생성하는 스킬입니다","es":"Quick-plan es una habilidad de AI Agent que crea planes ligeros para desarrolladores.","fr":"Quick-plan est une compétence d''Outil IA qui crée des plans légers pour les développeurs.","de":"Quick-plan ist eine Fähigkeit von KI-Tool, die leichte Pläne für Entwickler erstellt.","pt":"O Quick-Plan é uma ferramenta de IA que cria planos leves e concisos para desenvolvedores","ru":"Быстрый План - это инструмент ИИ, предназначенный для создания легковесных и кратких планов","ar":"خطة سريعة هي أداة ذكاء اصطناعي لإنشاء خطط خفيفة وموجزة"},"features":{"en":["Generates plan documents in backlog/plans/ directory","Uses standard template for consistency","Suitable for capturing ideas quickly before context is lost","Ideal for scoping small-to-medium features","Creates starting points for later /planner expansion","Supports creation of filenames for plan documents"],"zh":["创建轻量级计划文档","使用标准模板","适用于捕捉想法和范围小至中型功能","在backlog/plans/中创建文档","快速创建计划文档","适用于创建起始点"],"ja":["軽量プラン文書の作成","標準テンプレートの使用","アイデアの 捕捉と小規模〜中規模の機能の範囲に適する","backlog/plans/に文書を作成","計画文書の迅速作成","開始点の作成に適する"],"ko":["경량 계획 문서 생성","표준 템플릿 사용","아이디어 캡처와 소형〜중형 기능 범위에 적합","backlog/plans/에 문서 생성","계획 문서 빠른 생성","시작 지점 생성에 적합"],"es":["Crea documentos de plan ligeros en `backlog/plans/`","Utiliza una plantilla estándar para la creación de planes","Ideal para capturar ideas rápidamente antes de perder el contexto","Se utiliza para scopar características pequeñas a medianas","Permite la creación de puntos de partida para una posterior expansión con `/planner`"],"fr":["Crée des documents de plan légers dans `backlog/plans/`","Utilise un modèle standard pour la création de plans","Idéal pour capturer des idées rapidement avant de perdre le contexte","Est utilisé pour scoped de fonctionnalités petites à moyennes","Permet la création de points de départ pour une expansion ultérieure avec `/planner`"],"de":["Erstellt leichte Plänedokumente in `backlog/plans/`","Verwendet eine Standardvorlage für die Erstellung von Plänen","Ideal für die schnelle Erfassung von Ideen, bevor der Kontext verloren geht","Wird verwendet, um Funktionen von kleinen bis mittleren Umfang zu scopen","Ermöglicht die Erstellung von Startpunkten für eine spätere Erweiterung mit `/planner`"],"pt":["Criação de planos leves em backlog/plans/","Uso de modelo de plano padrão","Ideal para capturar ideias rapidamente","Suporta pequenas e médias funcionalidades","Integração com /planner para expansão posterior"],"ru":["Создание легковесных планов в backlog/plans/","Использование стандартного шаблона плана","Подходит для быстрого захвата идей","Поддерживает небольшие и средние функциональности","Интеграция с /planner для дальнейшего расширения"],"ar":["إنشاء خطط خفيفة في backlog/plans/","استخدام نموذج خطة قياسي","مثالية لالتقاط الأفكار بسرعة","تدعم الميزات الصغيرة والمتوسطة","التكامل مع /planner للتوسعة اللاحقة"]},"keywords":{"en":["how to use quick-plan","what is quick-plan","quick-plan alternative","quick-plan vs planner","quick-plan setup guide","quick-plan install","creating plan documents with quick-plan","using quick-plan for feature scoping","quick-plan for idea capture"],"zh":["快速计划","轻量级计划文档","标准模板","backlog/plans/","捕捉想法","范围小至中型功能","创建起始点","AI工具","项目管理"],"ja":["クイックプラン","軽量プラン文書","標準テンプレート","backlog/plans/","アイデアの 捕捉","小規模〜中規模の機能の範囲","開始点の作成","AIエージェント","プロジェクト管理"],"ko":["퀵플랜","경량 계획 문서","표준 템플릿","backlog/plans/","아이디어 캡처","소형〜중형 기능 범위","시작 지점 생성","AI工具","프로젝트 관리"],"es":["quick-plan","AI Agent","planes ligeros","desarrollo de software","creación de planes","scoped de características","plantilla estándar","backlog","planner"],"fr":["quick-plan","Outil IA","plans légers","développement de logiciels","création de plans","scoped de fonctionnalités","modèle standard","backlog","planner"],"de":["quick-plan","KI-Tool","leichte Pläne","Softwareentwicklung","Erstellung von Plänen","Scoped von Funktionen","Standardvorlage","Backlog","Planner"],"pt":["ferramentas de ia para desenvolvedores","criação de planos leves","backlog plans","modelo de plano padrão","capturar ideias rapidamente","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["инструменты ии для разработчиков","создание легковесных планов","backlog plans","стандартный шаблон плана","быстрый захват идей","разработка программного обеспечения","инструменты разработки"],"ar":["أدوات الذكاء الاصطناعي للdevelopers","إنشاء خطط خفيفة","backlog plans","نموذج خطة قياسي","التقاط الأفكار بسرعة","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ianphil","repo":"prism","repoPath":"ianphil/prism","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.351Z","topics":[],"category":"community","skillMd":{"name":"quick-plan","description":"This skill should be used when the user asks to create a quick plan, draft a plan, capture this idea, plan this feature, or wants a lightweight plan without full feature planning. Creates concise plans in backlog/plans/ for later expansion.","bodyPreview":"# Quick Plan\n\nCreate a lightweight plan document for: **$ARGUMENTS**\n\n## Overview\n\nThis skill creates concise plan documents in `backlog/plans/` using the standard template. Suitable for:\n- Capturing ideas quickly before context is lost\n- Scoping small-to-medium features\n- Creating starting points for later `/planner` expansion\n\nFor complex features requiring full analysis, spec, research, and TDD task breakdown, use `/planner` instead.\n\n## Workflow\n\n### Step 1: Generate Filename\n\nCreate filenam","body":"# Quick Plan\n\nCreate a lightweight plan document for: **$ARGUMENTS**\n\n## Overview\n\nThis skill creates concise plan documents in `backlog/plans/` using the standard template. Suitable for:\n- Capturing ideas quickly before context is lost\n- Scoping small-to-medium features\n- Creating starting points for later `/planner` expansion\n\nFor complex features requiring full analysis, spec, research, and TDD task breakdown, use `/planner` instead.\n\n## Workflow\n\n### Step 1: Generate Filename\n\nCreate filename using today''s date and a slug derived from the input:\n- Format: `YYYYMMDD-short-description.md`\n- Example: `20260127-add-user-authentication.md`\n\n### Step 2: Gather Context (Optional)\n\nWhen input references existing code or systems:\n- Briefly scan relevant files to understand current state\n- Note obvious constraints or dependencies\n\nLimit context gathering to under 2 minutes. Extensive research indicates `/planner` may be more appropriate.\n\n### Step 3: Create Plan\n\nCreate the plan file at `backlog/plans/{filename}`:\n\n```markdown\n---\ntitle: \"{Descriptive title}\"\nstatus: open\npriority: {low|medium|high|critical}\ncreated: {YYYY-MM-DD}\n---\n\n# {Plan Title}\n\n## Summary\n\n{1-2 sentences describing what this plan achieves}\n\n## Motivation\n\n{Why is this needed? What problem does it solve? 2-3 sentences.}\n\n## Proposal\n\n### Goals\n\n- {Primary goal}\n- {Secondary goal if applicable}\n\n### Non-Goals\n\n- {What this explicitly does NOT cover}\n\n## Design\n\n{High-level approach in 3-5 sentences or bullet points. Include key technical decisions if obvious.}\n\n## Tasks\n\n- [ ] {Task 1}\n- [ ] {Task 2}\n- [ ] {Task 3}\n\n## Open Questions\n\n- {Any uncertainties requiring resolution}\n```\n\n### Step 4: Output Summary\n\nAfter creating the plan:\n\n```\nCreated: backlog/plans/{filename}\n\n{title}\nPriority: {priority}\nTasks: {count}\n\nNext steps:\n- Review and refine the plan\n- Adjust priority if needed\n- Expand with /planner if complexity warrants\n- Or start implementation directly for simple plans\n```\n\n## Guidelines\n\n| Guideline | Detail |\n|-----------|--------|\n| Concise | Quick capture, not exhaustive planning |\n| Priority inference | Blocking issues = high, nice-to-have = low |\n| Task count | 3-7 tasks; more than 7 suggests `/planner` |\n| Optional sections | Omit \"Open Questions\" if none exist |\n| Time limit | Context gathering under 2 minutes |\n"},"lastSynced":"2026-03-08T02:03:50.713Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring rapid feature scoping and planning capabilities.","zh":"适用于需要快速特性范围和规划能力的开发代理","ja":"急速な機能のスコープと計画能力を必要とする開発エージェントに最適","ko":"신속한 기능 범위 및 계획 기능을 필요로 하는 개발 에이전트에 적합","es":"Ideal para agentes de desarrollo que requieren capacidades de planificación y definición de características rápidas.","fr":"Idéal pour les agents de développement nécessitant des capacités de planification et de définition de fonctionnalités rapides.","de":"Ideal für Entwicklungsmittel, die eine schnelle Funktionsdefinition und Planungsfähigkeit erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem capacidades rápidas de definição e planejamento de recursos.","ru":"Идеально подходит для агентов разработки, требующих быстрого определения и планирования функций.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى قدرات التخطيط والمواصفات السريعة"},"recommendation":{"en":"Empowers agents to generate concise plan documents in Markdown format, utilizing a standard template for capturing ideas and scoping small-to-medium features, while storing them in the `backlog/plans/` directory.","zh":"赋予代理生成Markdown格式的简洁计划文档的能力，利用标准模板捕获想法和规划小至中型功能，并将其存储在`backlog/plans/`目录中","ja":"エージェントがMarkdown形式の簡潔な計画書を生成する機能を提供し、小規模から中規模の機能のアイデアを標準テンプレートを使用して捕捉し、`backlog/plans/`ディレクトリに保存する","ko":"에이전트가 Markdown 형식의 간결한 계획 문서를 생성할 수 있는 기능을 제공하여 작은 기능부터 중형 기능까지 아이디어를 표준 템플릿을 사용하여捕获하고 `backlog/plans/` 디렉토리에 저장","es":"Habilita a los agentes a generar documentos de planificación concisos en formato Markdown, utilizando una plantilla estándar para capturar ideas y definir características pequeñas y medianas, mientras las almacena en el directorio `backlog/plans/`.","fr":"Permet aux agents de générer des documents de planification concis au format Markdown, en utilisant un modèle standard pour capturer les idées et définir les fonctionnalités petites et moyennes, tout en les stockant dans le répertoire `backlog/plans/`.","de":"Ermöglicht es den Agenten, knappe Planungsdokumente im Markdown-Format zu erstellen, indem sie eine Standardvorlage verwenden, um Ideen zu erfassen und kleine bis mittelgroße Funktionen zu definieren, während sie diese im Verzeichnis `backlog/plans/` speichern.","pt":"Habilita os agentes a gerar documentos de plano concisos no formato Markdown, utilizando um modelo padrão para capturar ideias e definir recursos de pequeno a médio porte, armazenando-os no diretório `backlog/plans/`.","ru":"Позволяет агентам генерировать краткие планы документов в формате Markdown, используя стандартный шаблон для захвата идей и определения небольших и средних функций, сохраняя их в директории `backlog/plans/`.","ar":"يمنح الوكلاء إمكانية إنشاء مستندات خطة مُختصرة في تنسيق Markdown، باستخدام قوالب معيارية لالتقاط الأفكار وتحديد الميزات الصغيرة والمتوسطة، مع تخزينها في الدليل `backlog/plans/`"},"useCases":{"en":["Capturing ideas quickly before context is lost","Scoping small-to-medium features for agile development","Creating starting points for later expansion with `/planner`"],"zh":["快速捕获想法以免上下文丢失","为敏捷开发规划小至中型功能","使用`/planner`创建后续扩展的起点"],"ja":["コンテキストが失われる前にアイデアをすばやくキャプチャする","アジャイル開発のための小規模から中規模の機能の計画","`/planner`を使用して後続の拡張の起点を作成する"],"ko":["컨텍스트가 손실되기 전에 아이디어를 신속하게 캡처","민첩한 개발을 위한 작은 기능부터 중형 기능까지의 계획","`/planner`를 사용하여 후속 확장의 시작점을 만드는"],"es":["Capturar ideas rápidamente antes de que se pierda el contexto","Definir características pequeñas y medianas para el desarrollo ágil","Crear puntos de partida para una posterior expansión con `/planner`"],"fr":["Capturer des idées rapidement avant que le contexte ne soit perdu","Définir des fonctionnalités petites et moyennes pour le développement agile","Créer des points de départ pour une expansion ultérieure avec `/planner`"],"de":["Ideen schnell erfassen, bevor der Kontext verloren geht","Kleine bis mittelgroße Funktionen für die agile Entwicklung definieren","Startpunkte für eine spätere Erweiterung mit `/planner` erstellen"],"pt":["Capturar ideias rapidamente antes que o contexto seja perdido","Definir recursos de pequeno a médio porte para desenvolvimento ágil","Criar pontos de partida para expansão posterior com `/planner`"],"ru":["Быстро захватить идеи, прежде чем контекст будет потерян","Определить небольшие и средние функции для гибкой разработки","Создать отправные точки для последующего расширения с `/planner`"],"ar":["التقاط الأفكار بسرعة قبل فقدان السياق","تحديد الميزات الصغيرة والمتوسطة لتنمية مُتأصلة","إنشاء نقاط انطلاق للتوسعة اللاحقة مع `/planner`"]},"limitations":{"en":["Limited to small-to-medium feature planning","Not suitable for complex features requiring full analysis, spec, research, and TDD task breakdown","Requires access to the `backlog/plans/` directory for plan document generation"],"zh":["仅限小至中型功能规划","不适合需要完整分析、规格、研究和TDD任务分解的复杂功能","需要访问`backlog/plans/`目录以生成计划文档"],"ja":["小規模から中規模の機能の計画に限定","完全な分析、仕様、調査、TDDタスクの分解が必要な複雑な機能には適さない","`backlog/plans/`ディレクトリへのアクセスが計画書の生成に必要"],"ko":["작은 기능부터 중형 기능까지의 계획으로 제한","완전한 분석, 사양, 연구 및 TDD 작업 분할이 필요한 복잡한 기능에는 적합하지 않음","`backlog/plans/` 디렉토리에 대한 액세스가 계획 문서 생성에 필요"],"es":["Limitado a la planificación de características pequeñas y medianas","No adecuado para características complejas que requieren un análisis completo, especificación, investigación y desglose de tareas TDD","Requiere acceso al directorio `backlog/plans/` para la generación de documentos de planificación"],"fr":["Limité à la planification de fonctionnalités petites et moyennes","Non adapté pour les fonctionnalités complexes nécessitant une analyse complète, spécification, recherche et décomposition de tâches TDD","Nécessite un accès au répertoire `backlog/plans/` pour la génération de documents de planification"],"de":["Begrenzt auf die Planung kleiner bis mittelgroßer Funktionen","Nicht geeignet für komplexe Funktionen, die eine vollständige Analyse, Spezifikation, Forschung und TDD-Aufgabenzerlegung erfordern","Benötigt Zugriff auf das Verzeichnis `backlog/plans/` für die Erstellung von Planungsdokumenten"],"pt":["Limitado ao planejamento de recursos de pequeno a médio porte","Não é adequado para recursos complexos que exigem análise completa, especificação, pesquisa e quebra de tarefas TDD","Exige acesso ao diretório `backlog/plans/` para geração de documentos de plano"],"ru":["Ограничен планированием небольших и средних функций","Не подходит для сложных функций, требующих полного анализа, спецификации, исследования и разбиения задач TDD","Требует доступа к директории `backlog/plans/` для генерации планов документов"],"ar":["محدود بالتخطيط للميزات الصغيرة والمتوسطة","غير مناسب للميزات المعقدة التي تتطلب تحليلًا كاملاً ومواصفات وأبحاث وتنفيذ مهام TDD","يتطلب الوصول إلى الدليل `backlog/plans/` لتوليد مستندات الخطة"]},"version":4},"contentHash":"1affd3a02b6675858510d55896ae6c340c451f140e8d80c53b5483a689c609b7","qualityScore":54}');
