INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ianphil/prism/quick-plan', 'quick-plan', 'ianphil', 'prism', 'community', 'quick-plan ianphil prism community The quick-plan skill creates lightweight plan documents for capturing ideas and scoping small-to-medium features. It generates plan documents in the backlog/plans/ directory using a standard template. 快速计划技能创建轻量级计划文档，适用于捕捉想法和范围小至中型功能。使用标准模板在backlog/plans/中创建文档 クイックプランスキルは、アイデアの 捕捉と小規模〜中規模の機能の範囲に適した軽量プラン文書を作成します。標準テンプレートを使用してbacklog/plans/に文書を作成します 퀵플랜 스킬은 아이디어 캡처와 소형〜중형 기능 범위에 적합한 경량 계획 문서를 생성합니다. 표준 템플릿을 사용하여 backlog/plans/에 문서를 생성합니다 Quick-plan es una habilidad de AI Agent que crea documentos de plan ligeros para capturar ideas y scoped de características pequeñas a medianas. Quick-plan est une compétence d''Outil IA qui crée des documents de plan légers pour capturer des idées et scoped de fonctionnalités petites à moyennes. Quick-plan ist eine Fähigkeit von KI-Tool, die leichte Plänedokumente erstellt, um Ideen und Scoped von kleinen bis mittleren Funktionen zu erfassen. O Quick-Plan é uma ferramenta de IA que cria planos leves e concisos em backlog/plans/, ideal para capturar ideias rapidamente Быстрый План - это инструмент ИИ, который создает легковесные и краткие планы в backlog/plans/, подходящий для быстрого захвата идей خطة سريعة هي أداة ذكاء اصطناعي التي تخلق خططًا خفيفةً وموجزة في backlog/plans/، مثالية لالتقاط الأفكار بسرعة how to use quick-plan what is quick-plan quick-plan alternative quick-plan vs planner quick-plan setup guide quick-plan install creating plan documents with quick-plan using quick-plan for feature scoping quick-plan for idea capture 快速计划 轻量级计划文档 标准模板 backlog/plans/ 捕捉想法 范围小至中型功能 创建起始点 AI工具 项目管理 Generates plan documents in backlog/plans/ directory Uses standard template for consistency Suitable for capturing ideas quickly before context is lost Ideal for scoping small-to-medium features Creates starting points for later /planner expansion Supports creation of filenames for plan documents quick-plan is a skill that creates concise plan documents in a standardized format for rapid idea capture and feature scoping.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('YunosukeYoshino/ImageScraper/tdd-wada-style', 'community', 'YunosukeYoshino', 'ImageScraper', 'YunosukeYoshino/ImageScraper', 'tdd-wada-style', 0, 0, 54, '2026-03-08T01:57:15.359Z', '2026-03-08T02:04:09.928Z', 'a9b88f63a1c795e8858452f02b40a74849ff531785a0ecfea3c5dc1038336a80', '{"id":"YunosukeYoshino/ImageScraper/tdd-wada-style","name":"tdd-wada-style","description":{"en":"The tdd-wada-style skill enables developers to practice high-quality test-driven development based on t.wada''s TDD philosophy. It benefits developers by providing a structured approach to testing and coding.","zh":"tdd-wada-style是一种测试驱动开发方法，强调测试在设计和开发中的重要性。通过遵循3个原则和TDD Cycle，开发者可以提高代码质量和开发效率","ja":"tdd-wada-styleは、テスト駆動開発におけるテストの重要性を強調する開発方法です。3つの原則とTDD Cycleに従うことで、開発者はコードの品質と開発効率を向上させることができます","ko":"tdd-wada-style은 테스트 주도 개발에서 테스트의 중요성을 강조하는 개발 방법입니다. 3가지 원칙과 TDD 주기를 따르면 개발자는 코드의 품질과 개발 효율성을 높일 수 있습니다","es":"El TDD-Wada-Style es un enfoque de desarrollo que se centra en la creación de pruebas automatizadas para garantizar la calidad del código","fr":"Le TDD-Wada-Style est une approche de développement qui se concentre sur la création de tests automatisés pour garantir la qualité du code","de":"Der TDD-Wada-Style ist ein Entwicklungsansatz, der sich auf die Erstellung von automatisierten Tests konzentriert, um die Qualität des Codes zu gewährleisten","pt":"O TDD-Wada-Style é uma abordagem de desenvolvimento baseada nos 3 princípios de t.wada, que visa melhorar a qualidade do código","ru":"TDD-Wada-Style - это подход к разработке, основанный на 3 принципах t.wada, направленный на улучшение качества кода для ИИ Агентов","ar":"TDD-Wada-Style هو نهج للتنمية يعتمد على 3 مبادئ ل t.wada، يهدف إلى تحسين جودة الكود لمنصات الإيجابية الذكية"},"seo":{"title":{"en":"tdd-wada-style: TDD Best Practices for AI Agents | AI Age...","zh":"tdd-wada-style 测试驱动开发最佳实践指南","ja":"tdd-wada-style TDD開発ガイド：高品質なテスト駆動開発を実践する","ko":"tdd-wada-style 테스트 주도 개발 Setup Guide: TDD 철학을 따라라","es":"Guía de implementación de TDD-Wada-Style para desarrollad...","fr":"Mise en place du TDD-Wada-Style pour les développeurs","de":"Einrichtungsleitfaden für TDD-Wada-Style-Entwickler","pt":"Guia de Configuração do TDD-Wada-Style para Desenvolvedores","ru":"Настройка TDD-Wada-Style: Руководство для Разработчиков И...","ar":"دليل إعداد TDD-Wada-Style لمنصة الإيجابية الذكية"},"description":{"en":"Discover the power of tdd-wada-style, a TDD philosophy that ensures high-quality test-driven development. Learn how to implement Red-Green-Refactor cycles an...","zh":"学习tdd-wada-style技能，掌握测试驱动开发的核心思想和3个原则，提高代码质量和开发效率，了解TDD Cycle和Red-Green-Refactor流程","ja":"tdd-wada-styleスキルをマスターし、高品質なテスト駆動開発を実践する。TDDの核心思想と3つの原則、TDD CycleとRed-Green-Refactor流程を学ぶ","ko":"tdd-wada-style 스킬을 배우고 테스트 주도 개발의 핵심 철학과 3가지 원칙을 이해하십시오. TDD 주기와 Red-Green-Refactor 프로세스에 대해 알아보세요","es":"Aprende a aplicar el enfoque TDD-Wada-Style en tus proyectos de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment mettre en œuvre l''approche TDD-Wada-Style dans vos projets de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie den TDD-Wada-Style-Ansatz in Ihren Entwicklungsprojekten anwenden können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a implementar o TDD-Wada-Style em seu projeto com nossa guia passo a passo, incluindo os 3 princípios e o ciclo Red-Green-Refactor","ru":"Узнайте, как настроить TDD-Wada-Style в вашем проекте с нашей пошаговой инструкцией, включая 3 принципа и цикл Red-Green-Refactor для ИИ Агентов","ar":"تعلم كيفية تطبيق TDD-Wada-Style في مشروعك مع دليلنا الخطوة بخطوة، بما في ذلك 3 مبادئ ودورة Red-Green-Refactor لمنصات الإيجابية الذكية"},"definition":{"en":"tdd-wada-style is a test-driven development approach based on t.wada''s philosophy, emphasizing testing as a means to detect mistakes, not just prove functionality.","zh":"tdd-wada-style是一种测试驱动开发方法，基于和田卓人氏的TDD哲学","ja":"tdd-wada-styleは、和田卓人氏のTDD哲学に基づくテスト駆動開発方法です","ko":"tdd-wada-style은 와다 타카토시氏의 TDD 철학을 기반으로 하는 테스트 주도 개발 방법입니다","es":"TDD-Wada-Style es un enfoque de desarrollo que combina principios de TDD con la filosofía de t.wada","fr":"Le TDD-Wada-Style est une approche de développement qui combine les principes du TDD avec la philosophie de t.wada","de":"Der TDD-Wada-Style ist ein Entwicklungsansatz, der die Prinzipien von TDD mit der Philosophie von t.wada kombiniert","pt":"TDD-Wada-Style é uma filosofia de desenvolvimento que enfatiza a importância da escrita de testes como parte do processo de design","ru":"TDD-Wada-Style - это философия разработки, подчеркивающая важность написания тестов как части процесса проектирования для ИИ Агентов","ar":"TDD-Wada-Style هو فلسفة للتنمية تبرز أهمية كتابة الاختبارات كجزء من عملية التصميم لمنصات الإيجابية الذكية"},"features":{"en":["Implements the Red-Green-Refactor cycle for efficient testing","Applies the principle that tests are a design action, driving API design","Treats test code as the most accurate documentation, serving as a specification","Emphasizes small, rapid cycles of testing and refactoring","Breaks down requirements into behavioral components for testing"],"zh":["测试驱动开发的核心思想","3个原则：测试是设计行为、测试是仕様書、 小さく回す","TDD Cycle：Red-Green-Refactor流程","提高代码质量和开发效率","遵循和田卓人氏的TDD哲学"],"ja":["テスト駆動開発の核心思想","3つの原則：テストは設計行為、テストは仕様書、 小さく回す","TDD Cycle：Red-Green-Refactor流程","コードの品質と開発効率を向上させる","和田卓人氏のTDD哲学に基づく"],"ko":["테스트 주도 개발의 핵심 철학","3가지 원칙：테스트는 설계 행위, 테스트는仕様書, 작은 사이클","TDD 주기：Red-Green-Refactor 프로세스","코드의 품질과 개발 효율성을 높인다","와다 타카토시씨의 TDD 철학을 기반으로"],"es":["Implementación de pruebas automatizadas con enfoque en la calidad del código","Diseño de API basado en pruebas","Documentación a través de código de pruebas","Ciclo de desarrollo Red-Green-Refactor","Enfoque en la creación de pruebas pequeñas y rápidas"],"fr":["Mise en œuvre de tests automatisés avec un focus sur la qualité du code","Conception d''API basée sur les tests","Documentation à travers le code de test","Cycle de développement Red-Green-Refactor","Focus sur la création de tests petits et rapides"],"de":["Implementierung von automatisierten Tests mit Fokus auf die Code-Qualität","API-Design basierend auf Tests","Dokumentation durch Testcode","Entwicklungszyklus Red-Green-Refactor","Fokus auf die Erstellung kleiner und schneller Tests"],"pt":["Implementação dos 3 princípios de t.wada","Ciclo Red-Green-Refactor para desenvolvimento iterativo","Escrita de testes como parte do processo de design","Melhoria da qualidade do código com testes automatizados","Desenvolvimento de APIs fáceis de usar com testes"],"ru":["Реализация 3 принципов t.wada","Цикл Red-Green-Refactor для итеративной разработки","Написание тестов как части процесса проектирования для ИИ Агентов","Улучшение качества кода с помощью автоматизированных тестов","Разработка легко используемых API с тестами"],"ar":["تنفيذ 3 مبادئ ل t.wada","دورة Red-Green-Refactor للتنمية التكرارية","كتابة الاختبارات كجزء من عملية التصميم لمنصات الإيجابية الذكية","تحسين جودة الكود مع الاختبارات الآلية","تنمية واجهات برمجة تطبيقات سهلة الاستخدام مع الاختبارات"]},"keywords":{"en":["how to use tdd-wada-style","tdd-wada-style tutorial","tdd-wada-style vs traditional TDD","tdd-wada-style setup guide","what is tdd-wada-style","tdd-wada-style best practices","tdd-wada-style for AI agents","tdd-wada-style install","tdd-wada-style example"],"zh":["tdd-wada-style","测试驱动开发","TDD","和田卓人","测试驱动开发最佳实践","TDD Cycle","Red-Green-Refactor","代码质量","开发效率"],"ja":["tdd-wada-style","テスト駆動開発","TDD","和田卓人","テスト駆動開発ガイド","TDD Cycle","Red-Green-Refactor","コードの品質","開発効率"],"ko":["tdd-wada-style","테스트 주도 개발","TDD","와다 타카토시","테스트 주도 개발 Setup Guide","TDD 주기","Red-Green-Refactor","코드의 품질","개발 효율성"],"es":["TDD-Wada-Style","desarrollo de software","pruebas automatizadas","calidad del código","diseño de API","documentación a través de código de pruebas","ciclo de desarrollo Red-Green-Refactor","herramientas de desarrollo","AI Agent","Herramientas de desarrollo de software"],"fr":["TDD-Wada-Style","développement de logiciels","tests automatisés","qualité du code","conception d''API","documentation à travers le code de test","cycle de développement Red-Green-Refactor","outils de développement","Agent IA","Outils de développement de logiciels"],"de":["TDD-Wada-Style","Software-Entwicklung","automatisierte Tests","Code-Qualität","API-Design","Dokumentation durch Testcode","Entwicklungszyklus Red-Green-Refactor","Entwicklungstools","KI-Agent","Software-Entwicklungstools"],"pt":["TDD-Wada-Style","Desenvolvimento de software","Testes automatizados","Ciclo Red-Green-Refactor","3 princípios de t.wada","Desenvolvimento de APIs","Qualidade do código","Desenvolvedores de software"],"ru":["TDD-Wada-Style","Разработка программного обеспечения","Автоматизированные тесты","Цикл Red-Green-Refactor","3 принципа t.wada","Разработка API","Качество кода","Разработчики ИИ Агентов"],"ar":["TDD-Wada-Style","تنمية البرمجيات","الاختبارات الآلية","دورة Red-Green-Refactor","3 مبادئ ل t.wada","تنمية واجهات برمجة التطبيقات","جودة الكود","مطوري منصات الإيجابية الذكية"]}},"owner":"YunosukeYoshino","repo":"ImageScraper","repoPath":"YunosukeYoshino/ImageScraper","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.359Z","topics":[],"category":"community","skillMd":{"name":"tdd-wada-style","description":"t.wada流TDD（テスト駆動開発）。新機能実装、バグ修正、リファクタリング時に自動適用。Red-Green-Refactorサイクル、AAA構造、振る舞いテストの原則に従う。テストを書く、テストファーストで実装する、テストコードをレビューする際に使用。","bodyPreview":"# t.wada流 TDD（テスト駆動開発）\n\n和田卓人氏のTDD哲学に基づき、高品質なテスト駆動開発を実践する。\n\n## Core Philosophy（中核思想）\n\n> 「テストとは、動くことを証明するものではない。間違いを見つけるためのものだ。」\n> — t.wada\n\n### 3つの原則\n\n1. **テストは設計行為** — テストを書くことで、使いやすいAPIを設計する\n2. **テストは仕様書** — テストコードが最も正確なドキュメントである\n3. **小さく回す** — Red → Green → Refactor を短いサイクルで繰り返す\n\n## TDD Cycle（Red-Green-Refactor）\n\n```\n🔴 RED      → 失敗するテストを先に書く\n     ↓\n🟢 GREEN    → 最小限のコードでテストを通す\n     ↓\n🔵 REFACTOR → テストが通ったまま設計を改善\n     ↓\n   （繰り返し）\n```\n\n## Instructions\n\n### Step 1: 要件を振る舞いで分解\n\n実装前に「〜したとき、〜となる」形","body":"# t.wada流 TDD（テスト駆動開発）\n\n和田卓人氏のTDD哲学に基づき、高品質なテスト駆動開発を実践する。\n\n## Core Philosophy（中核思想）\n\n> 「テストとは、動くことを証明するものではない。間違いを見つけるためのものだ。」\n> — t.wada\n\n### 3つの原則\n\n1. **テストは設計行為** — テストを書くことで、使いやすいAPIを設計する\n2. **テストは仕様書** — テストコードが最も正確なドキュメントである\n3. **小さく回す** — Red → Green → Refactor を短いサイクルで繰り返す\n\n## TDD Cycle（Red-Green-Refactor）\n\n```\n🔴 RED      → 失敗するテストを先に書く\n     ↓\n🟢 GREEN    → 最小限のコードでテストを通す\n     ↓\n🔵 REFACTOR → テストが通ったまま設計を改善\n     ↓\n   （繰り返し）\n```\n\n## Instructions\n\n### Step 1: 要件を振る舞いで分解\n\n実装前に「〜したとき、〜となる」形式でテストケースをリストアップする。\n\n```markdown\nテストケースリスト:\n□ 空のリストを渡すと空のリストを返す\n□ 1要素のリストはそのまま返す\n□ 複数要素は昇順でソートされる\n□ 負の数を含んでも正しくソートされる\n```\n\n最も単純なケースから始める。\n\n### Step 2: テスト構造（AAA パターン）\n\nすべてのテストは Arrange-Act-Assert の3フェーズで構成する。\n\n```python\ndef test_振る舞いを日本語で記述():\n    # Arrange（準備）\n    sut = TargetClass()\n    input_data = create_test_data()\n\n    # Act（実行）\n    result = sut.target_method(input_data)\n\n    # Assert（検証）\n    assert result == expected_value\n```\n\n**ポイント:**\n- テスト名は日本語で振る舞いを明確に記述\n- 1テスト1アサーション（原則）\n- 3つのブロックを空行で明確に分離\n\n### Step 3: 境界値と異常系\n\n必ず以下をカバーする:\n\n```python\n# 境界値テスト\ndef test_空入力():\n    assert func([]) == []\n\ndef test_単一要素():\n    assert func([1]) == [1]\n\ndef test_最大値():\n    assert func([MAX_VALUE]) == expected\n\ndef test_最大値プラス1で例外():\n    with pytest.raises(ValueError):\n        func([MAX_VALUE + 1])\n\n# 異常系テスト\ndef test_None入力で例外():\n    with pytest.raises(TypeError):\n        func(None)\n\ndef test_不正な型で例外():\n    with pytest.raises(TypeError):\n        func(\"not a list\")\n```\n\n### Step 4: Refactor（リファクタリング）\n\nテストがグリーンの状態を維持しながら:\n- 重複の除去\n- 命名の改善\n- 責務の分離\n\n**ルール:** 振る舞いを変えずに構造を改善する\n\n## Anti-Patterns（避けるべきパターン）\n\n### ❌ 実装詳細のテスト\n\n```python\n# Bad: 内部状態に依存\nassert obj._internal_cache == {...}\nassert obj._call_count == 3\n\n# Good: 振る舞いをテスト\nassert obj.get_result() == expected\n```\n\n### ❌ テスト間の依存\n\n```python\n# Bad: 前のテストの状態に依存\nclass TestCounter:\n    counter = Counter()  # 共有状態\n\n    def test_1(self):\n        self.counter.increment()\n\n    def test_2(self):\n        assert self.counter.value == 1  # test_1に依存\n\n# Good: 各テストが独立\ndef test_increment():\n    counter = Counter()\n    counter.increment()\n    assert counter.value == 1\n```\n\n### ❌ 過度なモック\n\n```python\n# Bad: すべてをモック化（何もテストしていない）\n@patch(''module.ClassA'')\n@patch(''module.ClassB'')\n@patch(''module.ClassC'')\ndef test_something(mock_a, mock_b, mock_c):\n    ...\n\n# Good: 外部境界のみモック化\n@patch(''module.external_api_client'')\ndef test_something(mock_api):\n    ...\n```\n\n### ❌ 巨大なテスト\n\n```python\n# Bad: 1テストで複数の振る舞い\ndef test_user_registration():\n    # 50行のテストコード...\n    assert user.email == ...\n    assert user.created_at == ...\n    assert email_sent == True\n    assert db.users.count() == ...\n\n# Good: 1テスト1振る舞い\ndef test_ユーザー登録でメールアドレスが保存される():\n    ...\n\ndef test_ユーザー登録で確認メールが送信される():\n    ...\n```\n\n## Test Template\n\n新しいテストファイルを作成する際のテンプレート:\n\n```python\n\"\"\"\n{モジュール名}のテスト\n\nテスト対象: {クラス名/関数名}\n\"\"\"\nimport pytest\nfrom src.module import TargetClass\n\n\nclass Test{TargetClass}:\n    \"\"\"TargetClassの振る舞いテスト\"\"\"\n\n    # ========== 正常系 ==========\n\n    def test_基本的な使用方法(self):\n        \"\"\"最も一般的なユースケース\"\"\"\n        # Arrange\n        sut = TargetClass()\n\n        # Act\n        result = sut.do_something(\"input\")\n\n        # Assert\n        assert result == \"expected\"\n\n    # ========== 境界値 ==========\n\n    def test_空入力(self):\n        \"\"\"空の入力を処理できる\"\"\"\n        sut = TargetClass()\n        result = sut.do_something(\"\")\n        assert result == \"\"\n\n    def test_最大長入力(self):\n        \"\"\"最大長の入力を処理できる\"\"\"\n        sut = TargetClass()\n        result = sut.do_something(\"x\" * MAX_LENGTH)\n        assert len(result) <= MAX_LENGTH\n\n    # ========== 異常系 ==========\n\n    def test_None入力で例外(self):\n        \"\"\"Noneを渡すとTypeErrorが発生\"\"\"\n        sut = TargetClass()\n        with pytest.raises(TypeError):\n            sut.do_something(None)\n\n    def test_不正な入力でValueError(self):\n        \"\"\"不正な入力はValueErrorを発生\"\"\"\n        sut = TargetClass()\n        with pytest.raises(ValueError) as exc_info:\n            sut.do_something(\"invalid\")\n        assert \"不正な入力\" in str(exc_info.value)\n```\n\n## Checklist\n\n実装完了時の確認項目:\n\n- [ ] すべてのテストがパス\n- [ ] 各テストが独立して実行可能\n- [ ] テスト名から振る舞いが理解できる\n- [ ] AAA構造が明確\n- [ ] 境界値がカバーされている\n- [ ] 異常系がカバーされている\n- [ ] 実装詳細ではなく振る舞いをテスト\n- [ ] 過度なモックを使用していない\n\n## References\n\n追加のガイダンスは以下を参照:\n- [EXAMPLES.md](EXAMPLES.md) - 具体的なテストパターン例\n- [PATTERNS.md](PATTERNS.md) - よくあるテストパターン集\n"},"lastSynced":"2026-03-08T02:04:09.928Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Development Agents needing structured TDD workflows based on t.wada''s philosophy.","zh":"非常适合需要结构化TDD工作流的代码开发代理，基于t.wada的哲学。","ja":"t.wadaの哲学に基づいた構造化されたTDDワークフローを必要とするコード開発エージェントに最適。","ko":"t.wada의 철학을 기반으로 구조화된 TDD 워크플로가 필요한 코드 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de código que necesitan flujos de trabajo de TDD estructurados basados en la filosofía de t.wada.","fr":"Parfait pour les agents de développement de code ayant besoin de flux de travail TDD structurés basés sur la philosophie de t.wada.","de":"Perfekt für Code-Entwicklungsagenten, die strukturierte TDD-Workflows basierend auf der Philosophie von t.wada benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Código que necessitam de fluxos de trabalho TDD estruturados baseados na filosofia de t.wada.","ru":"Идеально подходит для агентов разработки кода, требующих структурированных рабочих процессов TDD на основе философии t.wada.","ar":"مثالي لعميل تطوير الكود الذي يحتاج إلى سير عمل اختبار قائم على التصميم بناءً على فلسفة t.wada."},"recommendation":{"en":"Enables agents to implement Red-Green-Refactor cycles systematically, decomposing requirements into behavioral specifications before coding. Provides structured test-driven development with minimal implementation steps and continuous design improvement.","zh":"使代理能够系统地实施红绿重构周期，将需求分解为行为规范，然后进行编码。提供结构化的测试驱动开发，具有最小的实现步骤和持续的设计改进。","ja":"エージェントが、要件を行動仕様に分解してからコーディングを行うことで、systematically Red-Green-Refactor サイクルを実装できるようにします。最小限の実装ステップと継続的な設計改善を伴う構造化されたテスト駆動開発を提供します。","ko":"에이전트가 요구 사항을 행동 사양으로 분해한 다음 코딩을 통해 체계적으로 적색-녹색-리팩토링 주기를 구현할 수 있도록 합니다. 최소한의 구현 단계와 지속적인 설계 개선을 갖춘 구조화된 테스트 주도 개발을 제공합니다.","es":"Permite a los agentes implementar ciclos de Red-Green-Refactor de manera sistemática, descomponiendo los requisitos en especificaciones de comportamiento antes de codificar. Proporciona un desarrollo dirigido por pruebas estructurado con pasos de implementación mínimos y mejora continua del diseño.","fr":"Permet aux agents de mettre en œuvre des cycles Red-Green-Refactor de manière systématique, en décomposant les exigences en spécifications de comportement avant de coder. Fournit un développement dirigé par des tests structuré avec des étapes d''implémentation minimales et une amélioration continue de la conception.","de":"Ermöglicht es Agenten, Red-Green-Refactor-Zyklen systematisch umzusetzen, indem sie Anforderungen in Verhaltensspezifikationen vor der Codierung zerlegen. Bietet strukturierte testgetriebene Entwicklung mit minimalen Implementierungsschritten und kontinuierlicher Designverbesserung.","pt":"Permite que os agentes implementem ciclos Red-Green-Refactor de forma sistemática, decompondo requisitos em especificações comportamentais antes da codificação. Fornece desenvolvimento de teste orientado por estrutura com etapas de implementação mínimas e melhoria contínua de design.","ru":"Позволяет агентам реализовывать циклы Red-Green-Refactor систематически, разбивая требования на поведенческие спецификации до написания кода. Обеспечивает структурированное тестирование с минимальными шагами реализации и постоянным улучшением дизайна.","ar":"يمكن للعملاء تنفيذ دورات التحرير-الاخضر-إعادة الهيكلة بطريقة منهجية، و تفكيك المتطلبات إلى مواصفات سلوكية قبل البرمجة. يوفر تطوير اختبار مدعوم بتصميم بدرجات تنفيذ минимية وتحسين التصميم المستمر."},"useCases":{"en":["Decomposing requirements into ''when-then'' behavioral specifications","Implementing failing tests first (RED phase)","Writing minimal code to pass tests (GREEN phase)","Refactoring code while maintaining test passes (REFACTOR phase)"],"zh":["将需求分解为''当-则''行为规范","首先实施失败的测试（RED 阶段）","编写最小代码以通过测试（GREEN 阶段）","在保持测试通过的同时重构代码（REFACTOR 阶段）"],"ja":["要件を''when-then'' 行動仕様に分解する","失敗するテストを先に実装する（RED フェーズ）","テストに合格するための最小限のコードを記述する（GREEN フェーズ）","テストの合格を維持しながらコードをリファクタリングする（REFACTOR フェーズ）"],"ko":["요구 사항을 ''when-then'' 행동 사양으로 분해한다","먼저 실패하는 테스트를 구현한다(RED 단계)","테스트를 통과하기 위한 최소한의 코드를 작성한다(GREEN 단계)","테스트 통과를 유지하면서 코드를 리팩토링한다(REFATOR 단계)"],"es":["Descomponer los requisitos en especificaciones de comportamiento ''cuándo-entonces''","Implementar pruebas fallidas en primer lugar (fase RED)","Escribir código mínimo para aprobar pruebas (fase GREEN)","Reestructurar el código manteniendo aprobaciones de pruebas (fase REFACTOR)"],"fr":["Décomposer les exigences en spécifications de comportement ''lorsque-alors''","Mettre en œuvre des tests qui échouent en premier lieu (phase RED)","Écrire un code minimal pour passer les tests (phase GREEN)","Réorganiser le code en maintenant les approbations de tests (phase REFACTOR)"],"de":["Anforderungen in Verhaltensspezifikationen ''wenn-dann'' zerlegen","Zuerst fehlende Tests implementieren (RED-Phase)","Minimalen Code zum Bestehen von Tests schreiben (GREEN-Phase)","Code umstrukturieren, während Testbestehen beibehalten wird (REFACTOR-Phase)"],"pt":["Decompor requisitos em especificações comportamentais ''quando-então''","Implementar testes com falha primeiro (fase RED)","Escrever código mínimo para passar nos testes (fase GREEN)","Reestruturar código mantendo a aprovação dos testes (fase REFACTOR)"],"ru":["Разбить требования на поведенческие спецификации ''когда-то''","Реализовать сначала неудачные тесты (фаза RED)","Написать минимальный код для прохождения тестов (фаза GREEN)","Перестроить код, сохраняя прохождение тестов (фаза REFACTOR)"],"ar":["تفكيك المتطلبات إلى مواصفات سلوكية ''عند-ثم''","تنفيذ اختبارات فاشلة أولاً (مرحلة الحمر)","كتابة كود أدنى ل Passing اختبارات (مرحلة الخضر)","إعادة هيكلة الكود مع الحفاظ على прохождение الاختبارات (مرحلة إعادة الهيكلة)"]},"limitations":{"en":["Requires understanding of t.wada''s specific TDD philosophy","Focuses on behavioral decomposition rather than implementation-first approach"],"zh":["需要理解t.wada的特定TDD哲学","关注行为分解而不是实现优先的方法"],"ja":["t.wadaの特定のTDD哲学を理解する必要がある","実装優先アプローチではなく行動分解に焦点を当てている"],"ko":["t.wada의 특정 TDD 철학을 이해해야 함","구현 우선 접근법이 아닌 행동 분해에 중점을 둠"],"es":["Requiere comprensión de la filosofía de TDD específica de t.wada","Se centra en la descomposición del comportamiento en lugar de un enfoque de implementación primero"],"fr":["Nécessite une compréhension de la philosophie TDD spécifique de t.wada","Se concentre sur la décomposition du comportement plutôt que sur une approche d''implémentation en premier"],"de":["Benötigt Verständnis für die spezifische TDD-Philosophie von t.wada","Konzentriert sich auf die Verhaltenszerlegung anstatt auf einen implementierungsorientierten Ansatz"],"pt":["Exige compreensão da filosofia TDD específica de t.wada","Foca na decomposição comportamental em vez de abordagem de implementação primeiro"],"ru":["Требует понимания конкретной философии TDD t.wada","Сосредоточен на поведенческой декомпозиции, а не на подходе реализации сначала"],"ar":["يتطلب فهم فلسفة ت.وادا الخاصة للاختبار القائم على التصميم","يركز على التحلل السلوكي بدلاً من نهج التنفيذ أولاً"]},"version":4},"contentHash":"a9b88f63a1c795e8858452f02b40a74849ff531785a0ecfea3c5dc1038336a80","qualityScore":54}');
DELETE FROM skills_fts WHERE id = 'YunosukeYoshino/ImageScraper/tdd-wada-style';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('YunosukeYoshino/ImageScraper/tdd-wada-style', 'tdd-wada-style', 'YunosukeYoshino', 'ImageScraper', 'community', 'tdd-wada-style YunosukeYoshino ImageScraper community The tdd-wada-style skill enables developers to practice high-quality test-driven development based on t.wada''s TDD philosophy. It benefits developers by providing a structured approach to testing and coding. tdd-wada-style是一种测试驱动开发方法，强调测试在设计和开发中的重要性。通过遵循3个原则和TDD Cycle，开发者可以提高代码质量和开发效率 tdd-wada-styleは、テスト駆動開発におけるテストの重要性を強調する開発方法です。3つの原則とTDD Cycleに従うことで、開発者はコードの品質と開発効率を向上させることができます tdd-wada-style은 테스트 주도 개발에서 테스트의 중요성을 강조하는 개발 방법입니다. 3가지 원칙과 TDD 주기를 따르면 개발자는 코드의 품질과 개발 효율성을 높일 수 있습니다 El TDD-Wada-Style es un enfoque de desarrollo que se centra en la creación de pruebas automatizadas para garantizar la calidad del código Le TDD-Wada-Style est une approche de développement qui se concentre sur la création de tests automatisés pour garantir la qualité du code Der TDD-Wada-Style ist ein Entwicklungsansatz, der sich auf die Erstellung von automatisierten Tests konzentriert, um die Qualität des Codes zu gewährleisten O TDD-Wada-Style é uma abordagem de desenvolvimento baseada nos 3 princípios de t.wada, que visa melhorar a qualidade do código TDD-Wada-Style - это подход к разработке, основанный на 3 принципах t.wada, направленный на улучшение качества кода для ИИ Агентов TDD-Wada-Style هو نهج للتنمية يعتمد على 3 مبادئ ل t.wada، يهدف إلى تحسين جودة الكود لمنصات الإيجابية الذكية how to use tdd-wada-style tdd-wada-style tutorial tdd-wada-style vs traditional TDD tdd-wada-style setup guide what is tdd-wada-style tdd-wada-style best practices tdd-wada-style for AI agents tdd-wada-style install tdd-wada-style example tdd-wada-style 测试驱动开发 TDD 和田卓人 测试驱动开发最佳实践 TDD Cycle Red-Green-Refactor 代码质量 开发效率 Implements the Red-Green-Refactor cycle for efficient testing Applies the principle that tests are a design action, driving API design Treats test code as the most accurate documentation, serving as a specification Emphasizes small, rapid cycles of testing and refactoring Breaks down requirements into behavioral components for testing tdd-wada-style is a test-driven development approach based on t.wada''s philosophy, emphasizing testing as a means to detect mistakes, not just prove functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('madooei/backend-template/add-env-variable', 'community', 'madooei', 'backend-template', 'madooei/backend-template', 'add-env-variable', 0, 0, 54, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:11.198Z', '072333f034c735697eb5ef2191ea6bf60353b7d4748d454e2f6f0f18715e3153', '{"id":"madooei/backend-template/add-env-variable","name":"add-env-variable","description":{"en":"The add-env-variable skill provides a template for adding new environment variables with Zod validation in a TypeScript and Hono.js backend service, benefiting developers who need to manage environment variables efficiently.","zh":"add-env-variable 是一个用于添加环境变量的模板，使用 TypeScript 和 Hono.js 构建。它提供了一个基本的 RESTful API 结构","ja":"add-env-variable は、環境変数を追加するためのテンプレートで、TypeScript と Hono.js で構築されています。基本的な RESTful API 構造を提供します","ko":"add-env-variable 은 환경 변수를 추가하는 템플릿으로, TypeScript와 Hono.js로 구축되었습니다. 기본적인 RESTful API 구조를 제공합니다","es":"El skill add-env-variable permite agregar variables de entorno con validación Zod en proyectos de TypeScript y Hono.js.","fr":"Le skill add-env-variable permet d''ajouter des variables d''environnement avec validation Zod dans les projets TypeScript et Hono.js.","de":"Das Skill add-env-variable ermöglicht das Hinzufügen von Umgebungsvariablen mit Zod-Validierung in TypeScript- und Hono.js-Projekten.","pt":"O add-env-variable é um template para serviços backend em TypeScript e Hono.js que fornece uma estrutura básica para criar APIs RESTful com validação de variáveis de ambiente.","ru":"Add-env-variable - это шаблон для бэкенд-сервисов на TypeScript и Hono.js, который предоставляет базовую структуру для создания RESTful API с валидацией переменных среды.","ar":"إضافة متغير البيئة هو قالب لخدمات الخادم الخلفي مع TypeScript وHono.js يوفر هيكلا أساسيا لإضافة واجهات برمجة التطبيقات RESTful مع التحقق من متغيرات البيئة"},"seo":{"title