INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('madooei/backend-template/add-env-variable', 'add-env-variable', 'madooei', 'backend-template', 'community', 'add-env-variable madooei backend-template community The add-env-variable skill provides a template for adding new environment variables with Zod validation in a TypeScript and Hono.js backend service, benefiting developers who need to manage environment variables efficiently. add-env-variable 是一个用于添加环境变量的模板，使用 TypeScript 和 Hono.js 构建。它提供了一个基本的 RESTful API 结构 add-env-variable は、環境変数を追加するためのテンプレートで、TypeScript と Hono.js で構築されています。基本的な RESTful API 構造を提供します add-env-variable 은 환경 변수를 추가하는 템플릿으로, TypeScript와 Hono.js로 구축되었습니다. 기본적인 RESTful API 구조를 제공합니다 El skill add-env-variable permite agregar variables de entorno con validación Zod en proyectos de TypeScript y Hono.js. Le skill add-env-variable permet d''ajouter des variables d''environnement avec validation Zod dans les projets TypeScript et Hono.js. Das Skill add-env-variable ermöglicht das Hinzufügen von Umgebungsvariablen mit Zod-Validierung in TypeScript- und Hono.js-Projekten. O add-env-variable é um template para serviços backend em TypeScript e Hono.js que fornece uma estrutura básica para criar APIs RESTful com validação de variáveis de ambiente. Add-env-variable - это шаблон для бэкенд-сервисов на TypeScript и Hono.js, который предоставляет базовую структуру для создания RESTful API с валидацией переменных среды. إضافة متغير البيئة هو قالب لخدمات الخادم الخلفي مع TypeScript وHono.js يوفر هيكلا أساسيا لإضافة واجهات برمجة التطبيقات RESTful مع التحقق من متغيرات البيئة how to use add-env-variable add-env-variable setup guide add-env-variable alternative what is add-env-variable add-env-variable vs environment variables add-env-variable install Zod validation for environment variables TypeScript environment variable management Hono.js backend service development add-env-variable 环境变量 Zod TypeScript Hono.js RESTful API AI 工具 环境变量设置 Zod 验证 Adds new environment variables with Zod validation Requires definition in src/env.ts and documentation in .env.example Supports validation tests in tests/env.test.ts Utilizes TypeScript and Hono.js for backend service development Follows a structured approach for environment variable management add-env-variable is a skill that enables developers to add new environment variables with Zod validation in a backend service, following a structured approach for defining and documenting variables.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maxlogvn/AiCMR/doc-index', 'community', 'maxlogvn', 'AiCMR', 'maxlogvn/AiCMR', 'doc-index', 0, 0, 54, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:13.914Z', 'a71b815a3660ad8a0d8e5c9c65f7ffaf0f63c02f6aa3c9aa141441f15eb70621', '{"id":"maxlogvn/AiCMR/doc-index","name":"doc-index","description":{"en":"The doc-index skill updates documentation indexes in README.md and CLAUDE.md when the docs/ directory changes. It ensures indexes reflect the actual file structure, eliminating hardcoded file names.","zh":"doc-index 是一个动态文档索引更新工具，能够自动扫描和同步文档目录，保持文档的最新性和准确性","ja":"doc-index は動的なドキュメントインデックス更新ツールで、ドキュメントディレクトリを自動的にスキャンして同期し、ドキュメントの最新性と正確性を維持します","ko":"doc-index는 동적 문서 색인 업데이트 도구로서 문서 디렉토리를 자동으로 스캔하고 동기화하여 문서의 최신성과 정확성을 유지합니다","es":"Doc-index es una función que actualiza los índices de documentación de forma dinámica cuando cambian los archivos en el directorio docs/. Permite mantener la documentación sincronizada sin necesidad de hardcodear nombres de archivos","fr":"Doc-index est une fonction qui met à jour les indexes de documentation de manière dynamique lorsque les fichiers du répertoire docs/ changent. Cela permet de maintenir la documentation synchronisée sans avoir à durcir les noms de fichiers","de":"Doc-index ist eine Funktion, die die Dokumentationsindizes dynamisch aktualisiert, wenn sich die Dateien im Verzeichnis docs/ ändern. Damit können Sie Ihre Dokumentation synchron halten, ohne Dateinamen festkodieren zu müssen","pt":"O índice de documentação automática é uma ferramenta que atualiza dinamicamente os arquivos de documentação em resposta a alterações no diretório docs/.","ru":"Автоматический индекс документации - это инструмент, который динамически обновляет файлы документации в ответ на изменения в директории docs/.","ar":"فهرس الوثائق الآلي هو أداة تحديث 动态 لملفات الوثائق استجابة للتغييرات في الدليل docs/."},"seo":{"title":{"en":"doc-index: Dynamic Documentation Indexing Setup Guide | A...","zh":"doc-index 设置指南：动态文档索引更新","ja":"doc-index セットアップガイド：動的なドキュメントインデックスの更新","ko":"doc-index 설정 가이드: 동적 문서 색인 업데이트","es":"Guía de configuración de doc-index para actualizaciones d...","fr":"Guide d''installation de doc-index pour des mises à jour d...","de":"Einrichtungsanleitung für doc-index mit dynamischer Synch...","pt":"Guia de Configuração do Índice de Documentação Automática...","ru":"Настройка ИИ Агентов для Автоматического Индексирования Д...","ar":"دليل إعداد فهرس الوثائق الآلي باستخدام أدوات الذكاء الاصط..."},"description":{"en":"Automate your documentation indexing with doc-index. Learn how to sync README.md and CLAUDE.md files dynamically and discover the best practices for AI agents.","zh":"了解如何使用 doc-index 实现动态文档索引更新，保持文档目录的准确性和最新性，提高开发效率","ja":"doc-index を使用して動的なドキュメントインデックスを更新し、ドキュメントディレクトリの正確性と最新性を維持する方法を学びます","ko":"doc-index를 사용하여 동적 문서 색인을 업데이트하고 문서 디렉토리의 정확성과 최신성을 유지하는 방법을 알아보세요","es":"Descubre cómo configurar doc-index para mantener tus índices de documentación actualizados de forma dinámica y sin hardcodear nombres de archivos","fr":"Découvrez comment installer doc-index pour mettre à jour vos indexes de documentation de manière dynamique sans durcir les noms de fichiers","de":"Erfahren Sie, wie Sie doc-index einrichten, um Ihre Dokumentationsindizes dynamisch und ohne Festkodierung von Dateinamen zu aktualisieren","pt":"Aprenda a configurar o índice de documentação automática com ferramentas de IA para manter seus documentos atualizados e sincronizados","ru":"Узнайте, как настроить автоматическое индексирование документации с помощью ИИ Агентов для поддержания актуальности ваших документов","ar":"تعلم كيفية إعداد فهرس الوثائق الآلي باستخدام أدوات الذكاء الاصطناعي للحفاظ على تحديث وثائقك وتنظيمها"},"definition":{"en":"doc-index is a dynamic documentation indexing system that scans and syncs indexes automatically, reflecting changes in the docs/ directory.","zh":"doc-index 是一个用于动态更新文档索引的工具，保持文档目录的准确性和最新性","ja":"doc-index は動的なドキュメントインデックス更新ツールで、ドキュメントディレクトリの正確性と最新性を維持します","ko":"doc-index는 동적 문서 색인 업데이트를 위한 도구로서 문서 디렉토리의 정확성과 최신성을 유지합니다","es":"Doc-index es una función que mantiene los índices de documentación actualizados de forma dinámica","fr":"Doc-index est une fonction qui maintient les indexes de documentation à jour de manière dynamique","de":"Doc-index ist eine Funktion, die die Dokumentationsindizes dynamisch auf dem neuesten Stand hält","pt":"O índice de documentação automática é uma tecnologia que cria um índice dinâmico dos arquivos de documentação em um diretório","ru":"Автоматический индекс документации - это технология, создающая динамический индекс файлов документации в директории","ar":"فهرس الوثائق الآلي هو تكنولوجيا tạo فهرس ديناميكي لملفات الوثائق في دليل"},"features":{"en":["Scans and syncs documentation indexes dynamically","Updates README.md and CLAUDE.md files automatically","Eliminates hardcoded file names for flexibility","Reflects actual file structure in the docs/ directory","Supports dynamic updates when files are added, removed, or moved"],"zh":["动态扫描和同步文档目录","自动更新文档索引","支持 README.md 和 CLAUDE.md 文件","不需要 hardcode 文件名","保持文档的最新性和准确性"],"ja":["動的なドキュメントディレクトリのスキャンと同期","自動的なドキュメントインデックスの更新","README.md と CLAUDE.md ファイルのサポート","ファイル名のハードコーディング不要","ドキュメントの最新性と正確性の維持"],"ko":["동적 문서 디렉토리의 스캔과 동기화","자동 문서 색인 업데이트","README.md와 CLAUDE.md 파일 지원","파일 이름의 하드코딩 필요 없음","문서의 최신성과 정확성 유지"],"es":["Actualización dinámica de los índices de documentación","No requiere hardcodear nombres de archivos","Sincronización automática con el directorio docs/","Compatible con la creación de nuevos archivos .md","Soporte para la actualización de índices al eliminar o mover archivos"],"fr":["Mise à jour dynamique des indexes de documentation","Nécessite pas de durcir les noms de fichiers","Synchronisation automatique avec le répertoire docs/","Compatible avec la création de nouveaux fichiers .md","Prise en charge de la mise à jour des indexes lors de la suppression ou du déplacement de fichiers"],"de":["Dynamische Aktualisierung der Dokumentationsindizes","Erfordert keine Festkodierung von Dateinamen","Automatische Synchronisierung mit dem Verzeichnis docs/","Kompatibilität mit der Erstellung neuer Dateien .md","Unterstützung für die Aktualisierung von Indizes bei der Löschung oder Verschiebung von Dateien"],"pt":["Atualização dinâmica dos arquivos de documentação","Suporte à sincronização automática com o diretório docs/","Não requer hardcode de nomes de arquivos","Índice de documentação como fonte de verdade","Suporte à criação de novos arquivos .md no diretório docs/"],"ru":["Динамическое обновление файлов документации","Поддержка автоматической синхронизации с директорией docs/","Не требует hardcode имён файлов","Индекс документации как источник правды","Поддержка создания новых файлов .md в директории docs/"],"ar":["تحديث ديناميكي لملفات الوثائق","دعم التزامن الآلي مع الدليل docs/","لا يتطلب تدوين أسماء الملفات","فهرس الوثائق كمصدر للحقيقة","دعم إنشاء ملفات .md جديدة في الدليل docs/"]},"keywords":{"en":["how to use doc-index","doc-index setup guide","dynamic documentation indexing","README.md automation","CLAUDE.md synchronization","doc-index alternative","doc-index vs static indexing","install doc-index","doc-index for AI agents"],"zh":["doc-index","动态文档索引","文档目录更新","README.md","CLAUDE.md","自动更新","文档最新性","AIエージェント","文档管理"],"ja":["doc-index","動的なドキュメントインデックス","ドキュメントディレクトリの更新","README.md","CLAUDE.md","自動更新","ドキュメントの最新性","AIエージェント","ドキュメント管理"],"ko":["doc-index","동적 문서 색인","문서 디렉토리 업데이트","README.md","CLAUDE.md","자동 업데이트","문서 최신성","AI 에이전트","문서 관리"],"es":["doc-index","índices de documentación","actualización dinámica","sincronización automática","creación de archivos .md","eliminación de archivos","movimiento de archivos","herramientas de documentación","desarrollo de software"],"fr":["doc-index","indexes de documentation","mise à jour dynamique","synchronisation automatique","création de fichiers .md","suppression de fichiers","déplacement de fichiers","outils de documentation","développement de logiciels"],"de":["doc-index","Dokumentationsindizes","dynamische Aktualisierung","automatische Synchronisierung","Erstellung von Dateien .md","Löschung von Dateien","Verschiebung von Dateien","Dokumentationswerkzeuge","Softwareentwicklung"],"pt":["índice de documentação automática","ferramentas de IA para documentação","sincronização automática de documentos","criação de índices dinâmicos","documentação como fonte de verdade","desenvolvimento de software com IA","ferramentas de desenvolvimento com IA"],"ru":["автоматический индекс документации","ИИ Агенты для документации","автоматическая синхронизация документов","создание динамических индексов","документация как источник правды","разработка программного обеспечения с ИИ","инструменты разработки с ИИ"],"ar":["فهرس الوثائق الآلي","أدوات الذكاء الاصطناعي للوثائق","التزامن الآلي للوثائق","إنشاء فهارس ديناميكية","الوثائق كمصدر للحقيقة","تطوير البرمجيات بالذكاء الاصطناعي","أدوات التطوير بالذكاء الاصطناعي"]}},"owner":"maxlogvn","repo":"AiCMR","repoPath":"maxlogvn/AiCMR","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"doc-index","description":"Use when adding, renaming, or reorganizing documentation files. Keep README.md and CLAUDE.md documentation indexes synchronized with docs/ directory.","bodyPreview":"# Documentation Index\r\n\r\n## Overview\r\n\r\nCập nhật Documentation Index trong `README.md` và `CLAUDE.md` khi docs/ thay đổi. **KHÔNG hardcode file names** — luôn scan và sync dynamically.\r\n\r\n## Core Principle\r\n\r\n> **Documentation Index = Source of Truth**\r\n>\r\n> Indexes phải phản ánh **thực tế** trong `docs/` directory, không phải danh sách files tĩnh. Mỗi khi thêm/xóa/di chuyển files → cập nhật indexes ngay.\r\n\r\n## When to Use\r\n\r\n```\r\n✅ Tạo file .md mới trong docs/        → Update indexes\r\n✅ Di chuy","body":"# Documentation Index\r\n\r\n## Overview\r\n\r\nCập nhật Documentation Index trong `README.md` và `CLAUDE.md` khi docs/ thay đổi. **KHÔNG hardcode file names** — luôn scan và sync dynamically.\r\n\r\n## Core Principle\r\n\r\n> **Documentation Index = Source of Truth**\r\n>\r\n> Indexes phải phản ánh **thực tế** trong `docs/` directory, không phải danh sách files tĩnh. Mỗi khi thêm/xóa/di chuyển files → cập nhật indexes ngay.\r\n\r\n## When to Use\r\n\r\n```\r\n✅ Tạo file .md mới trong docs/        → Update indexes\r\n✅ Di chuyển/rename file docs          → Update references\r\n✅ Tổ chức lại docs/ structure         → Reorganize indexes\r\n✅ Xóa file documentation              → Remove from indexes\r\n```\r\n\r\n## Dynamic Workflow\r\n\r\n### Step 1: Scan docs/ reality\r\n\r\n```bash\r\n# Liệt kê tất cả .md files hiện có\r\nfind docs -name \"*.md\" -type f | sort\r\n```\r\n\r\n**Expected output pattern**:\r\n```\r\ndocs/CODING_STANDARDS.md\r\ndocs/DEPLOYMENT.md\r\ndocs/GETTING_STARTED.md\r\ndocs/SETUP.md\r\ndocs/TECH_STACK.md\r\ndocs/USERS.md\r\n```\r\n\r\n### Step 2: Detect missing files in indexes\r\n\r\n```bash\r\n# Check CLAUDE.md index\r\ngrep -E \"\\`docs/.*\\.md\\`\" CLAUDE.md | sed ''s/.*`\\(.*\\)`.*/\\1/'' | sort > /tmp/claude_docs.txt\r\nfind docs -name \"*.md\" -type f | sort > /tmp/actual_docs.txt\r\ndiff /tmp/claude_docs.txt /tmp/actual_docs.txt\r\n```\r\n\r\n**Output interpretation**:\r\n- Lines starting with `<` → File có trong index nhưng KHÔNG có trong docs/ (xóa khỏi index)\r\n- Lines starting with `>` → File có trong docs/ nhưng THIẾU trong index (thêm vào index)\r\n\r\n### Step 3: Categorize files dynamically\r\n\r\n**Classification by filename pattern**:\r\n\r\n| Pattern | Category | Section (README) | Priority |\r\n|---------|----------|------------------|----------|\r\n| `SETUP.md` | Getting Started | Bắt đầu | 1 |\r\n| `GETTING_STARTED.md` | Getting Started | Bắt đầu | 2 |\r\n| `TECH_STACK.md` | Getting Started | Bắt đầu | 3 |\r\n| `PROJECT_STRUCTURE.md` | Getting Started | Bắt đầu | 4 |\r\n| `CODING_STANDARDS.md` | Development | Phát triển | 1 |\r\n| `DESIGN_ADN.md` | Development | Phát triển | 2 |\r\n| `*.md` (other core) | Development | Phát triển | 3 |\r\n| `modules/*.md` | Operations | Operations | 1 |\r\n| `DEPLOYMENT.md` | Operations | Operations | 2 |\r\n| `FAQ.md` | Operations | Operations | 3 |\r\n\r\n**Algorithm**:\r\n1. Scan tất cả files trong `docs/`\r\n2. Classify theo pattern và location (core vs modules/)\r\n3. Sắp xếp theo priority trong mỗi category\r\n4. Generate entries cho CLAUDE.md và README.md\r\n\r\n### Step 4: Update CLAUDE.md Documentation Index\r\n\r\n**Format**:\r\n```markdown\r\n## Documentation Index (Tra cứu nhanh)\r\n\r\n| Chủ đề                     | Vị trí                      |\r\n| -------------------------- | --------------------------- |\r\n| [Generated dynamically]    | `docs/FILE.md`              |\r\n```\r\n\r\n**Link text generation rules**:\r\n- `SETUP.md` → \"Hướng dẫn khởi động\"\r\n- `GETTING_STARTED.md` → \"Hướng dẫn chi tiết\"\r\n- `CODING_STANDARDS.md` → \"Chuẩn code\"\r\n- `PROJECT_STRUCTURE.md` → \"Cấu trúc dự án\"\r\n- `DESIGN_ADN.md` → \"Design system / tokens\"\r\n- `TECH_STACK.md` → \"Công nghệ sử dụng\"\r\n- `DEPLOYMENT.md` → \"Triển khai\"\r\n- `FAQ.md` → \"FAQ\"\r\n- `modules/*.md` → Tên topic (VD: \"Hệ thống người dùng & rank\" cho AUTH.md)\r\n- Other files → Tên file without extension, Title Case\r\n\r\n### Step 5: Update README.md sections\r\n\r\n**Section structure**:\r\n```markdown\r\n### Bắt đầu\r\n- **[Link Text](docs/FILE.md)** - Short description\r\n\r\n### Phát triển\r\n- **[Link Text](docs/FILE.md)** - Short description\r\n\r\n### Operations\r\n- **[Link Text](docs/FILE.md)** - Short description\r\n```\r\n\r\n**Description generation** (infer from filename):\r\n- `SETUP.md` → \"Clone, permissions, verify environment\"\r\n- `GETTING_STARTED.md` → \"Cài đặt chi tiết\"\r\n- `CODING_STANDARDS.md` → \"Conventions, patterns\"\r\n- `DESIGN_ADN.md` → \"Design tokens, Brutalist style\"\r\n- `TECH_STACK.md` → \"Dependencies chính xác\"\r\n- `PROJECT_STRUCTURE.md` → \"Tổ chức thư mục\"\r\n- `DEPLOYMENT.md` → \"Cấu hình production, vận hành\"\r\n- `FAQ.md` → \"Troubleshooting\"\r\n- `modules/AUTH.md` → \"Hệ thống phân quyền, test accounts\"\r\n\r\n### Step 6: Verify consistency\r\n\r\n```bash\r\n# 1. Count files in docs/\r\nDOC_COUNT=$(find docs -name \"*.md\" -type f | wc -l)\r\n\r\n# 2. Count entries in CLAUDE.md index\r\nCLAUDE_COUNT=$(grep -c \"\\`docs/.*\\.md\\`\" CLAUDE.md)\r\n\r\n# 3. Count entries in README.md\r\nREADME_COUNT=$(grep -c \"\\](docs/.*\\.md)\" README.md)\r\n\r\necho \"Docs: $DOC_COUNT | CLAUDE.md: $CLAUDE_COUNT | README.md: $README_COUNT\"\r\n```\r\n\r\n**Expected**: All counts should be equal (± reasonable margin for internal references)\r\n\r\n### Step 7: Commit changes\r\n\r\n```bash\r\ngit diff CLAUDE.md README.md  # Review\r\ngit add CLAUDE.md README.md\r\ngit commit -m \"docs: sync documentation index với docs/ directory\"\r\n```\r\n\r\n## Common Patterns\r\n\r\n### Adding new documentation file\r\n\r\n```bash\r\n# 1. Create file\r\ntouch docs/NEW_TOPIC.md\r\n\r\n# 2. Scan to detect\r\nfind docs -name \"*.md\" -type f | sort\r\n\r\n# 3. Classify → Determine section\r\n# If NEW_TOPIC.md → Core dev doc → \"Phát triển\" section\r\n\r\n# 4. Update CLAUDE.md\r\n| New Topic | `docs/NEW_TOPIC.md` |\r\n\r\n# 5. Update README.md\r\n### Phát triển\r\n- **[New Topic](docs/NEW_TOPIC.md)** - Description\r\n\r\n# 6. Verify & commit\r\n```\r\n\r\n### Moving file to modules/\r\n\r\n```bash\r\n# 1. Move file\r\ngit mv docs/USERS.md docs/modules/AUTH.md\r\n\r\n# 2. Update ALL references\r\ngit grep -l \"docs/USERS.md\" | xargs sed -i ''s|docs/USERS.md|docs/modules/AUTH.md|g''\r\n\r\n# 3. Reclassify → Core → Module\r\n# CLAUDE.md: Move entry from Development → Operations\r\n# README.md: Move link from \"Phát triển\" → \"Operations\"\r\n\r\n# 4. Verify no old paths remain\r\ngit grep \"docs/USERS.md\" .  # Should return nothing\r\n\r\n# 5. Commit\r\ngit add -A && git commit -m \"docs: move USERS.md → modules/AUTH.md\"\r\n```\r\n\r\n### Deleting documentation\r\n\r\n```bash\r\n# 1. Remove file\r\ngit rm docs/OBSOLETE.md\r\n\r\n# 2. Remove from CLAUDE.md index\r\n# Delete the row for OBSOLETE.md\r\n\r\n# 3. Remove from README.md\r\n# Delete the link for OBSOLETE.md\r\n\r\n# 4. Verify no dangling references\r\ngit grep \"OBSOLETE\" CLAUDE.md README.md  # Should return nothing\r\n\r\n# 5. Commit\r\ngit commit -m \"docs: remove obsolete OBSOLETE.md\"\r\n```\r\n\r\n## Anti-Patterns\r\n\r\n### ❌ Hardcoded file lists\r\n\r\n```markdown\r\n## Files to include:\r\n- SETUP.md\r\n- GETTING_STARTED.md\r\n- CODING_STANDARDS.md\r\n```\r\n\r\n**Why wrong**: List becomes stale immediately after any change.\r\n\r\n### ✅ Dynamic scanning\r\n\r\n```markdown\r\n## How to scan:\r\nfind docs -name \"*.md\" -type f | sort\r\n```\r\n\r\n**Why right**: Always reflects current state.\r\n\r\n### ❌ Manual categorization\r\n\r\n```\r\nIf file is X → put here\r\nIf file is Y → put there\r\n```\r\n\r\n**Why wrong**: Doesn''t scale, requires updates for each new file.\r\n\r\n### ✅ Pattern-based classification\r\n\r\n```\r\nIf filename matches `SETUP.md` pattern → Getting Started (priority 1)\r\nIf file in `modules/` directory → Operations\r\n```\r\n\r\n**Why right**: Works for any file, scalable.\r\n\r\n## Verification Checklist\r\n\r\nBefore committing:\r\n\r\n- [ ] Ran `find docs -name \"*.md\"` to scan actual files\r\n- [ ] All files in docs/ have corresponding entry in CLAUDE.md index\r\n- [ ] All files in docs/ have corresponding link in README.md\r\n- [ ] No references to deleted/moved files remain\r\n- [ ] Link text is consistent between CLAUDE.md and README.md\r\n- [ ] Files are in correct sections (Getting Started / Development / Operations)\r\n- [ ] Table alignment correct in CLAUDE.md\r\n- [ ] Tested: `grep` counts match actual file count\r\n\r\n## Quick Reference Commands\r\n\r\n```bash\r\n# Scan docs\r\nfind docs -name \"*.md\" -type f | sort\r\n\r\n# Detect missing in CLAUDE.md\r\ngrep -o \"\\`docs/[^)]*\\.md\\`\" CLAUDE.md | sort -u\r\n\r\n# Detect missing in README.md\r\ngrep -o \"\\](docs/[^)]*\\.md)\" README.md | sed ''s/](//'' | tr -d '')'' | sort -u\r\n\r\n# Verify all docs are indexed\r\nfind docs -name \"*.md\" -type f | while read f; do\r\n  grep -q \"$f\" CLAUDE.md || echo \"MISSING in CLAUDE.md: $f\"\r\n  grep -q \"$f\" README.md || echo \"MISSING in README.md: $f\"\r\ndone\r\n\r\n# Count check\r\necho \"Docs: $(find docs -name \"*.md\" | wc -l) | CLAUDE: $(grep -c ''\\`docs/'' CLAUDE.md) | README: $(grep -c ''](docs/'' README.md)\"\r\n```\r\n\r\n## Real-World Examples\r\n\r\n### Case 1: Added MOCK_API.md\r\n\r\n**What happened**:\r\n```bash\r\n# Created docs/MOCK_API.md\r\n# Scan detected: 9 files (was 8)\r\n# Classified: MOCK_API → Development (API-related)\r\n# Added to CLAUDE.md index\r\n# Added to README.md \"Phát triển\" section\r\n# Commit: a639438\r\n```\r\n\r\n### Case 2: Moved USERS.md → modules/AUTH.md\r\n\r\n**What happened**:\r\n```bash\r\n# git mv docs/USERS.md docs/modules/AUTH.md\r\n# Reclassified: Core doc → Module doc\r\n# Moved from \"Phát triển\" → \"Operations\" in README.md\r\n# Updated all references with git grep\r\n# Verified no old paths remain\r\n# Commit: f40ce42\r\n```\r\n\r\n## Key Takeaway\r\n\r\n**Documentation Index is a mirror, not a catalog.**\r\n\r\nWhen `docs/` changes → Update indexes immediately.\r\nNever maintain hardcoded lists.\r\nAlways scan dynamically.\r\n"},"lastSynced":"2026-03-08T02:04:13.914Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Agents needing automated README.md and CLAUDE.md index updates","zh":"适用于需要自动更新README.md和CLAUDE.md索引的文档代理","ja":"README.mdとCLAUDE.mdのインデックスを自動更新する必要があるドキュメントエージェントに適しています","ko":"README.md와 CLAUDE.md 인덱스를 자동으로 업데이트해야 하는 문서 에이전트에게 적합합니다","es":"Perfecto para Agentes de Documentación que necesitan actualizaciones automáticas de README.md y CLAUDE.md","fr":"Parfait pour les Agents de Documentation ayant besoin de mises à jour automatiques de README.md et CLAUDE.md","de":"Perfekt für Dokumentationsagenten, die automatische Updates für README.md und CLAUDE.md benötigen","pt":"Perfeito para Agentes de Documentação que precisam de atualizações automatizadas de README.md e CLAUDE.md","ru":"Идеально для агентов документации, которым требуются автоматические обновления README.md и CLAUDE.md","ar":"مثالي لعميل الوثائق الذين يحتاجون إلى تحديثات README.md و CLAUDE.md آلي"},"recommendation":{"en":"Empowers agents to dynamically scan and sync documentation indexes, ensuring accuracy and eliminating hardcoded file names, using Markdown files like README.md and CLAUDE.md","zh":"赋予代理动态扫描和同步文档索引的能力，确保准确性并消除硬编码的文件名，使用README.md和CLAUDE.md等Markdown文件","ja":"エージェントにREADME.mdやCLAUDE.mdなどのMarkdownファイルを使用して、ドキュメントインデックスを動的にスキャンおよび同期する能力を与え、精度を確保し、ハードコードされたファイル名を排除します","ko":"README.md와 CLAUDE.md 등의 Markdown 파일을 사용하여 문서 인덱스를 동적으로 스캔하고同步하는 능력을 에이전트에게 부여하며, 정확성을 보장하고 하드코딩된 파일 이름을 제거합니다","es":"Habilita a los agentes a escanear y sincronizar dinámicamente los índices de documentación, garantizando la precisión y eliminando nombres de archivos codificados, utilizando archivos Markdown como README.md y CLAUDE.md","fr":"Permet aux agents de scanner et de synchroniser dynamiquement les index de documentation, assurant l''exactitude et éliminant les noms de fichiers codés, en utilisant des fichiers Markdown comme README.md et CLAUDE.md","de":"Ermächtigt die Agenten, die Dokumentationsindizes dynamisch zu scannen und zu synchronisieren, um die Genauigkeit zu gewährleisten und codierte Dateinamen zu eliminieren, indem Markdown-Dateien wie README.md und CLAUDE.md verwendet werden","pt":"Habilita os agentes a digitalmente varrer e sincronizar índices de documentação, garantindo precisão e eliminando nomes de arquivos codificados, usando arquivos Markdown como README.md e CLAUDE.md","ru":"Наделяет агентов возможностью динамически сканировать и синхронизировать индексы документации, обеспечивая точность и устраняя жестко запрограммированные имена файлов, используя файлы Markdown, такие как README.md и CLAUDE.md","ar":"يمنح الوكلاء القدرة على مسح وتنسيق فهارس الوثائق بشكل ديناميكي، مما يضمن الدقة ويقضي على أسماء الملفات المبرمجة، باستخدام ملفات Markdown مثل README.md و CLAUDE.md"},"useCases":{"en":["Updating documentation indexes after adding new files to the docs/ directory","Syncing indexes after deleting or moving files within the docs/ directory","Automating documentation index updates to reflect the actual file structure"],"zh":["在docs/目录中添加新文件后更新文档索引","在docs/目录中删除或移动文件后同步索引","自动更新文档索引以反映实际的文件结构"],"ja":["docs/ディレクトリに新しいファイルを追加した後にドキュメントインデックスを更新する","docs/ディレクトリ内でファイルを削除または移動した後にインデックスを同期する","実際のファイル構造を反映するためにドキュメントインデックスを自動更新する"],"ko":["docs/ 디렉토리에 새로운 파일을 추가한 후 문서 인덱스를 업데이트합니다","docs/ 디렉토리 내에서 파일을 삭제하거나 이동한 후 인덱스를 동기화합니다","실제 파일 구조를 반영하기 위해 문서 인덱스를 자동으로 업데이트합니다"],"es":["Actualizar los índices de documentación después de agregar nuevos archivos al directorio docs/","Sincronizar los índices después de eliminar o mover archivos dentro del directorio docs/","Automatizar las actualizaciones de los índices de documentación para reflejar la estructura de archivos real"],"fr":["Mettre à jour les index de documentation après avoir ajouté de nouveaux fichiers au répertoire docs/","Synchroniser les index après avoir supprimé ou déplacé des fichiers à l''intérieur du répertoire docs/","Automatiser les mises à jour des index de documentation pour refléter la structure de fichiers réelle"],"de":["Dokumentationsindizes aktualisieren, nachdem neue Dateien zum Verzeichnis docs/ hinzugefügt wurden","Indizes synchronisieren, nachdem Dateien innerhalb des Verzeichnisses docs/ gelöscht oder verschoben wurden","Dokumentationsindex-Updates automatisieren, um die tatsächliche Dateistruktur widerzuspiegeln"],"pt":["Atualizar índices de documentação após adicionar novos arquivos ao diretório docs/","Sincronizar índices após excluir ou mover arquivos dentro do diretório docs/","Automatizar atualizações de índices de documentação para refletir a estrutura de arquivos real"],"ru":["Обновлять индексы документации после добавления новых файлов в директорию docs/","Синхронизировать индексы после удаления или перемещения файлов внутри директории docs/","Автоматизировать обновления индексов документации, чтобы отражать фактическую структуру файлов"],"ar":["تحديث فهارس الوثائق بعد إضافة ملفات جديدة إلى الدليل docs/","مراجعة فهارس بعد حذف أو نقل الملفات داخل الدليل docs/","توفير تحديثات فهارس الوثائق آليًا لتعكس هيكل الملفات الفعلي"]},"limitations":{"en":["Requires access to the docs/ directory and README.md and CLAUDE.md files","Only updates indexes in Markdown files"],"zh":["需要访问docs/目录和README.md和CLAUDE.md文件","仅更新Markdown文件中的索引"],"ja":["docs/ディレクトリとREADME.mdおよびCLAUDE.mdファイルへのアクセスが必要","Markdownファイル内のインデックスのみを更新します"],"ko":["docs/ 디렉토리와 README.md 및 CLAUDE.md 파일에 대한 액세스가 필요합니다","Markdown 파일 내의 인덱스만 업데이트합니다"],"es":["Requiere acceso al directorio docs/ y a los archivos README.md y CLAUDE.md","Solo actualiza los índices en archivos Markdown"],"fr":["Nécessite l''accès au répertoire docs/ et aux fichiers README.md et CLAUDE.md","N''actualise les index que dans les fichiers Markdown"],"de":["Erfordert den Zugriff auf das Verzeichnis docs/ und die Dateien README.md und CLAUDE.md","Aktualisiert nur die Indizes in Markdown-Dateien"],"pt":["Requer acesso ao diretório docs/ e aos arquivos README.md e CLAUDE.md","Atualiza apenas índices em arquivos Markdown"],"ru":["Требует доступа к директории docs/ и файлам README.md и CLAUDE.md","Обновляет только индексы в файлах Markdown"],"ar":["يتطلب الوصول إلى الدليل docs/ وملفات README.md و CLAUDE.md","تحديث الفهارس فقط في ملفات Markdown"]},"version":4},"contentHash":"a71b815a3660ad8a0d8e5c9c65f7ffaf0f63c02f6aa3c9aa141441f15eb70621","qualityScore":54}');
